  ('cpiuris2025::8232ac19470d4324a016b7622a68a6fb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo Interno e Embargos de Declaração', '## Agravo Interno e Embargos de Declaração

O agravo interno é inadmissível ou improcedente e resulta em multa para o recorrente. Os embargos de declaração objetivam a integração e correção da decisão judicial, não sendo recurso para reforma, anulação ou cassação.

### Conceitos
- **Agravo Interno**: Recurso que busca impugnar uma decisão do tribunal
- **Embargos de Declaração**: Recurso que objetiva a integração e correção da decisão judicial
- **Multa**: Pena imposta ao recorrente por inadmissibilidade ou improcedência do agravo interno

### Referências legais
- Art. 1.021, § 4º e 5º, CPC
- Art. 932, III, CPC
- Art. 489, § 1º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre agravo interno e embargos de declaração
- Conhecimento da multa para o recorrente
- Presunção de omissão da decisão judicial em determinadas hipóteses', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.446 (1)", "page_number": 446, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.021, § 4º e 5º, CPC", "Art. 932, III, CPC", "Art. 489, § 1º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:39:18.646819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=446", "doc_key": "8232ac19470d4324a016b7622a68a6fb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fee55f63afcc95df4c5f02b641ce1e4c65a38f9aeb3d52fc5b43f69352266fb6'),
  ('cpiuris2025::970d701919b0f35bd04f135bd732551b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Uso adequado dos embargos de declaração', '## Uso adequado dos embargos de declaração

Os embargos de declaração não são a via adequada para conseguir um novo julgamento dos argumentos de mérito sem a presença de vício integrativo no acórdão embargado.

### Conceitos
- **embargos de declaração**: recurso que visa alterar o julgamento do acórdão
- **vício integrativo**: fato ou circunstância que adiciona algo novo ao acórdão
- **recursos recursais**: meios processuais que visam alterar o julgamento do tribunal

### Referências legais
- Art. 1.023, caput, CPC

### Jurisprudência
- AgInt no AREsp 2.092.094/GO
- EDcl no REsp 1.501.640/SP

### Dicas de prova
- Entenda a diferença entre embargos de declaração e recursos recursais.
- Conheça o prazo para opor os embargos de declaração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.446 (2)", "page_number": 446, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.023, caput, CPC"], "jurisprudence": ["AgInt no AREsp 2.092.094/GO", "EDcl no REsp 1.501.640/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:40:07.640540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=446", "doc_key": "970d701919b0f35bd04f135bd732551b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c7017798d03b5e1528d6ed3e772578aed5dc3786e530a34662751a17031f1fe2'),
  ('cpiuris2025::9429b79aa50830051ea7132fdc3f5708', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Interruptivo dos Embargos de Declaração', '## Efeito Interruptivo dos Embargos de Declaração

O efeito interruptivo dos embargos de declaração é um conceito jurídico que afirma que a mera oposição de embargos tempestivos interrompe o prazo para os demais recursos cabíveis. No entanto, recentemente o STJ posicionou-se no sentido de que a ausência de indicação da existência do erro na peça de embargos implica no não conhecimento do recurso.

### Conceitos
- **Efeito Interruptivo**: O efeito interruptivo de um recurso, que interrompe o prazo para os demais recursos cabíveis.
- **Tempestividade**: A tempestividade é a oportunidade de opor embargos dentro do prazo estabelecido pela lei.
- **Indicação da Existência do Erro**: A indicação da existência do erro na peça de embargos é necessária para que o recurso seja considerado tempestivo.
- **Omissão**: A omissão em uma peça de embargos pode ser considerada como falta de indicação da existência do erro.
- **Contradição**: A contradição em uma peça de embargos pode ser considerada como falta de indicação da existência do erro.
- **Desistência do Recurso**: A desistência do recurso não é considerada como produzindo efeito interruptivo.
- **Aclaratórios**: Os aclaratórios opostos podem ser considerados como parte do processo, mas não são necessários para o conhecimento do recurso.

### Referências legais
- Art. 1.023, caput, CPC
- Súmula 474/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Efeito Interruptivo dos Embargos de Declaração

### Dicas de prova
- Pergunte sobre o efeito interruptivo dos embargos de declaração e como ele é afetado pela ausência de indicação da existência do erro na peça de embargos.
- Entenda a diferença entre tempestividade e falta de indicação da existência do erro em uma peça de embargos.
- Conheça as regras para o julgamento dos embargos de declaração, incluindo o julgamento colegiado e a resolução por órgão fracionário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.447 (1)", "page_number": 447, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.023, caput, CPC", "Súmula 474/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Efeito Interruptivo dos Embargos de Declaração"], "confidence": 0.8, "extracted_at": "2026-05-28T05:41:28.424119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=447", "doc_key": "9429b79aa50830051ea7132fdc3f5708"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f1d6836011f29379dca847a686f360b50c8f7ab2a4d7ab1dfab3c9256a2ba365'),
  ('cpiuris2025::66a4ee191bf9af027ded4a9be998bd29', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Aclaratórios em recurso cabível', '## Aclaratórios em recurso cabível

Se uma parte opõe embargos de declaração e a outra interpõe o recurso cabível, os aclaratórios podem ser acolhidos com modificação ou rejeitados sem modificação.

### Conceitos
- **embargos de declaração**: Ação apresentada por uma parte para questionar decisões do juiz
- **recurso cabível**: Ação apresentada por uma parte para apelar decisão do juiz
- **aclaratórios**: Elementos adicionais apresentados pelas partes para esclarecer suas razões

### Referências legais
- Art. 1.024, § 4º

### Jurisprudência
- REsp 1.522.347/ES
- EDcl no AgInt nos EAREsp 1.064.251/GO
- REsp 1.833.120/SP
- AgRg no AREsp 2.173.912/RJ
- AgInt no AREsp 1.802.201/GO
- EREsp 1.265.625/SP

### Dicas de prova
- Entenda a diferença entre embargos de declaração e recurso cabível.
- Conheça o prazo para apresentar aclaratórios após julgamento dos embargos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.447 (2)", "page_number": 447, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.024, § 4º"], "jurisprudence": ["REsp 1.522.347/ES", "EDcl no AgInt nos EAREsp 1.064.251/GO", "REsp 1.833.120/SP", "AgRg no AREsp 2.173.912/RJ", "AgInt no AREsp 1.802.201/GO", "EREsp 1.265.625/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:42:18.812298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=447", "doc_key": "66a4ee191bf9af027ded4a9be998bd29"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f0cefb91a27b42102e5e380d40158308ce6972b85e8246dc3238099af42bdaa3'),
  ('cpiuris2025::c29680f8f865624ffb3405129ddffdd5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prequestionamento e Embargos de Declaração', '## Prequestionamento e Embargos de Declaração

O prequestionamento é um requisito para a admissibilidade dos recursos excepcionais. Os embargos de declaração são instrumento hábil à satisfação do requisito constitucional da causa decidida, mas não garantem o conhecimento do recurso excepcional se a questão federal ou constitucional não for examinada pelo Tribunal em 2º grau.

### Conceitos
- **Prequestionamento**: Requisito para a admissibilidade dos recursos excepcionais
- **Embargos de Declaração**: Instrumento hábil à satisfação do requisito constitucional da causa decidida
- **Omissão Judicial**: Falta de enfrentamento de uma determinada questão federal ou constitucional pelo Tribunal em 2º grau

### Referências legais
- Art. 102, III, CF/88
- Art. 105, III, CF/88
- Art. 1.025, CPC/15

### Jurisprudência
- Súmula 356/STF
- Súmula 211/STJ

### Dicas de prova
- Entenda a importância do prequestionamento e como os embargos de declaração se relacionam com ele.
- Conheça as regras sobre omissão judicial e sua relação com a admissibilidade dos recursos excepcionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.448 (1)", "page_number": 448, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, III, CF/88", "Art. 105, III, CF/88", "Art. 1.025, CPC/15"], "jurisprudence": ["Súmula 356/STF", "Súmula 211/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:43:23.949552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=448", "doc_key": "c29680f8f865624ffb3405129ddffdd5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '569f965fd4ce78e5e02a573f30bc13bfbe35eb793d99da8e32a0e57fd1eaec52'),
  ('cpiuris2025::617ec449cb03df3f30bb35b6124a2b5d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Obrigação de alegar violações legais em recurso especial', '## Obrigação de alegar violações legais em recurso especial

A parte recorrente deve obrigatoriamente alegar violação dos dispositivos legais art. 1.022 e 1.025 do CPC para discutir negativa de prestação jurisdicional no recurso especial.

### Conceitos
- **Recurso Especial**: Ação que visa apelar uma decisão do juiz de primeiro grau
- **Prestação Jurisdicional**: O dever do juiz de prover a justiça ao litigante
- **Violação Legal**: O ato de não cumprir uma norma legal

### Referências legais
- Art. 1.022 do CPC/15
- Art. 1.025 do CPC/15

### Jurisprudência
- REsp 1.915.277/RJ
- REsp 1.639.314/MG

### Dicas de prova
- Distinção entre art. 1.022 e 1.025 do CPC
- Obrigação de alegar violações legais em recurso especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.448 (2)", "page_number": 448, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.022 do CPC/15", "Art. 1.025 do CPC/15"], "jurisprudence": ["REsp 1.915.277/RJ", "REsp 1.639.314/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T05:44:02.445529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=448", "doc_key": "617ec449cb03df3f30bb35b6124a2b5d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fa72cde58a7f38bb4d37b3c6c0246af76762a793ebc90d3f51fcd065e193d8f8'),
  ('cpiuris2025::9adc0cb87372fe01e9862d417f82c918', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos dos Embargos de Declaração', '## Efeitos dos Embargos de Declaração

Resumo do artigo sobre os efeitos dos embargos de declaração em processos judiciais, incluindo efeito suspensivo, regressivo, interruptivo, modificativo ou infringente.

### Conceitos
- **Efeito Suspensivo**: Hábito de não proceder com a execução da decisão até que o recurso seja julgado
- **Efeito Regressivo**: O efeito que impede a propositura de novos recursos após a decisão do embargos de declaração
- **Efeito Interruptivo**: Há interrupção do prazo para a propositura de novos recursos, mas não afeta as defesas apresentadas
- **Efeito Modificativo ou Infringente**: Altera o conteúdo da decisão embargada em casos específicos, como omissões relevantes

### Referências legais
- Art. 1.022 do CPC/2015
- Art. 1.026, caput e § 1º do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e regressivo
- Conheça as hipóteses de reiteração de embargos de declaração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.449 (1)", "page_number": 449, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.022 do CPC/2015", "Art. 1.026, caput e § 1º do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:44:55.532578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=449", "doc_key": "9adc0cb87372fe01e9862d417f82c918"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4d4c38782318ef91ef95b29dcba4e7e8e4fc00356b2165214b89d4b8f634ff4e'),
  ('cpiuris2025::203b170ae57101eee47f3d4a3b81e77d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Multas nas Embargos de Declaração', '## Multas nas Embargos de Declaração

A reiteração dos embargos de declaração pode gerar multa, que é inicialmente de até 2% sobre o valor atualizado da causa e pode ser elevada a até 10% se os embargos também forem considerados protelatórios.

### Conceitos
- **Multas nas Embargos de Declaração**: A reiteração dos embargos de declaração pode gerar multa.
- **Valor da Multa**: É calculado sobre o valor atualizado da causa, inicialmente até 2% e até 10% em caso de reiteração.
- **Protelatório**: O recurso ou embargos são considerados manifestamente protelatórios se alegam demora injustificada para julgamento.
- **Depósito da Multa**: É condicionado à interposição de qualquer recurso.
- **Recurso Protelatório**: O primeiro recurso reputado como protelatório é o que determina a multa inicialmente.
- **Embargos de Declaração**: São recursos interpostos após a decisão do recurso principal.
- **Multa**: É a sanção imposta pelo juiz por considerar o recurso ou embargos como manifestamente protelatórios.

### Referências legais
- Art. 1.026, § 2º, CPC

### Jurisprudência
- REsp 1.822.287/PR
- REsp 1.805.898/MS
- REsp 1.817.845/MS
- EDcl no AgInt no AREsp 2.222.062/DF

### Dicas de prova
- Pergunte sobre a multa nas embargos de declaração e como ela é calculada.
- Entenda o conceito de protelatório e como ele afeta a multa.
- Lembre-se de que o depósito da multa é condicionado à interposição de qualquer recurso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.449 (2)", "page_number": 449, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.026, § 2º, CPC"], "jurisprudence": ["REsp 1.822.287/PR", "REsp 1.805.898/MS", "REsp 1.817.845/MS", "EDcl no AgInt no AREsp 2.222.062/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T05:46:12.950769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=449", "doc_key": "203b170ae57101eee47f3d4a3b81e77d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '35b774fdae800f2306496003910a1488d466743ba83ae142ec6aeb621f6cbdc5'),
  ('cpiuris2025::c90406717f56899469f18633280bd0fc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso especial e recurso extraordinário', '## Recurso especial e recurso extraordinário

Resumo sobre os recursos excepcionais no sistema de impugnação das decisões judiciais.

### Conceitos
- **Recursos excepcionais**: Gênero que inclui o especial e o extraordinário
- **Objetivos dos recursos excepcionais**: Uniformização do entendimento acerca da interpretação do direito federal ou constitucional, formação de precedentes e segurança jurídica
- **Fundamentação vinculada**: Recurso que se baseia em questões essencialmente de direito
- **Devolutividade restrita**: Recurso que não se presta ao reexame de todo e qualquer vício

### Referências legais
- Art. 102, III da CF/88
- Art. 105, III da CF/88

### Dicas de prova
- Entenda a diferença entre recursos especiais e extraordinários.
- Conheça as hipóteses de cabimento dos recursos excepcionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.450 (1)", "page_number": 450, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, III da CF/88", "Art. 105, III da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:46:59.053619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=450", "doc_key": "c90406717f56899469f18633280bd0fc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '895993b19817e02810d6e181d74f565f69723a0860cde35adcbf78892909c1a7'),
  ('cpiuris2025::e56d2a512dbb13dcb54133b76695c9e7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Extraordinário e Recurso Especial', '## Recurso Extraordinário e Recurso Especial

Recurso extraordinário é usado para julgar decisões em única ou última instância que contrariam a Constituição. O Superior Tribunal de Justiça (STJ) tem competência para julgar causas decididas por Tribunais Regionais Federais e tribunais dos Estados, quando a decisão recorrida contraria tratado ou lei federal.

### Conceitos
- **Recurso Extraordinário**: Ação que visa julgar decisões em única ou última instância que contrariam a Constituição.
- **Recurso Especial**: Ação que visa julgar decisões de Tribunais Regionais Federais e tribunais dos Estados, quando a decisão recorrida contraria tratado ou lei federal.
- **Competência do STJ**: O Superior Tribunal de Justiça tem competência para julgar causas decididas por Tribunais Regionais Federais e tribunais dos Estados.

### Referências legais
- Art. 105, III, da Constituição Brasileira

### Jurisprudência
- AgInt nos EDcl no AREsp 1.817.240/PR, 3ª Turma, DJe 25/06/2021, rel. Ministra Nancy Andrighi

### Dicas de prova
- Distinção entre Recurso Extraordinário e Recurso Especial
- Conhecimento da competência do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.450 (2)", "page_number": 450, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 105, III, da Constituição Brasileira"], "jurisprudence": ["AgInt nos EDcl no AREsp 1.817.240/PR, 3ª Turma, DJe 25/06/2021, rel. Ministra Nancy Andrighi"], "confidence": 0.8, "extracted_at": "2026-05-28T05:47:47.901033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=450", "doc_key": "e56d2a512dbb13dcb54133b76695c9e7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b4aac40690ee4f70c962ce8da6bff5c8675dc4fd92af4220d08db18066ff28ff'),
  ('cpiuris2025::a0c815270327889a30f8a7571ee61623', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pressupostos de admissibilidade comuns a ambos os recursos excepcionais', '## Pressupostos de admissibilidade comuns a ambos os recursos excepcionais

São examinados pressupostos de admissibilidade, além dos estudados na teoria geral dos recursos, mais requisitos específicos dos recursos excepcionais.

### Conceitos
- **Prequestionamento**: Requisito do recurso especial que o acórdão recorrido deva abordar a questão objeto da decisão
- **Questão de direito**: Requisito do recurso especial que o tema objeto da decisão seja uma questão de direito federal ou constitucional
- **Precedente**: Opinião do STJ sobre a possibilidade de superar omissão existente no acórdão local quando a questão é objeto de pacífica jurisprudência

### Referências legais
- Art. 105, III, ''a'', ''b'' e ''c'', Código de Processo Civil
- Súmula 284/STF
- Súmula 7 do STJ
- Súmula 279 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre prequestionamento e questão de direito

### Dicas de prova
- Entenda a importância do prequestionamento no recurso especial
- Distinga entre questões de fato e questões de direito
