  ('cpiuris2025::3e793fbc576cb9c07dc30d711f1a772f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reexame de Prova e Exaurimento das Vias Ordinárias', '## Reexame de Prova e Exaurimento das Vias Ordinárias

Superiores não examinam os fatos, mas podem atribuir valor jurídico a fatos incontroversos e decidir sobre regras jurídicas aplicáveis.

### Conceitos
- **Reexame de Prova**: Ato pelo qual o juiz revisa as provas apresentadas pelas partes
- **Exaurimento das Vias Ordinárias**: O esgotamento de todas as vias legais cabíveis para impugnar uma decisão
- **Requalificação Jurídica dos Fatos**: A atribuição de valor jurídico a fatos incontroversos

### Referências legais
- Art. 485, Código de Processo Civil
- Súmula 7, STJ

### Jurisprudência
- REsp 1.672.966/MG
- REsp 1.893.057/MG
- Súmula 279, STF

### Dicas de prova
- Entenda a diferença entre reexame de prova e exaurimento das vias ordinárias
- Conheça as regras para a requalificação jurídica dos fatos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.451 (2)", "page_number": 451, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, Código de Processo Civil", "Súmula 7, STJ"], "jurisprudence": ["REsp 1.672.966/MG", "REsp 1.893.057/MG", "Súmula 279, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T05:49:37.300523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=451", "doc_key": "3e793fbc576cb9c07dc30d711f1a772f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'eef2cde35b2b24b83bf9ff7bd53ab68b7d8830fe20d85cfc77d5f2768af5a959'),
  ('cpiuris2025::af783dc50315c963af2818cf871a73a8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Repercussão Geral no Recurso Extraordinário', '## Repercussão Geral no Recurso Extraordinário

A repercussão geral é um pressuposto de admissibilidade específico do recurso extraordinário dirigido ao STF, que se aplica em razão da matriz constitucional e ultrapassa os interesses subjetivos do processo.

### Conceitos
- **Repercussão Geral**: Pressuposto de admissibilidade específico do recurso extraordinário
- **Mátriz Constitucional**: Razão pela qual a repercussão geral se aplica
- **Interesses Subjetivos**: O que não é considerado na análise da repercussão geral
- **Tese Transcendente**: Uma questão que atinge toda a sociedade

### Referências legais
- Art. 102, § 3º, CF/88
- Art. 1.035, § 1º, CPC
- Art. 987, § 1º, CPC

### Jurisprudência
- Súmula 281/STF

### Dicas de prova
- Entenda a noção de repercussão geral e sua importância no recurso extraordinário
- Identifique os requisitos para que a questão constitucional tenha repercussão geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.452 (1)", "page_number": 452, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, § 3º, CF/88", "Art. 1.035, § 1º, CPC", "Art. 987, § 1º, CPC"], "jurisprudence": ["Súmula 281/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T05:50:26.212167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=452", "doc_key": "af783dc50315c963af2818cf871a73a8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b0df85a40a4a70c402acfe7334d2ddf121f42b19103a73a72a639c64644f2fe4'),
  ('cpiuris2025::d04b0447d673ed5590d4ec351ce56c4e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sobrestamento de processos em recurso extraordinário', '## Sobrestamento de processos em recurso extraordinário

Reconhecida a repercussão geral, o Pleno do STF pode suspender todos os processos pendentes sobre a questão, mas isso não é automatico e depende da decisão do relator.

### Conceitos
- **repercussão geral**: ocorrência que justifica a competência do Pleno do STF
- **suspensão de processos**: ato do Pleno do STF que pausa o andamento dos processos pendentes sobre uma questão
- **discricionário**: decisão do relator que não depende de um critério objetivo
- **sobrestamento**: ação do Pleno do STF que atrasa o andamento dos processos pendentes sobre uma questão

### Referências legais
- Art. 1.035, § 5º, CPC
- Art. 1.035, § 6º, CPC
- Art. 1.035, § 7º, CPC

### Jurisprudência
- Súmula 281, STF

### Dicas de prova
- Entenda a diferença entre suspensão e sobrestamento de processos
- Conheça o papel do relator na decisão sobre a suspensão dos processos
- Aprenda a importância da repercussão geral para a competência do Pleno do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.452 (2)", "page_number": 452, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.035, § 5º, CPC", "Art. 1.035, § 6º, CPC", "Art. 1.035, § 7º, CPC"], "jurisprudence": ["Súmula 281, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T05:51:28.633330+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=452", "doc_key": "d04b0447d673ed5590d4ec351ce56c4e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8ec73edd086c228d05956cd5488ce65d36bd851e4dd25bf9ab4b247db22e563b'),
  ('cpiuris2025::2b6a77712bbbd27d53f11c974e43822d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pressuposto de admissibilidade específico do recurso especial – relevância da questão federal', '## Pressuposto de admissibilidade específico do recurso especial – relevância da questão federal

A relevância da questão federal é um filtro adicional de admissibilidade do recurso especial, mas ainda não há legislação regulamentadora desse instituto.

### Conceitos
- **Relevância da questão federal**: Filtro adicional de admissibilidade do recurso especial
- **Pressuposto de admissibilidade específico**: Requisito para a admissão do recurso especial
- **Risco de uniformização**: A possibilidade de o STJ não uniformizar uma questão de direito federal

### Referências legais
- Art. 1.035, § 8º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de relevância da questão federal e seu papel na admissibilidade do recurso especial
- Conheça o risco de uniformização e como ele se relaciona com a relevância da questão federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.453 (1)", "page_number": 453, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.035, § 8º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:52:11.822384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=453", "doc_key": "2b6a77712bbbd27d53f11c974e43822d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5fac5ed593262be4621f5e7b4525311d85203d15b3f2c50c6f781caadb042b83'),
  ('cpiuris2025::7c7e9732e9b596107c4caa55016bb169', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Presunção de Relevância nos Recursos Especiais', '## Presunção de Relevância nos Recursos Especiais

A presunção de relevância nas questões federais é absoluta em certas hipóteses, como recursos especiais em ações penais ou que possam gerar inelegibilidade.

### Conceitos
- **Presunção de Relevância**: Conceito jurídico que permite a admissão automática de questões federais em recursos especiais
- **Hipótese Absoluta**: Situação em que a presunção de relevância é absoluta, sem necessidade de demonstração
- **Hipótese Relativa**: Situação em que a presunção de relevância é relativa e requer demonstração para sua admissão

### Referências legais
- Art. 105, § 2º da CF/88

### Jurisprudência
- RE 123456
- Enunciado Administrativo nº 8 do STJ

### Dicas de prova
- Entenda a diferença entre hipótese absoluta e relativa de presunção de relevância
- Conheça as hipóteses em que a presunção de relevância é absoluta ou relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.453 (2)", "page_number": 453, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 105, § 2º da CF/88"], "jurisprudence": ["RE 123456", "Enunciado Administrativo nº 8 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:52:52.894709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=453", "doc_key": "7c7e9732e9b596107c4caa55016bb169"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '82b9d3c39efa5fa55ac3fff602cf1d7a344ca51db149ae4d9bceb77d745e0a3b'),
  ('cpiuris2025::ce004be9ef071528810495ca582cd5ae', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Suspensivo nos Recursos Especiais', '## Efeito Suspensivo nos Recursos Especiais

O recurso especial não possui efeito suspensivo ope legis, mas pode ter efeito suspensivo ope judicis com determinados requisitos.

### Conceitos
- **Recurso Especial**: Ação que visa revisar uma decisão do tribunal de primeiro grau
- **Efeito Suspensivo**: Medida processual que suspende a execução de uma decisão ou acórdão
- **Ope Legis**: Efeito suspensivo concedido pelo legislador
- **Ope Judicis**: Efeito suspensivo concedido pelo juiz
- **Tutela Provisória**: Medida processual que suspende a execução de uma decisão ou acórdão até que seja tomada uma decisão final

### Referências legais
- Art. 995, caput, CPC
- Art. 1.029, § 5º, CPC
- Art. 105, parágrafo 2º, da Constituição Federal

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência para conceder efeito suspensivo nos recursos especiais

### Dicas de prova
- Entenda a diferença entre ope legis e ope judicis
- Conheça os requisitos para a atribuição de efeito suspensivo nos recursos especiais
- Aprenda a aplicar a regra do art. 995, parágrafo único, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.454 (1)", "page_number": 454, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 995, caput, CPC", "Art. 1.029, § 5º, CPC", "Art. 105, parágrafo 2º, da Constituição Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência para conceder efeito suspensivo nos recursos especiais"], "confidence": 0.8, "extracted_at": "2026-05-28T05:54:03.222214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=454", "doc_key": "ce004be9ef071528810495ca582cd5ae"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '115e853a8e869cf3d30c8211e6add185903c99d6ffa4bc0aec6960c1fbc8c018'),
  ('cpiuris2025::eb0eb24ddf9f3a122cc417c0c8d90de7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Excepcional', '## Recurso Excepcional

Os recursos excepcionais possuem devolutividade bastante restrita, especialmente na perspectiva da profundidade. A flexibilização da exigência de prequestionamento é permitida pelo art. 1.034, caput e parágrafo único, CPC, e pela Súmula 456 do STF.

### Conceitos
- **devolutividade**: A capacidade de um recurso de ser apresentado ao tribunal para que ele possa decidir sobre a questão
- **prequestionamento**: O ato de prestar clareza e precisão às questões de direito envolvidas no recurso
- **exigência de causa decidida**: A necessidade de que o tribunal decida sobre uma questão específica antes de julgar o recurso

### Referências legais
- Art. 1.034, caput e parágrafo único, CPC

### Jurisprudência
- Súmula 456 do STF
- AgInt na TP 2.203/PR
- AgInt na TP 12.712/SP

### Dicas de prova
- Entenda a devolutividade e o prequestionamento nos recursos excepcionais
- Conheça as hipóteses de cabimento e pressupostos adicionais de admissibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.454 (2)", "page_number": 454, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.034, caput e parágrafo único, CPC"], "jurisprudence": ["Súmula 456 do STF", "AgInt na TP 2.203/PR", "AgInt na TP 12.712/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:54:47.931774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=454", "doc_key": "eb0eb24ddf9f3a122cc417c0c8d90de7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '709bf1bea010661cd7723113ec4ff5ad8894ba6024a68f65331912b4e6091b97'),
  ('cpiuris2025::2ef25bbff0c930bf0e733edf79732b7b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prequestionamento e Devolutividade dos Recursos Excepcionais', '## Prequestionamento e Devolutividade dos Recursos Excepcionais

O prequestionamento é matéria relacionada à admissibilidade, mas ultrapassado o juízo de admissibilidade, a cognição dos Tribunais Superiores é ampliada para todo o capítulo decisório impugnado. O recurso especial pode discutir inicialmente questões que não foram decididas.

### Conceitos
- **Prequestionamento**: Materia relacionada à admissibilidade
- **Devolutividade dos Recursos Excepcionais**: Cognição ampliada para todo o capítulo decisório impugnado
- **Recurso Especial**: Recurso que pode discutir questões não decididas
- **Procedimento**: Sublinha-se a importância do procedimento nos recursos excepcionais

### Referências legais
- Art. 526 Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 497 STJ

### Dicas de prova
- Pergunte se o recurso especial pode discutir questões não decididas
- Entenda a importância do procedimento nos recursos excepcionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.455 (1)", "page_number": 455, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 526 Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 497 STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:55:34.026608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=455", "doc_key": "2ef25bbff0c930bf0e733edf79732b7b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '97e41f24500fd32f544cd874b04ac0c79ba9bc3e1b46244331629a7481e8d493'),
  ('cpiuris2025::4d735d41802d0f1e5986bb7facb8e28c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Excepcional e Admissibilidade', '## Recurso Excepcional e Admissibilidade

O recurso excepcional pode ser admitido nos Tribunais Locais, com possibilidade de resposta aos recursos interpostos e até mesmo com a possibilidade de interposição de recurso especial ou extraordinário adesivo. O resultado do primeiro juízo de admissibilidade determinará o caminho do recurso excepcional.

### Conceitos
- **Recurso Excepcional**: Ação que pode ser interposta em caso de dúvida sobre a competência do Tribunal.
- **Admissibilidade**: O processo de avaliação da legitimidade e procedência do recurso excepcional.
- **Tribunais Locais**: Tribunais que têm competência para julgar os recursos excepcionais.
- **Recurso Especial**: Ação que pode ser interposta para revisar a decisão do Tribunal de Segunda Instância.
- **Recurso Extraordinário**: Ação que pode ser interposta para revisar a decisão do Tribunal de Segunda Instância em casos excepcionais.
- **STJ**: Superior Tribunal de Justiça, que tem competência para julgar os recursos especiais e extraordinários.
- **STF**: Supremo Tribunal Federal, que tem competência para julgar os recursos extraordinários.

### Referências legais
- Art. 1.030, caput, CPC

### Jurisprudência
- RE 123456
- EResp 595.742/SC

### Dicas de prova
- Pergunte sobre a competência dos Tribunais Locais para julgar recursos excepcionais.
- Entenda a diferença entre recurso especial e extraordinário.
- Conheça o papel do STJ e STF na adesão de recursos excepcionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.455 (2)", "page_number": 455, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.030, caput, CPC"], "jurisprudence": ["RE 123456", "EResp 595.742/SC"], "confidence": 0.8, "extracted_at": "2026-05-28T05:56:44.089794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=455", "doc_key": "4d735d41802d0f1e5986bb7facb8e28c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a07eef12ae7085e112ace3850a1ff54a09b5dd82cd9f75e662b738cf9deab071'),
  ('cpiuris2025::8a63461c18423301e6c7ddaf8581499a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Excepcional e Inadmissibilidade', '## Recurso Excepcional e Inadmissibilidade

O recurso excepcional tem diferentes causas de inadmissibilidade, que podem ser conhecidas ou não conhecidas pelo Tribunal local. As hipóteses de inadmissibilidade são: questão constitucional já decidida pela STF; acórdão conforme entendimento do STF firmado em regime de repercussão geral; impugnação de acórdão conforme entendimento do STJ firmado em julgamento no regime de repetitivo; ou não apresentação dos requisitos de admissibilidade.

### Conceitos
- **Recurso Excepcional**: recurso que impugna acórdão e pode ser extraordinário ou especial
- **Inadmissibilidade Recursal**: fato que impede o conhecimento do recurso excepcional pelo Tribunal local
- **Repercussão Geral**: decisão da STF que torna questão constitucional vinculante para os Tribunais Superiores
- **Regime de Repetitivo**: regime jurídico que permite a repetição de decisões da STJ e do STF

### Referências legais
- Art. 1.030, I, a, CPC
- Art. 1.030, I, b, CPC
- Art. 1.030, V, CPC

### Dicas de prova
- Entenda a diferença entre recurso especial e extraordinário
- Conheça as hipóteses de inadmissibilidade do recurso excepcional
- Aprenda sobre o regime de repercussão geral e repetitivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.456 (1)", "page_number": 456, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.030, I, a, CPC", "Art. 1.030, I, b, CPC", "Art. 1.030, V, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:57:44.635146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=456", "doc_key": "8a63461c18423301e6c7ddaf8581499a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cc60a590f0202c16d40c6e351c3284c87049d898a0cacd102f22f341595a788b'),
  ('cpiuris2025::51ecd41bb8a57e0dd7cbb884586d0d33', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Interruptivo dos Embargos de Declaração', '## Efeito Interruptivo dos Embargos de Declaração

O recurso cabível contra a decisão que inadmite um recurso excepcional é o agravo interno, especialmente nas hipóteses do art. 1.030, I, a e b.

### Conceitos
- **Efeito Interruptivo**: Ocorre quando o prazo para os recursos subsequentes é interrompido
- **Embargos de Declaração**: Recurso excepcional oposto em face da decisão que inadmite um recurso excepcional
- **Preclusão**: Ocorre quando não pode ser conhecida uma ação ou recurso após determinado prazo

### Referências legais
- Art. 1.030, I, a e b do Código de Processo Civil
- 499

### Jurisprudência
- AgRg no Ag 1.341.818/RS
- AgInt no MS 25.013/DF
