  ('cpiuris2025::da26a5ec7aaa1b0b2bcacb08b1851466', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo em Recurso Especial e Extraordinário', '## Agravo em Recurso Especial e Extraordinário

O agravo é um recurso cabível contra decisão de inadmissão do recurso especial ou extraordinário, com finalidade de destrancar o recurso ao STJ ou STF.

### Conceitos
- **Agravo**: Recurso cabível contra decisão de inadmissão do recurso especial ou extraordinário
- **Recurso Especial**: Recurso apresentado ao STJ para impugnar decisões do TRF
- **Recurso Extraordinário**: Recurso apresentado ao STF para impugnar decisões do STJ
- **Agravo Denegatório**: Substituto do agravo, com finalidade de impugnar fundamentos adotados pelo Tribunal de origem

### Referências legais
- Art. 1.042, CPC

### Jurisprudência
- Súmula 7 do STJ
- Súmula 221 do STJ
- Súmula 7502 do STJ
- Súmula 211 do STJ
- Súmula 284 do STF
- Súmula 182 do STJ

### Dicas de prova
- Entenda a finalidade do agravo e sua diferença com o agravo denegatório
- Conheça as regras para impugnar fundamentos adotados pelo Tribunal de origem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.457 (1)", "page_number": 457, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.042, CPC"], "jurisprudence": ["Súmula 7 do STJ", "Súmula 221 do STJ", "Súmula 7502 do STJ", "Súmula 211 do STJ", "Súmula 284 do STF", "Súmula 182 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:59:30.086507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=457", "doc_key": "da26a5ec7aaa1b0b2bcacb08b1851466"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd9209493d15dfc265248a683c038c803be860a65d14b30206648f718b83b23bb'),
  ('cpiuris2025::8ba0eaebc0d868025816016f019c4fd3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Afastabilidade da fundamentação em decisões judiciais', '## Afastabilidade da fundamentação em decisões judiciais

A fundamentação de uma decisão não é afastável, mas a parte dispositiva pode ser, sendo o recurso necessário impugnar a decisão integralmente.

### Conceitos
- **Afastabilidade**: O direito de uma parte de questionar a validade de uma parte da decisão do juiz.
- **Fundamentação**: A razão que justifica a decisão do juiz.
- **Parte dispositiva**: A parte da decisão que contém a solução do litígio.
- **Recurso**: O meio pelo qual uma parte pode questionar a decisão do juiz.

### Referências legais
- Art. 1.042, § 2º e 3º, CPC

### Jurisprudência
- Súmula 7, STJ
- Súmula 211, STJ
- Súmula 284, STF
- Súmula 182, STJ
- EAREsp 746.775/PR

### Dicas de prova
- Entenda a diferença entre fundamentação e parte dispositiva.
- Conheça as regras de recurso nos termos do CPC.
- Afastabilidade da fundamentação não é afastável, mas a parte dispositiva pode ser.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.457 (2)", "page_number": 457, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.042, § 2º e 3º, CPC"], "jurisprudence": ["Súmula 7, STJ", "Súmula 211, STJ", "Súmula 284, STF", "Súmula 182, STJ", "EAREsp 746.775/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T06:00:15.668893+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=457", "doc_key": "8ba0eaebc0d868025816016f019c4fd3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f4a49a80277109676a091ba133b855cc2f1a5446cbb7cf74a87a0b643aa4c25b'),
  ('cpiuris2025::3283dd06ac2d73855d5163f7c89a9384', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo e Recursos nos Tribunais Superiores', '## Agravo e Recursos nos Tribunais Superiores

O artigo 1.042, § 5º, do CPC estabelece que o agravo pode ser julgado conjuntamente com o recurso especial ou extraordinário, assegurando sustentação oral, mas a interpretação é divergente entre a jurisprudência do STJ.

### Conceitos
- **Agravo**: Recurso que pode ser apresentado para impugnar uma decisão judicial
- **Recurso Especial**: Recurso apresentado para impugnar uma decisão de tribunal inferior
- **Recurso Extraordinário**: Recurso apresentado para impugnar uma decisão de tribunal superior
- **Sustentação Oral**: Argumentação oral feita perante o tribunal em um recurso
- **Julgamento Colegiado**: Julgamento realizado por mais de um juiz

### Referências legais
- Art. 1.042, § 5º, CPC

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre agravo e recurso especial/extraordinário
