  ('cpiuris2025::a59bd4df6fcdc5e9c173abaec415178f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Extraordinário', '## Recurso Extraordinário

Quando ambos os recursos excepcionais são interpostos, o julgamento inicia-se pelo recurso especial no STJ e é remetido ao STF para julgamento do recurso extraordinário.

### Conceitos
- **Recurso Extraordinário**: Ação que busca revisar uma decisão final de um tribunal inferior
- **Recurso Especial**: Ação que busca revisar uma decisão final do STJ
- **Recurso Ordinário**: Ação que busca revisar uma decisão final de um tribunal inferior, mas não é o recurso extraordinário
- **STJ**: Superior Tribunal de Justiça
- **STF**: Supremo Tribunal Federal

### Referências legais
- Art. 1.031, caput, CPC

### Jurisprudência
- Súmula 126, STJ

### Dicas de prova
- Entenda a ordem de prioridade dos recursos excepcionais
