  ('cpiuris2025::56e524f796fbfac9c71dd177dc14d750', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Redirecionamento de recursos excepcionais', '## Redirecionamento de recursos excepcionais

Descreve o processo de redirecionamento de recursos excepcionais entre STJ e STF, incluindo prazos para aditivo e julgamento.

### Conceitos
- **Recurso Extraordinário**: Recurso apresentado ao STF contra decisão do STJ
- **Recurso Especial**: Recurso apresentado ao STJ contra decisão de tribunal inferior
- **Redirecionamento**: Mecanismo que permite o retorno do recurso excepcional ao STJ para julgamento especial

