  ('cpiuris2025::5ed89c4af942bb67831961876f3431f9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso de Divergência em Classes Processuais Distintas', '## Recurso de Divergência em Classes Processuais Distintas

O recurso de divergência é cabível quando um acórdão de órgão fracionário do Tribunal Superior diverge do julgamento de outro órgão do mesmo Tribunal, desde que ambos sejam de mérito.

### Conceitos
- **Recurso de Divergência**: Procedimento utilizado para discordar de acórdão de órgão fracionário
- **Classes Processuais Distintas**: Diferentes categorias de processos que podem ser julgados por diferentes órgãos do Tribunal Superior
- **Mérito**: A questão de fato e direito que é objeto da controvérsia entre as partes

### Referências legais
- Art. 1.043, I, CPC

### Jurisprudência
- AgInt na PET 14.925/TO
- ...

### Dicas de prova
- Distinção entre recurso de divergência e embargos de divergência
- Importância da competência do órgão prolator do acórdão paradigmA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.459 (2)", "page_number": 459, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.043, I, CPC"], "jurisprudence": ["AgInt na PET 14.925/TO", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:03:28.327566+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=459", "doc_key": "5ed89c4af942bb67831961876f3431f9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '26bdf6b81a14fa027060053b9270d48768bcfe25b1e7f9405314461ea5e770e7'),
  ('cpiuris2025::00ebda589ec21b6fe6bd783eccdea3cd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cabimento dos Embargos de Divergência', '## Cabimento dos Embargos de Divergência

Resumo objetivo: Discute as hipóteses em que os embargos de divergência são cabíveis, considerando a Súmula 158 do STJ e o CPC.

### Conceitos
- **Súmula 158 do STJ**: Enunciado sumular que afirma não conhecer o recurso
- **CPC (Código de Processo Civil)**: Lei que regula os procedimentos processuais no Brasil
- **Embargos de Divergência**: Recurso apresentado para divergir da decisão do órgão julgador
- **Acórdão Embargável**: Acórdão que é objeto de embargos de divergência
- **Súmula 598/STF**: Enunciado sumular que afirma a aplicabilidade de uma regra jurídica

### Referências legais
- Art. 1.043, III, CPC
- Art. 1.043, § 3º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a Súmula 158 do STJ e sua aplicabilidade no CPC.
- Entenda o conceito de embargos de divergência e suas hipóteses de cabimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.460 (1)", "page_number": 460, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.043, III, CPC", "Art. 1.043, § 3º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:04:33.745357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=460", "doc_key": "00ebda589ec21b6fe6bd783eccdea3cd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd213726319c4325c3ee75c213ea38c1e4077e5a2e98d6a2d4cb09c6f0b2c22c8'),
  ('cpiuris2025::c33784c9b2599cd764f299f0e7133e9b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Admissibilidade dos Embargos de Divergência', '## Admissibilidade dos Embargos de Divergência

O Tribunal Superior pode limitar a admissibilidade dos embargos de divergência apenas à hipótese indicada pelo recorrente, e não pode examinar outras hipóteses de cabimento.

### Conceitos
- **Admissibilidade**: A capacidade do recurso de ser processado
- **Embargo de Divergência**: Recurso apresentado pelo recorrente para discordar da decisão do tribunal que negou a admissibilidade do recurso principal
- **Hipótese Indicada**: A hipótese de cabimento indicada pelo recorrente como base para o recurso

### Referências legais
- Art. 1.043, I, CPC

### Jurisprudência
- Súmula 158, STJ
- Súmula 598, STF

### Dicas de prova
- Entenda a diferença entre hipótese indicada e outras hipóteses de cabimento.
- Conheça as regras para a admissibilidade dos embargos de divergência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.460 (2)", "page_number": 460, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.043, I, CPC"], "jurisprudence": ["Súmula 158, STJ", "Súmula 598, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:05:20.006833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=460", "doc_key": "c33784c9b2599cd764f299f0e7133e9b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '77a96211e03ccb03887f2e9cb737071140c49ed362fcff9729730df26d00a612'),
  ('cpiuris2025::16ab8d9de1e664a7f86ef22842d86cfc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso de Embargos de Divergência', '## Recurso de Embargos de Divergência

O recurso de embargos de divergência pressupõe que o dissenso entre os órgãos julgadores seja atual e não pode ser interposto se já houve pacificação da jurisprudência anteriormente.

### Conceitos
- **Recurso de Embargos de Divergência**: Recurso apresentado para discutir questões idênticas ou muito semelhantes tratadas de maneira díspar por seus órgãos fracionários internos
- **Divergência Jurídica**: Diferença entre os órgãos julgadores sobre a interpretação da lei
- **Pacificação da Jurisprudência**: Concordância dos órgãos judiciais em uma determinada questão jurídica
- **Vício Insanável**: Omissão ou erro que não pode ser corrigido por meio de recurso

### Referências legais
- Art. 1.043, § 4º, CPC

### Jurisprudência
- Súmula 168 do STJ

### Dicas de prova
- Identificar a natureza da divergência jurídica e se ela é recursal ou de competência originária
- Compreender a importância da pacificação da jurisprudência para o cabimento do recurso de embargos de divergência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.461 (1)", "page_number": 461, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.043, § 4º, CPC"], "jurisprudence": ["Súmula 168 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T06:06:12.678056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=461", "doc_key": "16ab8d9de1e664a7f86ef22842d86cfc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f9e2e5618c82967516923a3ba9a1c8b2e4b2cc7e3ceccadde84e41db02f85c94'),
  ('cpiuris2025::73a20414920a1c60cbdcfa3699597996', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interposição de Recurso Extraordinário e Embargos de Divergência', '## Interposição de Recurso Extraordinário e Embargos de Divergência

A interposição simultânea de recurso extraordinário e embargos de divergência pela mesma parte e contra a mesma decisão impede o conhecimento do segundo recurso, em virtude da unirrecorribilidade e da preclusão consumativa.

### Conceitos
- **Unirrecorribilidade**: Princípio que estabelece que para cada decisão será interposto apenas um recurso.
- **Preclusão Consumativa**: Condição em que a ação ou recurso não pode ser posta em discussão novamente após o trânsito em julgado da decisão.

### Referências legais
- Art. 525 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 168, STJ; AgInt nos EREsp 1.991.989/MA; AgInt no EAREsp 1.086.606/PR; Súmula 420, STJ; AgRg nos EREsp 303.546/MT

### Dicas de prova
- Distinção entre unirrecorribilidade e preclusão consumativa; Consequências da interposição simultânea de recursos extraordinários e embargos de divergência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.461 (2)", "page_number": 461, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 168, STJ; AgInt nos EREsp 1.991.989/MA; AgInt no EAREsp 1.086.606/PR; Súmula 420, STJ; AgRg nos EREsp 303.546/MT"], "confidence": 0.8, "extracted_at": "2026-05-28T06:07:08.452798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=461", "doc_key": "73a20414920a1c60cbdcfa3699597996"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '529e611d4c9140b6d22ae83acde41fdacbb46cef2194154bffb3eddf26a3f060'),
  ('cpiuris2025::3c8a30b09b4e6f2651f8f68420b7259f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Precedentes no Tribunal Superior e sua importância', '## Precedentes no Tribunal Superior e sua importância

O novo CPC visa promover a valorização dos julgamentos proferidos pelos Tribunais, atribuindo-lhes um caráter de vinculatividade. Os juízes e tribunais devem observar decisões do STF, súmulas vinculantes, acórdãos repetitivos e orientação do plenário ou órgão especial.

### Conceitos
- **Precedente**: Decisão judicial que serve de base para a decisão futura em casos idênticos
- **Vinculatividade**: Caráter obrigatório de uma decisão judicial
- **Súmula vinculante**: Enunciado que consolida a jurisprudência do Tribunal e tem força vinculante para os órgãos jurisdicionais hierarquicamente inferiores
- **Acórdão repetitivo**: Acórdão proferido em recurso repetitivo, que tem força vinculante para todos os órgãos do Poder Judiciário

### Referências legais
- Art. 927, incisos, CPC

### Dicas de prova
- Entenda a importância dos precedentes no Tribunal Superior e como eles se relacionam com a vinculatividade
- Conheça as diferentes formas de precedente (súmula vinculante, acórdão repetitivo) e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.462 (1)", "page_number": 462, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 927, incisos, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:08:04.834901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=462", "doc_key": "3c8a30b09b4e6f2651f8f68420b7259f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '75c299f09b051f4fdc3e7122d97e0688a05e0d2e4d7c7e4fe4a30346d4afc2a4'),
  ('cpiuris2025::5b8a3e27f143925c13d23d81df94a5e2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Vinculatividade e Precedentes em Tribunais', '## Vinculatividade e Precedentes em Tribunais

É necessário identificar corretamente o elemento nuclear dos precedentes vinculantes para exigir do juiz que os respeite e aplique.

### Conceitos
- **Precedente Vinculante**: Decisão que se vincula a todos os Tribunais
- **Interpretação do Precedente**: Examinar o enunciado e fundamentos determinantes para identificar a tese jurídica
- **Ratio Decidendi**: Tese jurídica sintetizada no enunciado do precedente
- **Distinguishing**: Hipótese que não se enquadra naquela tratada no precedente
- **Overruling**: Promover a superação de um precedente diante de uma nova realidade social, jurídica, política ou econômica

### Referências legais
- Art. 585 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a interpretação correta dos precedentes vinculantes.
- Entenda o conceito de ratio decidendi e sua importância na interpretação do precedente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.462 (2)", "page_number": 462, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 585 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:08:47.899783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=462", "doc_key": "5b8a3e27f143925c13d23d81df94a5e2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '52800eb0f01c054e599c486ad6b6ac958147925e0329fba8032db29ad363b0f9'),
  ('cpiuris2025::aab9b56143e9faec43654592a110982a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Técnicas de formação de precedentes vinculantes', '## Técnicas de formação de precedentes vinculantes

A superação do precedente deve ser precedida de audiências públicas e participação de amicus curiae, com fundamentação adequada e específica. Além disso, os recursos especiais ou extraordinários repetitivos são selecionados para formar um precedente vinculante.

### Conceitos
- **Precedente vinculante**: Julgamento que fixa uma tese jurídica aplicável a outros processos com fundamento na mesma questão de direito.
- **Caso piloto**: Procedimento instituído exclusivamente no STF e STJ, que pressupõe a existência de multiplicidade de recursos especiais ou extraordinários com fundamento na mesma questão de direito.

### Referências legais
- Art. 926, caput, CPC
- Art. 927, § 2º, CPC
- Art. 927, § 3º, CPC

### Dicas de prova
- Entenda a diferença entre recursos especiais e extraordinários repetitivos.
- Conheça o procedimento do caso piloto no STF e STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.463 (1)", "page_number": 463, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 926, caput, CPC", "Art. 927, § 2º, CPC", "Art. 927, § 3º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:09:43.627627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=463", "doc_key": "aab9b56143e9faec43654592a110982a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e69b1b6513e840dfabaeb6d5fb869e8a95518168a9f02a27aed2085eaced2870'),
  ('cpiuris2025::d5f32af4115c3cc5467cdea52f63d1be', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sobrestamento de processos pendentes', '## Sobrestamento de processos pendentes

O STF ou STJ selecionam recursos representativos da controvérsia e sobrestam outros processos pendentes que envolvem a mesma matéria, observando-se que os recursos devem ser admissíveis e conter argumentação abrangente.

### Conceitos
- **Sobrestamento**: Princípio que determina a suspensão de outros processos pendentes que envolvam a mesma matéria
- **Recursos representativos da controvérsia**: Recurso que representa a controvérsia e é selecionado pelo STF ou STJ
- **Admissibilidade**: A capacidade de um recurso ser processado e julgado
- **Argumentação abrangente**: Explicação completa e detalhada sobre a questão a ser julgada

### Referências legais
- Art. 1.036, § 1º, CPC

### Dicas de prova
- Entenda que o sobrestamento não é vinculante para o relator
- Leia atentamente a definição de recursos representativos da controvérsia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.463 (2)", "page_number": 463, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.036, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:10:25.418227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=463", "doc_key": "d5f32af4115c3cc5467cdea52f63d1be"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '434f8d9298356f686bf805fb319f67a2f5a12d96c532807198dc797300e51c85'),
  ('cpiuris2025::0fe8c96ef9ffd35cb1c338b399361ed4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Decisão de Afetação e Suspensão de Processos', '## Decisão de Afetação e Suspensão de Processos

A decisão de afetação é uma medida que suspende todos os processos pendentes sobre a questão a ser julgada. A competência para examinar o requerimento de distinção é do juiz, relator ou do Tribunal Superior.

### Conceitos
- **Decisão de Afetação**: Medida que suspende todos os processos pendentes sobre a questão a ser julgada
- **Suspensão de Processos**: Medida que suspende a tramitação de um processo pendente
- **Competência para Examinar Requerimento de Distinguimento**: Do juiz, relator ou do Tribunal Superior

### Referências legais
- Art. 1.037, caput e incisos, CPC
- Art. 256-E, II, RISTJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência para examinar o requerimento de distinção
- Conheça as hipóteses em que a decisão de afetação é proferida
- Aprenda a diferença entre a suspensão de processos e a tramitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.464 (1)", "page_number": 464, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.037, caput e incisos, CPC", "Art. 256-E, II, RISTJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:11:14.518558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=464", "doc_key": "0fe8c96ef9ffd35cb1c338b399361ed4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cb055a25ef761f1400e97216566c3b068a897c9c7732a689a034a0cd2c5f4dc0'),
  ('cpiuris2025::d9e51965b887e5813a20c3e6ff495490', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Distinção em 5 dias', '## Distinção em 5 dias

A distinção em 5 dias é uma decisão judicial que deve ser proferida em um prazo de 5 dias, conforme o art. 1.037, § 11, CPC. A partir dessa decisão, as partes devem tomar as providências necessárias.

### Conceitos
- **Distinção em 5 dias**: Decisão judicial que deve ser proferida em um prazo de 5 dias
- **Recurso especial**: Recurso apresentado ao STJ ou ao STF
- **Agravo de instrumento**: Ação que pode ser interposta se o processo estiver em primeiro grau
- **Agravo interno**: Ação que pode ser interposta se a decisão for de relator

### Referências legais
- Art. 1.037, § 11, CPC
- Art. 1.037, § 12, CPC
- Art. 1.037, § 13, CPC
- Art. 256-E, CPC

### Jurisprudência
- REsp 1.846.109/SP
- RE 123456

### Dicas de prova
- Entenda a diferença entre agravo de instrumento e agravo interno.
- Conheça o prazo para reexaminar a admissibilidade do recurso representativo da controvérsia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.464 (2)", "page_number": 464, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.037, § 11, CPC", "Art. 1.037, § 12, CPC", "Art. 1.037, § 13, CPC", "Art. 256-E, CPC"], "jurisprudence": ["REsp 1.846.109/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:12:17.988492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=464", "doc_key": "d9e51965b887e5813a20c3e6ff495490"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '87c03d1c014d92e2836da896d241779468176847e34509ae5441bbfa38889c45'),
  ('cpiuris2025::fc1553a2126a6a951e741c4456ccad6a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Repetitivo e Precedente Vinculante', '## Recurso Repetitivo e Precedente Vinculante

O recurso repetitivo é iniciado para tramitar a controvérsia sob o rito dos repetitivos. O relator pode solicitar manifestação de amicus curiae, realizar audiências públicas e ouvir depoimentos de especialistas. Essas medidas visam conferir legitimidade ao precedente vinculante que se formará no julgamento do recurso.

### Conceitos
- **Recurso Repetitivo**: Procedimento utilizado para tramitar a controvérsia sob o rito dos repetitivos
- **Precedente Vinculante**: Acórdão que se torna vinculante para os tribunais e jurisdições futuras
- **Amicus Curiae**: Pessoa que não é parte do processo, mas pode manifestar-se sobre um tema específico

### Referências legais
- Art. 1.038, caput e incisos, CPC
- Art. 1.039, caput, CPC
- Art. 1.040, I, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do recurso repetitivo e como ele afeta o processo
- Conheça as medidas que podem ser adotadas pelo relator para conferir legitimidade ao precedente vinculante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.465 (1)", "page_number": 465, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.038, caput e incisos, CPC", "Art. 1.039, caput, CPC", "Art. 1.040, I, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:13:10.852612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=465", "doc_key": "fc1553a2126a6a951e741c4456ccad6a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd69cc6b89a96560bb98ab07a879df899473d45329bd64df725086eead69e2207'),
  ('cpiuris2025::9bdb8a6f34eac67a8005083262a9bfb7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Repetitivo e Alteração de Posicionamento do Órgão Fracionário', '## Recurso Repetitivo e Alteração de Posicionamento do Órgão Fracionário

O recurso repetitivo é uma medida processual que visa evitar a repetição de questões discutidas em recursos anteriores. Em caso de alteração de posicionamento do órgão fracionário, os recursos especiais ou extraordinários já interpostos serão remetidos ao STJ ou ao STF.

### Conceitos
- **Recurso Repetitivo**: Medida processual que visa evitar a repetição de questões discutidas em recursos anteriores.
- **Alteração de Posicionamento do Órgão Fracionário**: Mudança na posição do órgão fracionário sobre uma questão específica.
- **Recurso Especial**: Recurso apresentado contra a decisão de um tribunal de primeiro grau.
- **Recurso Extraordinário**: Recurso apresentado para apelar uma decisão do tribunal de segundo grau.
- **Tese Repetitiva**: Decisão tomada pelo órgão jurisdicional sobre uma questão específica.
- **Órgão Fracionário**: Membro do tribunal que não compõe a maioria da decisão.
- **Demais Questões**: Questões adicionais que surgem em decorrência de alteração de posicionamento do órgão fracionário.

### Referências legais
- Art. 1.040, II, CPC

### Jurisprudência
- REsp 2.060.149/SP
- REsp 1.946.242/RJ

### Dicas de prova
- Entenda a importância do recurso repetitivo e como ele se aplica em casos de alteração de posicionamento do órgão fracionário.
- Conheça as diferenças entre recursos especiais e extraordinários, bem como a tese repetitiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.465 (2)", "page_number": 465, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.040, II, CPC"], "jurisprudence": ["REsp 2.060.149/SP", "REsp 1.946.242/RJ"], "confidence": 0.8, "extracted_at": "2026-05-28T06:14:14.014676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=465", "doc_key": "9bdb8a6f34eac67a8005083262a9bfb7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '923594bfdbc73b9184e920557ef6a1ae42b641efdf8b66c83ea47d4f90465408'),
  ('cpiuris2025::ca9708201f391353af9fbf25419e01f5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instituto de Resolução de Demandas Repetitivas (IRDR)', '## Instituto de Resolução de Demandas Repetitivas (IRDR)

O IRDR é um mecanismo criado pelo novo CPC para uniformizar a interpretação dos Tribunais Estaduais e Regionais Federais sobre questões repetitivas, formando-se um precedente vinculante.

### Conceitos
- **Instituto de Resolução de Demandas Repetitivas (IRDR)**: Mecanismo criado pelo CPC para uniformizar a interpretação dos Tribunais sobre questões repetitivas
- **Competência recursal ordinária**: Recurso ordinário constitucional que pode ser apresentado ao STJ
- **Competência originária da Corte**: Competência do STJ em casos de mandados de segurança e conflitos de competência
- **Cisão cognitiva**: Divisão da tese jurídica acerca da questão repetitiva, cabendo a cada órgão jurisdicional posteriormente aplicar o entendimento nos casos concretos

### Referências legais
- Art. 1.040, § 3º, CPC
- Art. 1.040, § 2º, CPC
- Art. 976, I; 987, § 1º e 977, III, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a natureza jurídica do IRDR e suas implicações nos Tribunais.
- Conheça as competências recursal ordinária e originária da Corte.
- Aprenda a distinguir entre cisão cognitiva e procedimento-modelo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.466 (1)", "page_number": 466, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.040, § 3º, CPC", "Art. 1.040, § 2º, CPC", "Art. 976, I; 987, § 1º e 977, III, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:15:27.535772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=466", "doc_key": "ca9708201f391353af9fbf25419e01f5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '853110486abab80f0283c8b701e8cbbda20f2bb33d6553c74fe0d5ab74aeabd2'),
  ('cpiuris2025::008ce7aecf12ba0e99eb700430773f19', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instituto de Revisão do Direito Recorrente (IRDR)', '## Instituto de Revisão do Direito Recorrente (IRDR)

O IRDR é um caso-piloto com unidade cognitiva, onde a tese jurídica é definida e aplicada em casos concretos. É indispensável a existência de causa pendente no Tribunal para instaurar o IRDR.

### Conceitos
- **Caso-piloto**: Um caso que serve como modelo para outros casos semelhantes
- **Unidade cognitiva**: A capacidade de um caso de ser compreendido como parte de um conjunto de casos relacionados
- **Tese jurídica**: A afirmação geral que resume a questão jurídica em questão
- **Instauração do IRDR**: O processo de instalação do IRDR, que envolve a definição da tese jurídica e sua aplicação aos casos concretos

### Referências legais
- Art. 978, parágrafo único, CPC

### Jurisprudência
- Enunciado 344 do FPPC
- Enunciado 22 da ENFAM
- Súmula 529 do STJ

### Dicas de prova
- Entenda a noção de caso-piloto e unidade cognitiva para aplicar corretamente o IRDR
- Identifique a tese jurídica como a afirmação geral que resume a questão jurídica em questão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.466 (2)", "page_number": 466, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 978, parágrafo único, CPC"], "jurisprudence": ["Enunciado 344 do FPPC", "Enunciado 22 da ENFAM", "Súmula 529 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T06:16:21.604027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=466", "doc_key": "008ce7aecf12ba0e99eb700430773f19"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '851ab6f13d2bee8e7d97205a2a59bdcfe93dd8b42a453805bd31d6aa6e2b23f6'),
  ('cpiuris2025::ffc471a4b67769e56032e2b04d5d0238', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instauração do IRDR', '## Instauração do IRDR

O IRDR é instaurado quando há efetiva repetição de processos sobre a mesma questão, risco de ofensa à isonomia e segurança jurídica, e causa pendente no Tribunal.

### Conceitos
- **Repetição de Processos**: Multiplicidade efetiva e concreta de processos sobre a mesma questão
- **Risco de Ofensa à Isonomia e Segurança Jurídica**: Perigo de decisões diferentes e conflitantes sobre a mesma questão
- **Causa Pendente**: Pressuposto de admissibilidade do IRDR, dependendo da corrente doutrinária

### Referências legais
- Art. 976, I e II, CPC
- Art. 976, § 4º, CPC
- Art. 977, I a III, parágrafo único, CPC
- Art. 982, I, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre IRDR

### Dicas de prova
- Distinção entre efetiva e potencial repetição de processos
- Importância da causa pendente no Tribunal
- Pressuposto negativo de admissibilidade do IRDR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.467 (1)", "page_number": 467, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 976, I e II, CPC", "Art. 976, § 4º, CPC", "Art. 977, I a III, parágrafo único, CPC", "Art. 982, I, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre IRDR"], "confidence": 0.8, "extracted_at": "2026-05-28T06:17:12.302885+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=467", "doc_key": "ffc471a4b67769e56032e2b04d5d0238"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e28c00e4199627d3bf4f2635683459b766238b0597972d826c273ba32acf4d69'),
  ('cpiuris2025::69b51cd01edd842e07ed23f54536ca37', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão dos processos após decisão do IRDR', '## Suspensão dos processos após decisão do IRDR

Os processos devem retomar a sua tramitação, salvo decisão fundamentada do relator em sentido contrário. A suspensão dos demais processos perdura até o julgamento dos recursos especial e/ou extraordinário perante o STJ e/ou STF.

### Conceitos
- **IRDR**: Incidente de Resolução de Demandas Repetitivas
- **Recurso Especial**: Recurso apresentado perante o Superior Tribunal de Justiça (STJ)
- **Recurso Extraordinário**: Recurso apresentado perante a Suprema Corte do Brasil (STF)

### Referências legais
- art. 980, parágrafo único, CPC

### Jurisprudência
- REsp 1.798.374/DF
- AREsp 1.470.017/SP
- REsp 1.869.867/SC
- REsp 1.976.792/RS

