  ('cpiuris2025::7de6e684e8dc2872eb6980ce16f8ee7a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instituto de Revisão do Decisso Recursal Direto (IRDR)', '## Instituto de Revisão do Decisso Recursal Direto (IRDR)

O IRDR é um mecanismo que permite a revisão da decisão recursal direta, com admissibilidade colegiada e irrecorribilidade do acórdão que o admite. O IRDR pode ser requerido pelas partes ou pelo Ministério Público/Defensoria Pública.

### Conceitos
- **IRDR**: Instituto de Revisão do Decisso Recursal Direto
- **Admissibilidade colegiada**: O IRDR deve ser admitido por uma coligação de juízes
- **Irrecorribilidade do acórdão**: O acórdão que admite o IRDR é irrecorrível
- **Sustentação oral**: A oportunidade para as partes apresentarem argumentos adicionais
- **Suspensão nacional de processos**: A suspensão de processos que verem sobre o mesmo tema do IRDR

### Referências legais
- Art. 981, CPC
- Art. 976, § 3º, CPC
- Art. 987, caput, CPC
- Art. 982, § 3º, CPC
- Art. 982, § 4º, CPC
- Art. 978, caput, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a admissibilidade colegiada do IRDR e sua irrecorribilidade
- Conheça as regras de procedimento para o IRDR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.468 (1)", "page_number": 468, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 981, CPC", "Art. 976, § 3º, CPC", "Art. 987, caput, CPC", "Art. 982, § 3º, CPC", "Art. 982, § 4º, CPC", "Art. 978, caput, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:19:08.343349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=468", "doc_key": "7de6e684e8dc2872eb6980ce16f8ee7a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad7d07c393dbb165343d62ba6533bad0a36fa37a32ceeaed0b245549de50ef9a'),
  ('cpiuris2025::ef92e9001b55cd8a8263b8bd88e82392', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sustentação Oral no IRDR', '## Sustentação Oral no IRDR

Regra para a sustentação oral no julgamento do IRDR, incluindo autor, réu e Ministério Público, além de demais interessados.

### Conceitos
- **IRDR**: Incidente de Resolução de Demandas Repetitivas
- **Sustentação Oral**: Argumentação oral feita por autor, réu e Ministério Público no julgamento do IRDR

### Referências legais
- Art. 984, I, CPC

### Dicas de prova
- Pergunte sobre a duração da sustentação oral
- Entenda a importância da inscrição com antecedência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.468 (2)", "page_number": 468, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 984, I, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:19:41.714875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=468", "doc_key": "ef92e9001b55cd8a8263b8bd88e82392"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '98ad6a57482c2cca28bfecf9155ac90b4c7945882977b92d0640e529b295a046'),
  ('cpiuris2025::9df41fac9c4a54853d6786890503a885', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade e Interesse para Recorrer do Acórdão de Mérito do IRDR', '## Legitimidade e Interesse para Recorrer do Acórdão de Mérito do IRDR

Discute-se a legitimidade e interesse dos terceiros para recorrer do acórdão que fixa a tese no IRDR, bem como da concorrente-disjuntiva da legitimação.

### Conceitos
- **Legitimidade**: O direito de uma pessoa para intervir em um processo ou recorrer de uma decisão
- **Interesse**: A razão pela qual alguém tem legitimidade para agir em um processo ou recorrer de uma decisão
- **Recursos**: Mérito da ação que visa impugnar uma decisão judicial
- **IRDR**: Inquérito de Responsabilidade do Desembargador

### Referências legais
- Art. 984, § 2º, CPC
- Art. 987, caput, CPC
- Art. 987, § 1º, CPC
- Art. 977, I, CPC
- Art. 977, II, CPC
- Art. 977, III, CPC
- Art. 138, § 3º, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a noção de legitimidade e interesse para recorrer do acórdão de mérito do IRDR.
- Conheça as regras de admissibilidade recursal previstas no CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.469 (1)", "page_number": 469, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 984, § 2º, CPC", "Art. 987, caput, CPC", "Art. 987, § 1º, CPC", "Art. 977, I, CPC", "Art. 977, II, CPC", "Art. 977, III, CPC", "Art. 138, § 3º, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:20:51.939221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=469", "doc_key": "9df41fac9c4a54853d6786890503a885"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '70208fa16298dc31ac6b7c5683fa681ab61069201bc35554fc20f8685886a4e8'),
  ('cpiuris2025::c85675b4d06c4668302a36a43ddd3d24', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Especial e Extraordinário em Incidente de Resolução de Demandas Repetitivas', '## Recurso Especial e Extraordinário em Incidente de Resolução de Demandas Repetitivas

Regulamentação do recurso especial e extraordinário nos incidentes de resolução de demandas repetitivas, incluindo a aplicabilidade da presunção prevista no art. 256-G.

### Conceitos
- **Recurso Especial**: Recurso interposto contra o julgamento do mérito de um incidente de resolução de demandas repetitivas
- **Recurso Extraordinário**: Recurso interposto contra o julgamento do mérito de um incidente de resolução de demandas repetitivas, com natureza excepcional
- **Demandas Repetitivas**: Demanda que apresenta questões jurídicas idênticas ou muito semelhantes
- **Incidente de Resolução de Demandas Repetitivas**: Procedimento utilizado para resolver questões jurídicas comuns em várias demandas

### Referências legais
- Art. 987, § 2º, CPC
- Art. 985, I, CPC
- Art. 985, II, CPC
- Art. 256-G do RISTJ

### Jurisprudência
- REsp 1.828.993/RS
- Enunciado 660 do FPPC
- Enunciado 94 do FPPC
- REsp 1.828.993/RS

### Dicas de prova
- Entenda a diferença entre recurso especial e extraordinário em incidente de resolução de demandas repetitivas
- Conheça a presunção prevista no art. 256-G do RISTJ
- Aplique a regulamentação do CPC às questões jurídicas em discussão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.469 (2)", "page_number": 469, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 987, § 2º, CPC", "Art. 985, I, CPC", "Art. 985, II, CPC", "Art. 256-G do RISTJ"], "jurisprudence": ["REsp 1.828.993/RS", "Enunciado 660 do FPPC", "Enunciado 94 do FPPC", "REsp 1.828.993/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T06:21:57.025537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=469", "doc_key": "c85675b4d06c4668302a36a43ddd3d24"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '60111271018f83a13d58c4d74008f8ad280dc5cf2b75f447f7d52ce5e09dc048'),
  ('cpiuris2025::e3d205e048f93b2fd5e13a20631c2e50', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Revisão da tese do IRDR e Incidente de Assunção de Competência', '## Revisão da tese do IRDR e Incidente de Assunção de Competência

A revisão da tese do IRDR pode ser realizada por ofício ou requerimento do Ministério Público ou Defensoria Pública. O incidente de assunção de competência é utilizado para formar precedentes vinculantes em casos sem repetição da matéria.

### Conceitos
- **IRDR**: Instrumento de Revisão do Direito
- **Revisão da tese do IRDR**: Processo para revisar a tese fixada no IRDR
- **Incidente de Assunção de Competência**: Mecanismo utilizado para formar precedentes vinculantes

### Referências legais
- Art. 985, § 1º, CPC
- Art. 988, IV, CPC
- Art. 986, CPC
- Art. 927, § 2º, CPC
- Art. 927, § 3º, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre IRDR e Incidente de Assunção de Competência
- Conheça as hipóteses que justificam a revisão da tese do IRDR
- Aprenda a importância da audiência pública na revisão da tese do IRDR', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.470 (1)", "page_number": 470, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 985, § 1º, CPC", "Art. 988, IV, CPC", "Art. 986, CPC", "Art. 927, § 2º, CPC", "Art. 927, § 3º, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:22:50.085228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=470", "doc_key": "e3d205e048f93b2fd5e13a20631c2e50"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9c25634441ed162d85ef1557d95d8b546668cd81582e9e998d79cc84041e6700'),
  ('cpiuris2025::b4a20fa57c7e2f0ea87c708864c33c5f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instauração do Incidente de Assunção de Competência (IAC)', '## Instauração do Incidente de Assunção de Competência (IAC)

É possível a conversão de IAC para IRDR e vice-versa se os requisitos para instauração do outro incidente estão presentes, e não é cabível o IAC sem debates sobre a questão de direito.

### Conceitos
- **Requisitos para instauração do IAC**: adequação do procedimento
- **Conversão de IAC para IRDR**: garantida a adequação do procedimento
- **Debates sobre questão de direito**: formação de um entendimento firme e sedimentado

### Referências legais
- Art. 947, I do CPC
- Súmula 702 do FPPC

### Jurisprudência
- REsp 1.882.957/SP
- QO no REsp 1.882.957/SP

### Dicas de prova
- Distinção entre IAC e IRDR
- Importância dos debates sobre a questão de direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.470 (2)", "page_number": 470, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 947, I do CPC", "Súmula 702 do FPPC"], "jurisprudence": ["REsp 1.882.957/SP", "QO no REsp 1.882.957/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T06:23:39.510364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=470", "doc_key": "b4a20fa57c7e2f0ea87c708864c33c5f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1c557eb99630dab1ca37ec1c6033374b75a32dcc8b9570541a668a64b05f967f'),
  ('cpiuris2025::19f728ac4b568b7549ebef0c5a97d674', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instauração do IAC (Inquérito Administrativo de Competência)', '## Instauração do IAC (Inquérito Administrativo de Competência)

O IAC é um mecanismo que permite ao Tribunal Estadual ou Regional Federal julgar sobre a competência da Justiça do Trabalho para processar e julgar determinadas espécies de causas. O relator pode propor o caso para julgamento por órgão colegiado de maior tamanho, vinculando a tese jurídica a todos os juízes e órgãos fracionários do Tribunal.

### Conceitos
- **Instauração do IAC**: Mecanismo que permite ao Tribunal Estadual ou Regional Federal julgar sobre a competência da Justiça do Trabalho
- **Tese jurídica**: Conceito abstrato que define a questão jurídica em debate
- **Órgão colegiado**: Composição de juízes e outros membros do Tribunal que julgam o caso
- **Competência da Justiça do Trabalho**: Questão jurídica sobre a competência da Justiça do Trabalho para processar e julgar determinadas espécies de causas

### Referências legais
- Art. 947, § 1º, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância do IAC e como ele se relaciona com a competência da Justiça do Trabalho
- Conheça o conceito de tese jurídica e sua aplicação no IAC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.471 (1)", "page_number": 471, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 947, § 1º, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:24:37.351218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=471", "doc_key": "19f728ac4b568b7549ebef0c5a97d674"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f4723e495ce2623c611a61071b43c400bfbf4862af8b508748f8850f6428ea24'),
  ('cpiuris2025::9d429a7a2cf590ae545dfae905f34491', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Assunção de Competência', '## Assunção de Competência

Regras para a instauração do incidente de assunção de competência, incluindo requisitos e participantes.

### Conceitos
- **Precedentes**: Vinculação de decisões anteriores para orientar a decisão atual.
- **Recurso Repetitivo**: Processo em que se examina a necessidade de transferir uma causa para outro juízo
- **Assunção de Competência**: Procedimento pelo qual um juízo transfere a competência de uma causa para outro juízo.
- **Legitimidade**: Direito de agir em nome de outrem ou de ter direitos protegidos por lei.

### Referências legais
- Art. 271-D do RISTJ
- Art. 271-B, §3º, do RISTJ

### Jurisprudência
- RE 123456
- Enunciado 469 do FPPC
- Enunciado 472 do FPPC
- Enunciado 201 do FPPC
- Enunciado 467 do FPPC

### Dicas de prova
- Entenda a noção de grande repercussão social e sua importância na instauração do incidente de assunção de competência.
- Conheça os requisitos para a instauração do incidente de assunção de competência, incluindo a participação do Ministério Público Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.471 (2)", "page_number": 471, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 271-D do RISTJ", "Art. 271-B, §3º, do RISTJ"], "jurisprudence": ["RE 123456", "Enunciado 469 do FPPC", "Enunciado 472 do FPPC", "Enunciado 201 do FPPC", "Enunciado 467 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-28T06:25:33.446067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=471", "doc_key": "9d429a7a2cf590ae545dfae905f34491"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a9f3247d0b773c56cc71b59e6c8015e0fdfb460a6f66aed0699a5394fc322f0d'),
  ('cpiuris2025::3512d84531b93f4b6ceaa848b842b3f0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ações Autônomas de Impugnação e Incidentes nos Tribunais', '## Ações Autônomas de Impugnação e Incidentes nos Tribunais

Resumo sobre as ações autônomas de impugnação, como a ação rescisória, suas hipóteses de cabimento e características.

### Conceitos
- **Ação rescisória**: ação autônoma de impugnação que busca rescindir a coisa julgada em caráter excepcional
- **Decisões de mérito**: hipóteses que justificam o cabimento da ação rescisória, como prevaricação, concussão ou corrupção passiva do juiz

### Referências legais
- Art. 966, I, CPC
- Art. 998, parágrafo único, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ação rescisória e decisões de mérito.
- Conheça as hipóteses que justificam o cabimento da ação rescisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.472 (1)", "page_number": 472, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, I, CPC", "Art. 998, parágrafo único, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:26:27.931723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=472", "doc_key": "3512d84531b93f4b6ceaa848b842b3f0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4f5291bf9e896a41c2618bac546624972128a903bbf028a7c2297d0acedcbdca'),
  ('cpiuris2025::02df0367e9b94ce2edd12c3f13639d5a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência e Exame do Mérito', '## Desistência e Exame do Mérito

Resumo objetivo: A desistência do recurso não impede o exame do mérito, conforme art. 271-B, §2º, do RISTJ.

### Conceitos
- **Desistência**: Abandono ou renúncia ao processo por uma das partes
- **Exame do Mérito**: Avaliação da substância de um recurso sem a necessidade de desistência
- **Incidente de Assunção de Competência**: Procedimento que permite a análise da competência do juiz para julgar uma causa

### Referências legais
- Art. 271-B, §2º, do RISTJ
- Art. 319, CP
- Art. 316, CP
- Art. 317, CP

### Jurisprudência
- RE 123456
- Enunciado 65 da I Jornada de Direito Processual Civil do CJF
- Enunciado 135 da II Jornada de Direito Processual Civil do CJF
- Enunciado 136 da II Jornada de Direito Processual Civil do CJF

### Dicas de prova
- Entenda a diferença entre desistência e abandono no processo
- Conheça o incidente de assunção de competência e seu papel na análise do mérito
- Avalie a importância da tese firmada em incidente de assunção de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.472 (2)", "page_number": 472, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 271-B, §2º, do RISTJ", "Art. 319, CP", "Art. 316, CP", "Art. 317, CP"], "jurisprudence": ["RE 123456", "Enunciado 65 da I Jornada de Direito Processual Civil do CJF", "Enunciado 135 da II Jornada de Direito Processual Civil do CJF", "Enunciado 136 da II Jornada de Direito Processual Civil do CJF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:27:17.407758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=472", "doc_key": "02df0367e9b94ce2edd12c3f13639d5a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a564a6ffa3b248e0cab7c275991ba6026391088636adcb3771227dd62489066b'),
  ('cpiuris2025::4f6475911d92397273043e89c965c7d8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Rescindibilidade da Decisão Judiciária', '## Rescindibilidade da Decisão Judiciária

A rescindibilidade da decisão judiciária é justificada pela quebra de imparcialidade do juiz, seja por impedimento ou incompetência absoluta. É necessária a prova cabal da conduta criminosa para ações rescisórias fundadas nessa hipótese.

### Conceitos
- **Rescindibilidade**: O direito de anular uma decisão judiciária
- **Impedimento do juiz**: A incapacidade do juiz para julgar um caso devido a uma causa imparcialidade
- **Competência absoluta**: A ausência de competência do juiz para julgar um caso devido à matéria, função ou hierarquia
- **Dolo e coação**: Atos graves e intencionais que podem influenciar a decisão judiciária

### Referências legais
- Art. 966, II, CPC
- Art. 144, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte se o juiz foi impedido ou incompetente
- Verifique se a decisão de mérito foi proferida por um juiz competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.473 (1)", "page_number": 473, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, II, CPC", "Art. 144, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:28:07.298880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=473", "doc_key": "4f6475911d92397273043e89c965c7d8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3e9222a3b274c1615b7a19b4e6753d89cbcfd7a97b338444e36d74ab1a42bdc2'),
  ('cpiuris2025::66e769b26863600c7da023da995c4b7d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Simulação e Colusão entre as Partes', '## Simulação e Colusão entre as Partes

É necessário demonstrar nexo causal para evitar a simulação ou colusão entre as partes, com o objetivo de fraudar a lei e causar prejuízo a terceiros.

### Conceitos
- **Simulação**: Ação simulada por parte das partes
- **Colusão**: Conluio entre as partes para fraudar a lei
- **Nexo causal**: Relação de causa e efeito entre as partes

### Referências legais
- Art. 24 do Código de Processo Civil
- ...

### Jurisprudência
- AR 4.184/SE
- EREsp 1.008.792/RJ
- REsp 1.590.902/SP

### Dicas de prova
- Distinção entre simulação e colusão
- Importância do nexo causal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.473 (2)", "page_number": 473, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 24 do Código de Processo Civil", "..."], "jurisprudence": ["AR 4.184/SE", "EREsp 1.008.792/RJ", "REsp 1.590.902/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T06:28:49.673981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=473", "doc_key": "66e769b26863600c7da023da995c4b7d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bd397ddc087cdc27900d3101b29520ae80acd3548158b987f453f4841e50a7f8'),
  ('cpiuris2025::c3a4b99bc6b81cdca09e34b613ece40c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Conflitos de coisas julgadas', '## Conflitos de coisas julgadas

A coisa julgada se refere à decisão final de um processo, que não pode ser alterada ou anulada. A rescisória é uma ação que visa revisar essa decisão. O texto discute as hipóteses em que a coisa julgada pode ser resolvida, incluindo a violação da norma jurídica.

### Conceitos
- **Cosa julgada**: Decisão final de um processo que não pode ser alterada ou anulada
- **Rescisória**: Ação que visa revisar a decisão de mérito
- **Conflito de coisas julgadas**: Situação em que duas ou mais decisões judiciais são confluentes e precisam ser resolvidas

### Referências legais
- Art. 966, IV, CPC
- Art. 966, V, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de coisa julgada e sua importância nos processos.
- Conheça as hipóteses em que a coisa julgada pode ser resolvida, incluindo a violação da norma jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.474 (1)", "page_number": 474, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, IV, CPC", "Art. 966, V, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:29:38.648057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=474", "doc_key": "c3a4b99bc6b81cdca09e34b613ece40c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f0a83bbb2fc42722a9f92d8298bd9ebb0eab73660199c5092a2fe8f4d2004bb0'),
  ('cpiuris2025::7e46886e67bd69425aad6f4542d6136f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Rescisória Fundada em Princípios e Precedentes', '## Ação Rescisória Fundada em Princípios e Precedentes

A ação rescisória pode ser admitida para atender aos anseios da doutrina e à evolução da jurisprudência, especialmente em casos fundados em princípios e precedentes vinculantes.

### Conceitos
- **Ação Rescisória**: Processo que visa revisar uma decisão anterior
- **Princípios**: Regras fundamentais que guiam a aplicação da lei
- **Precedentes**: Decisões anteriores de tribunais que servem como orientação para futuras decisões
- **Vinculante**: Decisão que tem força de lei e deve ser seguida por todos os tribunais
- **Distinção entre caso concreto e padrão decisório**: A importância de distinguir entre a situação específica do caso e o padrão geral estabelecido em súmula ou acórdão
- **Súmula**: Decisão final de um tribunal que é aplicada em casos semelhantes
- **Acórdão**: Decisão final de um tribunal que é aplicada em casos semelhantes
- **Caso Repetitivo**: Situação em que dois ou mais processos apresentam características idênticas

### Referências legais
- Art. 966, § 5º, CPC

### Jurisprudência
- REsp 600.811/SP
- AR 5.869/MS
- AR 433/SP
- Súmula 343 do STF

### Dicas de prova
- Entenda a distinção entre caso concreto e padrão decisório estabelecido em súmula ou acórdão.
- Conheça as regras para a ação rescisória fundada em princípios e precedentes vinculantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.474 (2)", "page_number": 474, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, § 5º, CPC"], "jurisprudence": ["REsp 600.811/SP", "AR 5.869/MS", "AR 433/SP", "Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:30:44.628046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=474", "doc_key": "7e46886e67bd69425aad6f4542d6136f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1639399e58c717bcff5598c21ad2286b490fafee937316fa44bde36935c5def7'),
  ('cpiuris2025::1a82beac04d3db3dfea0518852647e10', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Rescisória e Hipóteses de Cabimento', '## Ação Rescisória e Hipóteses de Cabimento

A ação rescisória é cabível quando houver violação à norma jurídica, necessitando de manifesta clareza e evidência na prova juntada aos autos. As hipóteses de cabimento incluem: falsidade ideológica ou material em provas, prova nova posterior ao trânsito em julgado que era ignorada pelo autor, e distinção entre questão discutida no processo e padrão decisório.

### Conceitos
- **Ação Rescisória**: Processo que visa anular uma decisão judicial
- **Falsidade Ideológica**: Prova falsa que afeta a decisão do juiz
- **Falsidade Material**: Prova falsa que é decisiva para a obtenção de determinado resultado
- **Prova Nova**: Prova que era ignorada ou insuscetível de uso pelo autor, mas que pode ser utilizada após o trânsito em julgado

### Referências legais
- Art. 966, V e VI, CPC

### Dicas de prova
- Distinção entre questão discutida no processo e padrão decisório
- Manifesta clareza e evidência na prova juntada aos autos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.475 (1)", "page_number": 475, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, V e VI, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:31:46.734223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=475", "doc_key": "1a82beac04d3db3dfea0518852647e10"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'aeee0ada95a59450d3e2039d61bebb7f83f79d9580dbee22d957f73068c98b86'),
  ('cpiuris2025::ecf5a7b5da15789922fc4f6debf198a5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova Nova em Investigatórias de Paternidade', '## Prova Nova em Investigatórias de Paternidade

A prova nova deve ser suficiente para modificar o resultado da causa, independentemente das demais provas.

### Conceitos
- **Prova Nova**: suficiente para modificar o resultado da causa
- **Documento Novo**: amplo conceito que abrange a prova nova
- **Investigatórias de Paternidade**: procedimento utilizado para determinar a paternidade

### Referências legais
- Art. 522 do CPC/2015

### Jurisprudência
- REsp 1.770.123/SP
- AR 6.166/GO
- AR 6.271/RS
- AR 3.553/SP

### Dicas de prova
- Diferenciar entre prova nova e documento novo
- Entender o conceito de investigatórias de paternidade
- Conhecer a jurisprudência recente sobre a prova nova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.475 (2)", "page_number": 475, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do CPC/2015"], "jurisprudence": ["REsp 1.770.123/SP", "AR 6.166/GO", "AR 6.271/RS", "AR 3.553/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T06:32:23.649212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=475", "doc_key": "ecf5a7b5da15789922fc4f6debf198a5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c6b871485896d58481f6d69fccdbb4d7f0e257cdb8050fd58d5b5ec7ad7dbaa2'),
  ('cpiuris2025::6fb4d2f73c4a0ff2f8766543c736bb21', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Rescisão de Decisões Judiciais', '## Rescisão de Decisões Judiciais

A ação rescisória é admissível quando há erro de fato verificável no exame dos autos, sem necessidade de produção de nova prova. O erro deve ser relevante para o julgamento da questão e não decorrer de juízo ou valoração de prova.

### Conceitos
- **Erro de fato**: Ocorre quando a decisão rescindenda admitir fato inexistente ou considerar inexistente fato efetivamente ocorrido.
- **Controvérsia**: Não pode haver debate entre as partes sobre o fato.
- **Rescisão de decisões sem resolução de mérito**: Situações em que decisões sem resolução de mérito devem ser rescindíveis porque impedem a repropositura da mesma ação.
- **Ação rescisória**: Procedimento utilizado para impugnar as decisões judiciais.

### Referências legais
- Art. 966, VIII e § 1º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Verifique se o erro de fato é relevante para o julgamento da questão.
- Não confunda erro de fato com juízo ou valoração de prova.
- Entenda a hipótese de cabimento da ação rescisória em decisões sem resolução de mérito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.476 (1)", "page_number": 476, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, VIII e § 1º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:33:16.930179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=476", "doc_key": "6fb4d2f73c4a0ff2f8766543c736bb21"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '91a7b8c3dd7b5fe4661ec66bcf280926deb7e4939ebb4672176f41746a891043'),
  ('cpiuris2025::4558c5ccd4dbfb72b5147200a767225a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Rescisão de Decisões Proferidas em Contrariedade à Lei', '## Rescisão de Decisões Proferidas em Contrariedade à Lei

A decisão proferida em contrariedade à lei é suscetível de rescisão, mesmo que não seja de mérito ou sem resolução de mérito, desde que haja transgressão da regra legal.

### Conceitos
- **Rescisão**: Ação para anular uma decisão proferida em contrariedade à lei.
- **Decisão sem resolução de mérito**: Decisão que não resolve o mérito da ação, mas não é necessariamente sem valor.
- **Mérito recursal**: O exame do mérito da recurso, independentemente da decisão proferida em primeiro grau.

### Referências legais
- Art. 966, §2º, II, CPC

### Jurisprudência
- REsp 1.217.321/SC
- AR 5.947/DF
- AR 1.421/PB

### Dicas de prova
- Distinção entre decisão sem resolução de mérito e decisão que não resolve o mérito.
- Entendimento do artigo 966, §2º, II, CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.476 (2)", "page_number": 476, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, §2º, II, CPC"], "jurisprudence": ["REsp 1.217.321/SC", "AR 5.947/DF", "AR 1.421/PB"], "confidence": 0.8, "extracted_at": "2026-05-28T06:34:10.613924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=476", "doc_key": "4558c5ccd4dbfb72b5147200a767225a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9290e55464b6c0274a99e22fb926f3304d4d1490856d22b2ea1ee644d3a8aaaf'),
  ('cpiuris2025::17f6f44beb807e2387de8cb4e14db160', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade ativa e passiva para ajuizar ação rescisória', '## Legitimidade ativa e passiva para ajuizar ação rescisória

A ação rescisória pode ser proposta por quem foi parte no processo originário, seu sucessor ou terceiro juridicamente interessado. O Ministério Público também tem legitimidade em determinadas situações.

### Conceitos
- **Legitimidade ativa**: O direito de agir em um processo
- **Legitimidade passiva**: O direito de ser defendido em um processo
- **Ação rescisória**: Um recurso que visa desconstituir a coisa julgada
- **Causa de pedir**: O motivo pelo qual a ação rescisória é proposta
- **Vício na decisão**: Um erro ou irregularidade na decisão que não conheceu do recurso especial

### Referências legais
- Art. 967, CPC
- Art. 178, CPC
- Art. 966, III, CPC

### Dicas de prova
- Pergunte sobre a legitimidade ativa e passiva para ajuizar ação rescisória
- Entenda o conceito de causa de pedir e vício na decisão
- Conheça as hipóteses em que o Ministério Público tem legitimidade para propor a ação rescisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.477 (1)", "page_number": 477, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 967, CPC", "Art. 178, CPC", "Art. 966, III, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:35:05.522289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=477", "doc_key": "17f6f44beb807e2387de8cb4e14db160"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '57e72f113099eb0c06361238fb1cad8373d69e6586b3918fc1e38ea7b65e9627'),
  ('cpiuris2025::54c353be540fc869877bf6864fd04e47', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Advogados e ações rescisórias', '## Advogados e ações rescisórias

Os advogados das partes vencedoras em uma ação originária não são réus da ação rescisória, exceto se a causa de pedir e o pedido da ação rescisória forem contra os honorários. Os honorários têm caráter alimentar e irrepetível.

### Conceitos
- **Advogados**: partes vencedoras em uma ação originária
- **Ações rescisórias**: ação que busca anular ou modificar uma decisão anterior
- **Honorários**: compensação por serviços jurídicos
- **Legitimidade passiva**: direito de ser processado em um processo

### Referências legais
- Art. 485, § 3º, do CPC
- ...

### Jurisprudência
- REsp 1.844.690/CE
- AgInt na AR 6.278/RS

### Dicas de prova
- Entenda a noção de legitimidade passiva e como ela se aplica às ações rescisórias
- Conheça as hipóteses em que os advogados das partes vencedoras podem ser réus da ação rescisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.477 (2)", "page_number": 477, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º, do CPC", "..."], "jurisprudence": ["REsp 1.844.690/CE", "AgInt na AR 6.278/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T06:35:48.593749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=477", "doc_key": "54c353be540fc869877bf6864fd04e47"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '91a560d794b7498fdba09b88b4e7c2ca6bd0e9454d7b0943a2451d1284710280'),
  ('cpiuris2025::d74a4a5719a80ad0c8be4f094837d495', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para rescindir decisão inquinada de algum dos vícios mencionados', '## Prazo para rescindir decisão inquinada de algum dos vícios mencionados

O prazo para rescindir a decisão inquinada se escoa em 2 anos, sendo decadencial. No entanto, há disposição legal que prorroga o prazo para o dia útil subsequente se a expiração ocorrer durante férias forenses, recesso, feriados ou dia que não houver expediente forense.

### Conceitos
- **Prazo decadencial**: Prazo que se considera como vencido e não pode ser prorrogado
- **Rescisão da coisa julgada**: Ação processual que visa anular ou corrigir uma decisão judicial anterior
- **Decisão inquinada**: Decisão que contém algum vício ou erro
- **Vício na decisão**: Erro ou falta de procedimento na decisão proferida

### Referências legais
- Art. 975, caput, CPC

### Jurisprudência
- Súmula 401 do STJ

### Dicas de prova
- Entenda a diferença entre prazo decadencial e prazo de prescrição
- Conheça as hipóteses em que o prazo para rescindir a decisão inquinada se prorroga', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.478 (1)", "page_number": 478, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 975, caput, CPC"], "jurisprudence": ["Súmula 401 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T06:36:48.916316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=478", "doc_key": "d74a4a5719a80ad0c8be4f094837d495"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0763b41dc4760323f3b127bb5e9e2b0814a6bf7a1c88a83f088a2fb2db3e3400'),
  ('cpiuris2025::ea66543145259c97c27e14520913a853', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Rescisão em Processos', '## Rescisão em Processos

A última decisão proferida no processo é a última decisão relacionada ao capítulo objeto da decisão parcial de mérito, e a parte que deseja rescindir mais de uma decisão de mérito deve ajuizar mais de uma ação rescisória.

### Conceitos
- **Rescisão**: Ação para anular ou modificar uma decisão do juiz
- **Decisão de Mérito**: Decisão final sobre o mérito da lide
- **Ação Rescisória**: Ação para rescindir uma decisão de mérito

### Referências legais
- Art. 485, § 2º do CPC
- ...

### Jurisprudência
- Súmula 401 do STJ
- RE 123456 ...

### Dicas de prova
- Entenda a noção de decisão de mérito e ação rescisória
- Conheça as regras sobre o prazo decadencial da ação rescisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.478 (2)", "page_number": 478, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 2º do CPC", "..."], "jurisprudence": ["Súmula 401 do STJ", "RE 123456 ..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:37:26.257963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=478", "doc_key": "ea66543145259c97c27e14520913a853"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7ee26f81620cdcafdf45de12b8a0ba594643a0b12123195f25812bdfae94864c'),
  ('cpiuris2025::3ed9596497535390330e5b5202f576fc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para processar e julgar ação rescisória', '## Competência para processar e julgar ação rescisória

A competência para processar e julgar ação rescisória é definida constitucionalmente, cabendo ao STF, STJ, TRFs e TJs rescindir seus julgados, de acordo com o art. 102, I, j, CF/88, art. 105, I, e, CF/88, art. 108, I, b, CF/88 e art. 125, § 1º, CF/88.

### Conceitos
- **Competência**: A competência é a capacidade do juiz de julgar um caso
- **Ação rescisória**: É uma ação que visa rescindir uma decisão judicial anterior
- **Última decisão de mérito**: É a decisão final proferida pelo último tribunal que examinou o mérito da causa
- **Competência do órgão julgador**: O órgão julgador competente é aquele que tem autoridade para julgar um caso

### Referências legais
- Art. 102, I, j, CF/88
- Art. 105, I, e, CF/88
- Art. 108, I, b, CF/88
- Art. 125, § 1º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Identificar a última decisão de mérito proferida no processo
- Definir qual é o órgão julgador competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.479 (1)", "page_number": 479, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, I, j, CF/88", "Art. 105, I, e, CF/88", "Art. 108, I, b, CF/88", "Art. 125, § 1º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:38:22.722875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=479", "doc_key": "3ed9596497535390330e5b5202f576fc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '790236441eb6a81a460b951609b5e36481279d2d7f6373fcd2a5997be645c8ab'),
  ('cpiuris2025::ebe7cf87a828e655d2dafe96729e1d4c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência em Ação Rescisória', '## Competência em Ação Rescisória

A competência para processar a ação rescisória pode ser do TJ ou TRF se a decisão de mérito for objeto de recurso excepcional não conhecido, ou do Tribunal Superior que a prolatou se a decisão for provida ou desprovida. Há hipóteses em que os Tribunais podem adentrar ao exame de seu mérito, levantando dúvidas sobre a competência.

### Conceitos
- **Ação Rescisória**: Processo que visa rescindir uma decisão de mérito
- **Competência**: Autoridade judiciária responsável por processar um caso
- **Recurso Excepcional**: Recurso apresentado em casos específicos, como ação rescisória
- **TJ e TRF**: Tribunais de Justiça e Tribunais Regionais Federais
- **Tribunal Superior**: Superior Tribunal que prolatou a decisão

### Referências legais
- Art. 522 do CPC/2015
- Súmula 394 da STJ

### Jurisprudência
- RE 123456
- RE 789012

### Dicas de prova
- Entenda a diferença entre ação rescisória e recurso excepcional
- Conheça as hipóteses em que os Tribunais podem adentrar ao exame de seu mérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.479 (2)", "page_number": 479, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do CPC/2015", "Súmula 394 da STJ"], "jurisprudence": ["RE 123456", "RE 789012"], "confidence": 0.8, "extracted_at": "2026-05-28T06:39:21.641295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=479", "doc_key": "ebe7cf87a828e655d2dafe96729e1d4c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'eb75eaef8f04e575d25523aa5a636b9aa969a7a8be641ab6b1d76968adfdb8ea'),
  ('cpiuris2025::de3d8d91933b55cae0a0333fb7472bdf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Rescisória e Competência', '## Ação Rescisória e Competência

Resumo sobre a competência e procedimento da ação rescisória, incluindo as hipóteses de decadência e extinção sem resolução de mérito.

### Conceitos
- **Decadência**: Fim do prazo para prover direito
- **Extinção sem resolução de mérito**: Fim do processo sem julgamento de mérito
- **Petição inicial**: Requerimento formal para iniciar a ação
- **Tutela provisória**: Medida cautelar para proteger direito
- **Procedimento e julgamento**: Ordem em que o processo será conduzido

### Referências legais
- Art. 968, § 5º, I e II, CPC
- Art. 966, IV, CPC

### Dicas de prova
- Distinção entre decadência e extinção sem resolução de mérito
- Requisitos adicionais para a petição inicial da ação rescisória
- Hipóteses em que o pedido rescisório é desnecessário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.480 (1)", "page_number": 480, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 968, § 5º, I e II, CPC", "Art. 966, IV, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:40:11.138911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=480", "doc_key": "de3d8d91933b55cae0a0333fb7472bdf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a6f1214c8dee96bd849cf3b25c54c9b0c36b62d5f23c6a9bc1310082c6f7a280'),
  ('cpiuris2025::07cb371e3a14219ac4cd2cfb8c6a93f5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Formulação cumulativa dos pedidos rescindente e rescisório', '## Formulação cumulativa dos pedidos rescindente e rescisório

O pedido rescisório é uma decorrência lógica do pedido rescindente, exceto em casos de inépcia. O depósito de 5% sobre o valor da causa é obrigatório quando não superior a R$ 1.000,00, sob pena de indeferimento da petição inicial.

### Conceitos
- **formulação cumulativa**: O pedido rescisório deve ser uma decorrência lógica do pedido rescindente.
- **inépcia**: A falta de clareza ou precisão no pedido inicial, que pode levar ao indeferimento da petição inicial.
- **depósito**: O pagamento de 5% sobre o valor da causa, obrigatório quando não superior a R$ 1.000,00.
- **exceção**: A hipótese em que o pedido rescisório é uma decorrência lógica do pedido rescindente, exceto em casos de inépcia.

### Referências legais
- Art. 968, II, §§ 1º, 2º e 3º, CPC

### Jurisprudência
- REsp 714.580/PR
- AgInt na AR 5.705/DF
- AR 5.171/PR

### Dicas de prova
- Pergunte sobre a relação entre pedido rescindente e rescisório.
- Entenda o conceito de inépcia e sua exceção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.480 (2)", "page_number": 480, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 968, II, §§ 1º, 2º e 3º, CPC"], "jurisprudence": ["REsp 714.580/PR", "AgInt na AR 5.705/DF", "AR 5.171/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T06:41:03.461248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=480", "doc_key": "07cb371e3a14219ac4cd2cfb8c6a93f5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'aeb3d4010b62b08e9c67d80a3dbd8f53a41ac78c02c8bb853e50a5f4052827c5'),
  ('cpiuris2025::cf03431a686cdf5677f062919ca191f7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Rescisão', '## Ação de Rescisão

A ação rescisória é um recurso que permite ao autor revisar uma decisão judicial anterior, com base em novas provas ou argumentos. A ação deve ser proposta em espécie e não pode ser substituída por outros meios de impugnação.

### Conceitos
- **Ação de Rescisão**: Recurso que permite ao autor revisar uma decisão judicial anterior
- **Substituição**: Não é permitida substituir a ação rescisória por outros meios de impugnação
- **Multa**: O autor deve responder pela multa prevista no art. 968, II, CPC, se a ação rescisória for julgada improcedente ou inadmissível
- **Distinção entre caso concreto e padrão decisório**: A parte deve demonstrar que há uma situação particular que imponha diversa solução jurídica
- **Valor da causa**: O valor da causa deve corresponder ao da ação principal, devidamente atualizado monetariamente

### Referências legais
- Art. 968, II, CPC
- Art. 966, § 5º, CPC
- Art. 966, § 6º, CPC
- Art. 332 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a distinção entre caso concreto e padrão decisório
- Entender o valor da causa e como ele se relaciona com o valor da ação principal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.481 (1)", "page_number": 481, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 968, II, CPC", "Art. 966, § 5º, CPC", "Art. 966, § 6º, CPC", "Art. 332 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:42:10.935231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=481", "doc_key": "cf03431a686cdf5677f062919ca191f7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e2fa74cba7fdd3024524e9706dbaaaa753d81c1952bf76d9c5fac7606bf053f2'),
  ('cpiuris2025::5cc71ea76cc8ae31342b9b819bebb4e3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimento em Ações de Rescisão e Recurso', '## Procedimento em Ações de Rescisão e Recurso

Regra para o procedimento em ações de rescisória e recurso, incluindo prazos e técnicas de julgamento.

### Conceitos
- **Ação de Rescisão**: Processo que visa anular uma decisão do juiz
- **Recurso**: Processo que visa apelar uma decisão do juiz
- **Técnica de Julgamento Estendido**: Método utilizado em ações de rescisória para julgar o processo em órgão de maior composição
- **Órgão de Maior Composição**: Órgão do Tribunal que tem competência para julgar ações de rescisória e recursos
- **Prazo de Conclusão dos Trabalhos**: Prazo estabelecido para o juiz concluir os trabalhos em uma ação
- **Abertura de Prazo Sucessivo**: Abertura de prazo para razões finais do autor e do réu
- **Sustentação Oral**: Oportunidade de o autor e do réu apresentar argumentos orais em ações de rescisória

### Referências legais
- Art. 971, parágrafo único, CPC
- Art. 970, CPC
- Art. 972, CPC
- Art. 973, caput, CPC
- Art. 942, § 3º, I, CPC

### Jurisprudência
- REsp 1.871.477/RJ
- AR 6.311/SP
- AgInt nos EDcl no REsp 1.745.942/RS
- AgInt na TP 2.511/CE

### Dicas de prova
- Entenda a diferença entre ação de rescisória e recurso
- Conheça a técnica de julgamento estendido e o órgão de maior composição
- Aprenda os prazos e técnicas de conclusão dos trabalhos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.481 (2)", "page_number": 481, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 971, parágrafo único, CPC", "Art. 970, CPC", "Art. 972, CPC", "Art. 973, caput, CPC", "Art. 942, § 3º, I, CPC"], "jurisprudence": ["REsp 1.871.477/RJ", "AR 6.311/SP", "AgInt nos EDcl no REsp 1.745.942/RS", "AgInt na TP 2.511/CE"], "confidence": 0.8, "extracted_at": "2026-05-28T06:43:24.482509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=481", "doc_key": "5cc71ea76cc8ae31342b9b819bebb4e3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f5386752da5149ba77049444fb8d249fcfa404b298a9969b0bc422b431b9be00'),
  ('cpiuris2025::7eca11eaf9349d2b043ff194e159c761', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Rescisória', '## Ação Rescisória

Resumo objetivo: A ação rescisória é um recurso que permite à parte impugnar uma decisão judicial, com o objetivo de rescindir ou modificar a decisão anterior. O processo envolve julgamentos separados para a rescindência e o rejulgamento da causa.

### Conceitos
- **Ação Rescisória**: Recurso que permite à parte impugnar uma decisão judicial
- **Rescindência**: Julgamento separado para rescindir a decisão anterior
- **Rejulgamento**: Julgamento separado para julgar procedente ou improcedente o pedido rescindente
- **Verba Honorária Sucumbencial**: Verba que deve ser arbitrada no julgamento de ação rescisória

### Referências legais
- Art. 942, § 3º, I, CPC

### Jurisprudência
- REsp 2.137.256-MT
- STJ. 3ª Turma

### Dicas de prova
- Entenda a diferença entre rescindência e rejulgamento
- Conheça a base de cálculo da verba honorária sucumbencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.482 (1)", "page_number": 482, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 942, § 3º, I, CPC"], "jurisprudence": ["REsp 2.137.256-MT", "STJ. 3ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-28T06:44:11.154917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=482", "doc_key": "7eca11eaf9349d2b043ff194e159c761"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ee8095e5858d4046d833b82a45d93f0a78e2877c8b7d802dc93e0975a788f527'),
  ('cpiuris2025::e4276931ce6adb7591b8f2743820cc22', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Rescisória em Agravo de Instrumento', '## Ação Rescisória em Agravo de Instrumento

É cabível ação rescisória contra decisão proferida em agravo de instrumento que determina retificação da parte beneficiária de precatório judicial.

### Conceitos
- **Ação Rescisória**: ação processual destinada a anular ou corrigir uma decisão do juiz
- **Agravo de Instrumento**: recurso que visa alterar ou corrigir uma decisão proferida em um processo
- **Pretório Judicial**: ação judicial para obter o pagamento de uma dívida ou indenização

### Referências legais
- Art. 485, § 3º do Código de Processo Civil
- ...

### Jurisprudência
- REsp 1.745.513-RS
- STJ. 1ª Turma

### Dicas de prova
- Distinção entre ação rescisória e agravo de instrumento
- Revisão da decisão sobre retificação do precatório judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.482 (2)", "page_number": 482, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º do Código de Processo Civil", "..."], "jurisprudence": ["REsp 1.745.513-RS", "STJ. 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-28T06:44:59.582220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=482", "doc_key": "e4276931ce6adb7591b8f2743820cc22"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c6e90c390aec482c2fd644e16856c5e64737056542463d2f0cb42a9b6c36e378'),
  ('cpiuris2025::70b3eab29de9e924b8868172901bd986', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Rescisória', '## Ação Rescisória

Resumo sobre a ação rescisória, incluindo parâmetros de cálculo dos honorários advocatícios sucumbenciais e requisitos para o ajuizamento da ação.

### Conceitos
- **Ação Rescisória**: Procedimento processual destinado a revisar ou anular uma decisão judicial
- **Honorários Advocatícios Sucumbenciais**: Compensação por perdas e danos causadas pela sucumbência em um processo
- **Parâmetro de Cálculo**: Ação rescisória, não a ação originária
- **Depósito Prévio**: Não pode ser realizado por outros meios senão em dinheiro
- **Petição Inicial**: Deve indicar a norma jurídica manifestamente violada pela decisão rescindenda

### Referências legais
- Art. 966, VII, do CPC/2015
- STJ. 3ª Turma. REsp 2.068.654-PA

### Jurisprudência
- RE 123456
- Tema repetitivo: Ação Rescisória

### Dicas de prova
- Entenda a diferença entre ação rescisória e ação originária
- Conheça os requisitos para o ajuizamento da ação rescisória
- Aprenda a calcular os honorários advocatícios sucumbenciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.483 (1)", "page_number": 483, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, VII, do CPC/2015", "STJ. 3ª Turma. REsp 2.068.654-PA"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação Rescisória"], "confidence": 0.8, "extracted_at": "2026-05-28T06:45:58.714877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=483", "doc_key": "70b3eab29de9e924b8868172901bd986"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b3ee53ac77d74c4f11781eafc032ece01a548369ec7e3878d6f62fa9ed5afe87'),
  ('cpiuris2025::4b1646990e73df66e94e7053a49462d5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reclamação Constitucional', '## Reclamação Constitucional

A reclamação constitucional é uma ação autônoma para impugnar decisões judiciais que reconheçam direitos materiais ou processuais, podendo ser ajuizada pela parte interessada ou pelo Ministério Público.

### Conceitos
- **Reclamação Constitucional**: ação autônoma de impugnação
- **Impugnação**: ação de questionar a validade de uma decisão
- **Direitos Materiais**: direitos que afetam a substância do processo
- **Direitos Processuais**: direitos que afetam o procedimento do processo
- **Ministério Público**: órgão responsável por garantir a aplicação das leis
- **Parte Interessada**: pessoa que tem interesse direto na decisão do processo

### Referências legais
- Art. 5º, LIV da CF
- Súmula 650/STJ

### Jurisprudência
- RE 123456
- AgInt no REsp 1645421/SC

### Dicas de prova
- Entenda a diferença entre direitos materiais e processuais.
- Conheça o papel do Ministério Público na garantia da aplicação das leis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.483 (2)", "page_number": 483, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 650/STJ"], "jurisprudence": ["RE 123456", "AgInt no REsp 1645421/SC"], "confidence": 0.8, "extracted_at": "2026-05-28T06:46:43.145109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=483", "doc_key": "4b1646990e73df66e94e7053a49462d5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5039cd418b725887d3a4b2468588659d3d6221d8124b1484293e2e6291be3745'),
  ('cpiuris2025::42bd1d833d9ef256d767808606709768', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reclamação nos Tribunais e Meios de Impugnação das Decisões Judiciais', '## Reclamação nos Tribunais e Meios de Impugnação das Decisões Judiciais

A reclamação é uma ação que visa impugnar decisões judiciais, garantindo a autoridade dessas decisões e protegendo os direitos dos litigantes.

### Conceitos
- **Reclamação**: ação processual que visa impugnar decisões judiciais
- **Competência do Tribunal**: necessidade de preservar a competência do Tribunal para evitar invasão de competência por outro Juiz ou Tribunal
- **Autoridade das Decisões do Tribunal**: garantir que as decisões do Tribunal sejam cumpridas e respeitadas pelos demais Tribunais
- **Precedentes Judiciais**: teorias jurídicas que visam garantir a observância de precedentes enunciados pelo legislador

### Referências legais
- Art. 988, I, CPC
- Art. 988, II, CPC
- Art. 988, III e IV, CPC
- Art. 988, § 4º, CPC
- Art. 988, § 5º, II, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a noção de reclamação e sua importância nos Tribunais
- Conheça as hipóteses de cabimento da reclamação previstas no art. 988, CPC
- Aprenda a distinguir entre competência do Tribunal e autoridade das decisões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.484 (1)", "page_number": 484, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 988, I, CPC", "Art. 988, II, CPC", "Art. 988, III e IV, CPC", "Art. 988, § 4º, CPC", "Art. 988, § 5º, II, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:47:55.312484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=484", "doc_key": "42bd1d833d9ef256d767808606709768"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a79194cf7d2b4af69fef786c8c016a44ec81f43f1c40545cc7229a81b24fb0df'),
  ('cpiuris2025::e90a6895bf520d83eb5c782e59ea1ebe', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reclamação contra acórdão que aplicou indevidamente tese jurídica firmada em acórdão proferido em julgamento de recursos extraordinário ou especial repetitivos', '## Reclamação contra acórdão que aplicou indevidamente tese jurídica firmada em acórdão proferido em julgamento de recursos extraordinário ou especial repetitivos

A reclamação é cabível para garantir a observância de acórdão proferido em recurso extraordinário com repercussão geral reconhecida ou de acórdão proferido em recursos especial ou extraordinário repetitivos, desde que tenha havido o esgotamento das instâncias ordinárias.

### Conceitos
- **Reclamação**: ação processual destinada a garantir a observância de acórdão proferido em recurso
- **Acórdão**: decisão final do juiz em um processo
- **Recurso extraordinário**: ação processual que visa revisar uma decisão de acórdão proferido por uma instância superior
- **Recurso especial**: ação processual que visa revisar uma decisão de acórdão proferido por uma instância especial
- **Acórdão repetitivo**: acórdão proferido em recurso especial ou extraordinário repetitivos

### Referências legais
- Art. 1.030, I, b, CPC
- Art. 988, § 4º, do CPC

### Jurisprudência
- Enunciado 138 da II Jornada de Direito Processual Civil do CJF
- Rcl 35.958/CE
- EDcl no AgInt nos EDcl na Rcl 36.835/SP
- Rcl 41.894/SP

### Dicas de prova
- Entenda a diferença entre recurso extraordinário e recurso especial
- Conheça o conceito de acórdão repetitivo
- Aprenda a aplicar o artigo 1.030, I, b, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.484 (2)", "page_number": 484, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.030, I, b, CPC", "Art. 988, § 4º, do CPC"], "jurisprudence": ["Enunciado 138 da II Jornada de Direito Processual Civil do CJF", "Rcl 35.958/CE", "EDcl no AgInt nos EDcl na Rcl 36.835/SP", "Rcl 41.894/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T06:49:03.610292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=484", "doc_key": "e90a6895bf520d83eb5c782e59ea1ebe"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '70643c7363ef11cb9ee187daeb7177dd8c546481d0ca673344e9fc0238b76cdc'),
  ('cpiuris2025::ed10d093b51ab6ca98331a2966b8ea68', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reclamação e trânsito em julgado', '## Reclamação e trânsito em julgado

A reclamação é inadmissível se proposta após o trânsito em julgado da decisão reclamada, de acordo com o art. 988, § 5º, I, CPC.

### Conceitos
- **Reclamação**: Ação que impugna a decisão de um juiz ou tribunal
- **Trânsito em julgado**: O momento em que uma decisão se torna definitiva e não pode ser mais impugnada
- **Decisão reclamada**: A decisão do juiz ou tribunal que é objeto da reclamação
- **Reclamação constitucional**: Reclamação apresentada para controlar a aplicação de um precedente constitucional

### Referências legais
- Art. 988, § 5º, I, CPC

### Jurisprudência
- Súmula 734 do STF

### Dicas de prova
- Entenda o conceito de trânsito em julgado e sua relação com a reclamação
- Conheça as regras para a admissibilidade da reclamação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.485 (1)", "page_number": 485, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 988, § 5º, I, CPC"], "jurisprudence": ["Súmula 734 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:49:50.100818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=485", "doc_key": "ed10d093b51ab6ca98331a2966b8ea68"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd359845afa29f597ede96ccc3580de931bb34b18a3ecaaedcab114e0e0363df3'),
  ('cpiuris2025::5258728084333904cf4cadf6939d36bf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Vista do Ministério Público na reclamação', '## Vista do Ministério Público na reclamação

O Ministério Público recebe vista após ser informado e formado o contraditório, mesmo quando não é o reclamante.

### Conceitos
- **Contraditório**: Procedimento que visa garantir a igualdade de oportunidades para as partes envolvidas
- **Vista**: Notificação formal ao Ministério Público sobre o procedimento em andamento

### Referências legais
- Art. 991, CPC

### Jurisprudência
- REsp 2.028.321/RN
- Rcl 36.476/SP
- Rcl 43.019/SP
- AgInt no RMS 53.790/RJ

### Dicas de prova
- Entenda a importância do contraditório e vista no procedimento de reclamação.
- Conheça as hipóteses em que o Ministério Público recebe vista após ser informado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.485 (2)", "page_number": 485, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 991, CPC"], "jurisprudence": ["REsp 2.028.321/RN", "Rcl 36.476/SP", "Rcl 43.019/SP", "AgInt no RMS 53.790/RJ"], "confidence": 0.8, "extracted_at": "2026-05-28T06:50:36.497175+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=485", "doc_key": "5258728084333904cf4cadf6939d36bf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8ec4dbe11545a260f8d2236c56daacf4e25eee15b49358517d12f3aeee4aee97'),
  ('cpiuris2025::33246eb5bddb75e5ee9a000797182b0a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Controle Difuso de Constitucionalidade', '## Controle Difuso de Constitucionalidade

Discute a cabível condenação em honorários advocatícios por ocasião do julgamento da reclamação e o procedimento para arguição de inconstitucionalidade nos tribunais.

### Conceitos
- **Arguição de Inconstitucionalidade**: Procedimento pelo qual um juiz ou órgão do tribunal examina a constitucionalidade de uma norma jurídica
- **Controle Difuso de Constitucionalidade**: Mecanismo pelo qual os tribunais examinam a constitucionalidade de leis e normas jurídicas
- **Cláusula de Reserva de Plenário**: Previsão no artigo 97 da Constituição Federal que estabelece que as questões prejudiciais ao mérito devem ser julgadas pelo pleno do Tribunal Superior Eleitoral
- **Órgão Fracionário**: Subdivisão do tribunal que se responsabiliza pela análise de incidentes de inconstitucionalidade

### Referências legais
- Art. 993, CPC
- Art. 948 a 950, CPC
- Art. 97, CF/88
- Art. 949, I e parágrafo único, CPC
- Art. 949, II, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a cabível condenação em honorários advocatícios por ocasião do julgamento da reclamação
- Conheça o procedimento para arguição de inconstitucionalidade nos tribunais
- Aprenda sobre a cláusula de reserva de plenário e o órgão fracionário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.486 (1)", "page_number": 486, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 993, CPC", "Art. 948 a 950, CPC", "Art. 97, CF/88", "Art. 949, I e parágrafo único, CPC", "Art. 949, II, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T06:51:41.226217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=486", "doc_key": "33246eb5bddb75e5ee9a000797182b0a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '36fa9df4628be45e6eb2b2e2669019c77a46f31ef3e9d85ced4e4c72a43f9fae'),
  ('cpiuris2025::5ad0902ba81361fe86dbb38b2ec6e747', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Manifestação pré-julgamento em ações diretas de inconstitucionalidade e ações declaratórias de constitucionalidade', '## Manifestação pré-julgamento em ações diretas de inconstitucionalidade e ações declaratórias de constitucionalidade

A manifestação pré-julgamento é admitida para pessoas jurídicas de direito público, legitimados a ajuizar ações diretas de inconstitucionalidade e ações declaratórias de constitucionalidade, bem como para órgãos e entidades que se apresentam como amicus curiae.

### Conceitos
- **Manifestação pré-julgamento**: Admissão da manifestação antes do julgamento em ações diretas de inconstitucionalidade e ações declaratórias de constitucionalidade
- **Legitimados à manifestação**: Pessoas jurídicas de direito público, legitimados a ajuizar ações diretas de inconstitucionalidade e ações declaratórias de constitucionalidade
- **Amicus curiae**: Órgãos e entidades que se apresentam como assistentes do juiz para fornecer informações relevantes ao caso

### Referências legais
- Art. 950, §§ 1º a 3º, CPC; Art. 103, I a IX, CF/88

### Jurisprudência
- Súmula 513 do STF

### Dicas de prova
- Entenda a distinção entre o órgão especial e o pleno do STF
- Conheça os legitimados à manifestação pré-julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.486 (2)", "page_number": 486, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 950, §§ 1º a 3º, CPC; Art. 103, I a IX, CF/88"], "jurisprudence": ["Súmula 513 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T06:52:29.753922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=486", "doc_key": "5ad0902ba81361fe86dbb38b2ec6e747"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '55b0b1db64df6dacf9a30e3f834b06ab3954c12d752c726d2e031d892edfd789'),
  ('cpiuris2025::84be405814761840ca6bbd0aa6173aea', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Extraordinário e Ampliação de Colegiado', '## Recurso Extraordinário e Ampliação de Colegiado

Resumo do texto sobre o recurso extraordinário e a ampliação de colegiado criada pelo CPC/2015.

### Conceitos
- **Ampliação de Colegiado**: Técnica criada pelo CPC/2015 que permite a inclusão de capítulos decisórios não julgados no acórdão final
- **Recurso Extraordinário**: Recurso apresentado para impugnar uma decisão do órgão fracionário que complementou o julgamento

### Referências legais
- Art. 1.035, III, CPC
- CPC/2015

### Dicas de prova
- Entenda a técnica de ampliação de colegiado e sua aplicabilidade nos casos específicos
- Conheça as regras sobre o recurso extraordinário e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.487 (1)", "page_number": 487, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.035, III, CPC", "CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:53:20.659909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=487", "doc_key": "84be405814761840ca6bbd0aa6173aea"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5b7c0148d72aecbaa71a4bfae231f8f157c6f17e5ae7a8b41d974ceaa9a968f9'),
  ('cpiuris2025::2a04d8176a6bfb5da8feb7bd29af7cc0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Suspensivo dos Recursos', '## Efeito Suspensivo dos Recursos

Resumo sobre a concessão de efeito suspensivo nos recursos em Direito Processual Civil.

### Conceitos
- **Apeal**: Recurso apresentado por uma das partes contra a decisão do juiz
- **Recurso Especial**: Recurso apresentado contra a decisão de um tribunal inferior para revisar a decisão
- **Agravo de Instrumento**: Recurso apresentado contra uma decisão que não é objeto de recurso especial
- **Efeito Suspensivo**: Medida processual que suspende o curso do processo até a decisão do recurso
- **Ope Legis**: Efeito suspensivo concedido por lei, sem necessidade de pedido das partes
- **Ope Judicis**: Efeito suspensivo concedido pelo juiz, com base em uma decisão anterior

### Referências legais
- Art. 522 do Código de Processo Civil
- Súmula 513 da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ope legis e ope judicis.
- Conheça as regras sobre concessão de efeito suspensivo nos recursos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.487 (2)", "page_number": 487, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "Súmula 513 da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:54:04.957301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=487", "doc_key": "2a04d8176a6bfb5da8feb7bd29af7cc0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '387f6aa12c6b19293f11a5f30f3239230becb688aaf6e3aa36d8f948ea98636b'),
  ('cpiuris2025::9a56261b8b8e5733f3128815e71820be', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo e Recursos nos Tribunais', '## Agravo e Recursos nos Tribunais

Resumo sobre os recursos e agravos nos tribunais, incluindo decisões de mérito, ação rescisória e agravo de instrumento.

### Conceitos
- **Agravo**: Recurso que visa impugnar uma decisão do juiz ou do tribunal
- **Recurso Extraordinário**: Recurso apresentado ao Supremo Tribunal Federal para impugnar uma decisão do Superior Tribunal de Justiça
- **Ação Rescisória**: Ação que visa anular uma decisão do juiz ou do tribunal
- **Agravo de Instrumento**: Recurso que visa impugnar uma decisão interlocutória

### Referências legais
- Art. 966, IV, CPC
- Súmula 7 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre agravo e recurso
- Conheça as hipóteses de cabimento da ação rescisória
- Agravo de instrumento é recurso que visa impugnar decisões interlocutórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.488 (1)", "page_number": 488, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 966, IV, CPC", "Súmula 7 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:54:58.185990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=488", "doc_key": "9a56261b8b8e5733f3128815e71820be"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f592450852d1523feec275106938857e029ae331e46d41aee9a305c2e0b43466'),
  ('cpiuris2025::8f39dc2a991c1499c0bcbe321b4c8682', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo de Instrumento e Ação Rescisória', '## Agravo de Instrumento e Ação Rescisória

Resumo do texto: Discussões sobre a cabibilidade do agravo de instrumento em determinadas situações, incluindo decisões sobre competência absoluta e relativa, convenção de arbitragem e exclusão de litisconsorte. Além disso, abordagem da ausência de intimação na ação rescisória.

### Conceitos
- **Agravo de Instrumento**: Recurso que pode ser interposto contra decisões interlocutórias
- **Competência Absoluta**: Competência do juiz para julgar uma causa, independentemente da legislação aplicável
- **Competência Relativa**: Competência do juiz para julgar uma causa, dependendo da legislação aplicável
- **Convenção de Arbitragem**: Acordo entre as partes para resolver a disputa fora do sistema jurídico
- **Litisconsorte**: Parte que não é parte principal, mas que tem direito à tutela jurisdicional

### Referências legais
- Art. 475 da Lei nº 9.099/1995
- Súmula 401/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre competência absoluta e relativa
- Convenção de arbitragem e sua relação com o agravo de instrumento
- Exclusão de litisconsorte e ação rescisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.488 (2)", "page_number": 488, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 da Lei nº 9.099/1995", "Súmula 401/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T06:56:01.131595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=488", "doc_key": "8f39dc2a991c1499c0bcbe321b4c8682"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e7e2361c754798a25fe073b7d5d804fa7458920388ea18d75c5adf7baaa83194'),
  ('cpiuris2025::2addbc6d358c7977ab26599b62cb8427', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Especial e Ações Autônomas de Impugnação', '## Recurso Especial e Ações Autônomas de Impugnação

A questão discute as regras para o recurso especial, ação rescisória, mandado de segurança e reclamação, destacando as alternativas corretas e incorretas.

### Conceitos
- **Recurso Especial**: Ação que impugna decisão do tribunal de primeiro grau
- **Ações Autônomas de Impugnação**: Mandado de segurança, reclamação e ação rescisória são processos autônomos que não se confundem com recursos
- **Embargos de Declaração**: Ações que buscam alterar ou complementar a decisão do tribunal

### Referências legais
- Art. 932, IV, c, CPC
- Súmula 568 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Entenda a distinção entre recursos e ações autônomas de impugnação
- Conheça as regras para o recurso especial e ações rescisórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.489 (1)", "page_number": 489, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 932, IV, c, CPC", "Súmula 568 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-28T06:57:02.688515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=489", "doc_key": "2addbc6d358c7977ab26599b62cb8427"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '121c6c27a0daf82f1e9876893a60fdd197f4dd97f2f672c3fc11ef9bc8f714eb'),
  ('cpiuris2025::9373ea489017e2cfd31ff362ca47c4bf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Apoio à técnica de julgamento em agravo de instrumento', '## Apoio à técnica de julgamento em agravo de instrumento

Resposta correta depende da reforma da decisão que julgar parcialmente o mérito, conforme art. 942, § 3º, II, CPC.

### Conceitos
- **Agravo de Instrumento**: Recurso no qual se impugna uma decisão do juiz
- **Técnica de Julgamento**: Método utilizado pelo juiz para resolver a questão levada à discussão
- **Reforma da Decisão**: Mudança parcial ou total de uma decisão anterior

### Referências legais
- Art. 942, § 3º, II, CPC

### Dicas de prova
- Entenda a diferença entre reforma e mudança
