  ('cpiuris2025::f118d5ec8e7731c691615bb543b6cb89', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Suspensivo nos Recursos', '## Efeito Suspensivo nos Recursos

Questões sobre o efeito suspensivo nos recursos em processos judiciais, incluindo agravo de instrumento, embargos de declaração e ações rescisórias.

### Conceitos
- **Agravo de Instrumento**: Recurso que impugna decisão parcial de mérito
- **Efeito Suspensivo**: O direito de suspender a execução de uma decisão judiciária
- **Embargos de Declaração**: Recurso que impugna decisões parciais de mérito
- **Ações Rescisórias**: Recurso que busca anular uma decisão judiciária

### Referências legais
- Art. 942, § 3º, II, CPC
- Art. 987, § 1º, CPC
- Art. 1.019, I, CPC
- Art. 1.026, § 1º, CPC
- Art. 1.030, I, a, 1ª parte e § 2º, CPC
- Art. 1.030, I, b e § 2º, CPC
- Art. 966, § 2º, I e II, CPC
- Art. 968, I, CPC
- Art. 932, IV e VI, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Incidente de Arguição de Inconstitucionalidade

### Dicas de prova
- Entenda a diferença entre agravo de instrumento e embargos de declaração
- Conheça as hipóteses em que se admite o efeito suspensivo nos recursos
- Aprenda a aplicar as regras de procedimento nos processos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.490 (1)", "page_number": 490, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 942, § 3º, II, CPC", "Art. 987, § 1º, CPC", "Art. 1.019, I, CPC", "Art. 1.026, § 1º, CPC", "Art. 1.030, I, a, 1ª parte e § 2º, CPC", "Art. 1.030, I, b e § 2º, CPC", "Art. 966, § 2º, I e II, CPC", "Art. 968, I, CPC", "Art. 932, IV e VI, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Incidente de Arguição de Inconstitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-28T06:59:15.054662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=490", "doc_key": "f118d5ec8e7731c691615bb543b6cb89"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9aed2bfaef99940cfaf2fea4a583e603aff1d76fa38ef1a8d3947e2cac629c0b'),
  ('cpiuris2025::5a5b4cb188760e6668f672475d5c8d18', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazos processuais', '## Prazos processuais

A questão discute sobre os prazos processuais e a aplicabilidade das normas do artigo 937 do CPC.

### Conceitos
- **Competência absoluta**: A competência do juiz que não depende de uma causa determinada.
- **Competência relativa**: A competência do juiz que depende de uma causa determinada.
- **Prazo processual**: O período dentro do qual deve ser feito um ato processual.
- **Rejeição de alegação de convenção de arbitragem**: A decisão que rejeita a alegação de convenção de arbitragem é impugnável por agravo de instrumento.

### Referências legais
- Art. 937, caput e IX, CPC; Art. 7º, § 2º-B, Lei 8.906/94; Art. 942, § 3º, II e § 4º, II e III, CPC

### Dicas de prova
- Entenda a distinção entre competência absoluta e relativa.
- Conheça as normas do artigo 937 do CPC.
- Aprenda com o tema repetitivo 988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.490 (2)", "page_number": 490, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 937, caput e IX, CPC; Art. 7º, § 2º-B, Lei 8.906/94; Art. 942, § 3º, II e § 4º, II e III, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T06:59:58.997904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=490", "doc_key": "5a5b4cb188760e6668f672475d5c8d18"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fcee1632304c9b63cb633f6ff730d28f68d120761363947f228a7a69d45aad46'),
  ('cpiuris2025::5beff7ea6ad61a66fbfaad298983ade8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recorribilidade per saltum ao STJ', '## Recorribilidade per saltum ao STJ

A recorribilidade per saltum ao STJ é permitida em processos que envolvem Estado estrangeiro ou organismo internacional e Município ou pessoa domiciliada ou residente no país, tanto no mérito quanto nas interlocutórias.

### Conceitos
- **Recorribilidade per saltum**: Permitida em processos que envolvem Estado estrangeiro ou organismo internacional e Município ou pessoa domiciliada ou residente no país
- **STJ**: Superior Tribunal de Justiça, órgão jurisdicional do sistema judiciário brasileiro

### Referências legais
- Art. 1.027, II, b, CPC
- Art. 1.027, § 1º, CPC
- Art. 968, CPC

### Jurisprudência
- AR 6.463-SP
- STJ. 2ª Seção

### Dicas de prova
- Entenda a noção de recorribilidade per saltum e sua aplicação nos processos mencionados
- Conheça as regras do artigo 1.027, II, b, CPC e seu significado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.491", "page_number": 491, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.027, II, b, CPC", "Art. 1.027, § 1º, CPC", "Art. 968, CPC"], "jurisprudence": ["AR 6.463-SP", "STJ. 2ª Seção"], "confidence": 0.8, "extracted_at": "2026-05-28T07:00:48.782481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=491", "doc_key": "5beff7ea6ad61a66fbfaad298983ade8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e5752bf87975c1ae126ba337dbc2508d00ac9b9ce018af3058e86badcb7629d8'),
  ('cpiuris2025::2c1fb7997d4bf6990a1bd4922e2f8be1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão de Liminar e Sentença', '## Suspensão de Liminar e Sentença

As pessoas jurídicas de direito privado podem formular pedido de suspensão de segurança em defesa do interesse público primário, correspondente aos interesses da coletividade como um todo. O prazo para a Fazenda Pública interpor agravo interno é de 15 dias, contados em dobro.

### Conceitos
- **Legitimidade para formular pedido de suspensão**: Pessoas jurídicas de direito privado podem formular pedido de suspensão se prestadoras de serviço público ou exercendo função delegada pelo Poder Público
- **Interesse público primário**: Corresponde aos interesses da coletividade como um todo

### Referências legais
- Art. 273, § 2º, do CPC; Art. 5º, inciso XXI, da CF

### Jurisprudência
- STJ. Corte Especial. EDcl no AgInt na SLS 3.156-AM
- STJ. Corte Especial. AgInt na SLS 3.204-SP
- Súmula 626 do STF

### Dicas de prova
- Distinção entre interesse público primário e secundário
- Prazo para a Fazenda Pública interpor agravo interno em Suspensão de Liminar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.494 (2)", "page_number": 494, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273, § 2º, do CPC; Art. 5º, inciso XXI, da CF"], "jurisprudence": ["STJ. Corte Especial. EDcl no AgInt na SLS 3.156-AM", "STJ. Corte Especial. AgInt na SLS 3.204-SP", "Súmula 626 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T13:35:22.640464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=494", "doc_key": "2c1fb7997d4bf6990a1bd4922e2f8be1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '27979771dddb57e82273fe4d1eec6a0813302875cc075a06c585f127efd6a4af'),
  ('cpiuris2025::bf1bf141a611b24960da70e2c1cb5d63', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão de Segurança', '## Suspensão de Segurança

A anulação dos atos administrativos e da licitação não é suficiente para demonstrar ofensa ao interesse público. É necessário comprovar risco de dano grave e impossível reparação.

### Conceitos
- **Anulação**: Ato administrativo ou licitação declarado nulo
- **Suspensão de Segurança**: Medida cautelar para proteger direito
- **Interesse Público**: Direito que se opõe ao interesse individual
- **Dano Grave**: Prejuízo irreparável

### Referências legais
- Art. 522 do Código de Processo Civil
- ...

### Jurisprudência
- STJ - Súmula 504/2017
- RE 123456

### Dicas de prova
- Distinção entre anulação e suspensão de segurança
- Requisitos para a concessão da suspensão de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.495", "page_number": 495, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "..."], "jurisprudence": ["STJ - Súmula 504/2017", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T13:36:05.392280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=495", "doc_key": "bf1bf141a611b24960da70e2c1cb5d63"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '406b17f48b95f1661aca74df32f617602ccb7e8630a969d3119e9bd340ac56f7'),
  ('cpiuris2025::2823be97c1d5e36556bd7202bf62677c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo Coletivo', '## Processo Coletivo

O processo coletivo é uma nova realidade global que exige a tutela de direitos e interesses comuns, diferentemente da tutela individual. Os direitos podem ser classificados em difusos, coletivos stricto sensu e individuais homogêneos.

### Conceitos
- **Tutela Coletiva**: A tutela de direitos e interesses comuns
- **Difusos**: Direitos que dizem respeito a uma parcela indeterminada de pessoas, ligadas a uma mesma circunstância de fato
- **Coletivos Stricto Sensu**: Direitos que possuem característica de indivisibilidade e têm interessados determinados a partir de uma relação jurídica base
- **Individuais Homogêneos**: Direitos que são divisíveis e podem ser especificamente atribuídos e quantificados aos seus respectivos titulares

### Referências legais
- Art. 81, parágrafo único, I a III da Lei n.º 8.078/1990 - CDC

### Dicas de prova
- Entenda a distinção entre difusos e coletivos stricto sensu
- Identifique os exemplos de direitos individuais homogêneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.496 (1)", "page_number": 496, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 81, parágrafo único, I a III da Lei n.º 8.078/1990 - CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T13:36:59.453928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=496", "doc_key": "2823be97c1d5e36556bd7202bf62677c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '674ace4adc5ba00cd579399f40b8230381deee6f04f1da5ad7484f2e137aee72'),
  ('cpiuris2025::11cf9542c97d25adac39974763b56847', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo Coletivo', '## Processo Coletivo

Rege-se o processo coletivo sobre princípios específicos, buscando soluções nas normas do microssistema de tutela coletiva, com exceção das hipóteses em que o CPC é aplicado residualmente.

### Conceitos
- **Microssistema**: conjunto de normas que compõem o processo coletivo
- **Tutela Coletiva**: proteção a um grupo de pessoas ou entidades
- **CPC**: Código de Processo Civil
- **Processo Coletivo**: procedimento destinado a resolver litígios de natureza coletiva

### Referências legais
- Art. 8 da Lei n.º 7.437/1985
- Lei n.º 4.717/1965

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de microssistema e sua relação com a tutela coletiva.
- Conheça as hipóteses em que o CPC é aplicado residualmente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.496 (2)", "page_number": 496, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 8 da Lei n.º 7.437/1985", "Lei n.º 4.717/1965"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T13:37:51.008299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=496", "doc_key": "11cf9542c97d25adac39974763b56847"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1ec05295a5bdc2b0b01936f7858000379b95ec556d132f068292001a829a5736'),
  ('cpiuris2025::8e3e77aaf7f83f6c57a88ae36b1dd1c1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo Coletivo', '## Processo Coletivo

O processo coletivo é um instrumento de realização da democracia participativa, com princípios como a participação da sociedade, a primazia do conhecimento do mérito e a indisponibilidade da demanda coletiva.

### Conceitos
- **Participação**: Involvement da sociedade na realização da justiça
- **Princípio da primazia do conhecimento do mérito**: O exame do mérito da tutela veiculada na ação coletiva deve ser priorizado sobre o formalismo
- **Indisponibilidade da demanda coletiva**: A demanda coletiva não pode ser dispensada, mas sim superada pelo interesse público

### Referências legais
- Art. 2º, caput e parágrafo único da Lei n.º 7.347/1985

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre participação e diálogo no processo coletivo
- Conheça os princípios que regem o processo coletivo, como a primazia do conhecimento do mérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.497 (1)", "page_number": 497, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º, caput e parágrafo único da Lei n.º 7.347/1985"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T13:38:44.273154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=497", "doc_key": "8e3e77aaf7f83f6c57a88ae36b1dd1c1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '63217dc6c90d56a8e604b6229459133b48688620fb76b0da52ceafe97762aade'),
  ('cpiuris2025::c3849234557e7e9887e79d6353a38047', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para ajuizamento de ações coletivas', '## Competência para ajuizamento de ações coletivas

A competência para ajuizamento de ações coletivas é do local do fato, ressalvada hipótese de ação popular concorrente.

### Conceitos
- **Competência**: A competência é o direito de um juízo ou tribunal julgar uma causa.
- **Local do Fato**: O local onde ocorreu o fato que serve como base para a ação coletiva.
- **Legitimidade Ativa**: A capacidade de um partido para propor uma ação no juízo.
- **Ação Popular**: Uma ação que pode ser proposta por qualquer cidadão contra o Estado ou entidades públicas.
- **Litisconsórcio**: O estado de dois ou mais pessoas que se encontram no mesmo processo.
- **Ministério Público**: O órgão do Estado responsável por fiscalizar a aplicação das leis e garantir a ordem pública.
- **Defensoria Pública**: Um advogado que atua em favor de pessoas pobres ou sem recursos para defender seus direitos.
- **Ação Coletiva**: Uma ação que visa proteger o interesse de um grupo de pessoas.

### Referências legais
- Art. 82, I a IV do CDC

### Jurisprudência
- REsp 1.978.138/SP
- CC 164.362/MG

### Dicas de prova
- Pergunte sobre o conceito de competência e local do fato.
- Entenda a legitimidade ativa para ajuizamento de ações coletivas.
- Conheça as hipóteses em que a competência é do local do fato ou da União, Estado, Distrito Federal e Município.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.497 (2)", "page_number": 497, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 82, I a IV do CDC"], "jurisprudence": ["REsp 1.978.138/SP", "CC 164.362/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T13:39:56.053975+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=497", "doc_key": "c3849234557e7e9887e79d6353a38047"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cc5c8ce30d5d6cca3fb5303525e0f481e26d2e71325f04396bd7a2443430bca8'),
  ('cpiuris2025::b0a2d8fed502edf1d138a696d487c2c3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litispendência e Tutela Coletiva', '## Litispendência e Tutela Coletiva

A litispendência é uma barreira processual que impede a repetição de uma ação judicial. A tutela coletiva, por outro lado, visa proteger direitos individuais homogêneos. O Ministério Público pode promover a tutela coletiva, mas apenas em casos com relevante natureza social.

### Conceitos
- **Litispendência**: Barreira processual que impede a repetição de uma ação judicial
- **Tutela Coletiva**: Proteção de direitos individuais homogêneos
- **Ministério Público**: Instituição que pode promover a tutela coletiva em casos com relevante natureza social

### Referências legais
- Art. 94, CDC
- Súmula 626/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tutela Coletiva

### Dicas de prova
- Entenda a diferença entre litispendência e tutela coletiva
- Conheça as hipóteses em que o Ministério Público pode promover a tutela coletiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.498 (1)", "page_number": 498, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 94, CDC", "Súmula 626/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tutela Coletiva"], "confidence": 0.8, "extracted_at": "2026-05-28T13:41:07.883189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=498", "doc_key": "b0a2d8fed502edf1d138a696d487c2c3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2f6d650f7e72fea735232111efe8d61536e6c05eaea7287b346541537dd8c72e'),
  ('cpiuris2025::aa6065eda7f90639119057c3638aa226', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Coisas julgadas e litispendência em ações coletiva e individual', '## Coisas julgadas e litispendência em ações coletiva e individual

Não há coisa julgada e litispendência entre ação coletiva e individual devido às diferenças nos sujeitos, pedidos e direito do indivíduo de renunciar à jurisdição coletiva.

### Conceitos
- **Coisas julgadas**: Conceito jurídico que se refere à decisão final de um processo que não pode ser alterada ou modificada por outro processo.
- **Litispendência**: Conceito jurídico que se refere à situação em que dois ou mais processos apresentam a mesma questão de fato e são julgados simultaneamente.
- **Ação coletiva**: Processo em que vários indivíduos comuns se unem para buscar uma tutela jurídica contra um ou mais responsáveis por um dano ou lesão.
- **Ação individual**: Processo em que um indivíduo busca uma tutela jurídica contra um ou mais responsáveis por um dano ou lesão.

### Referências legais
- Art. 95 do CDC
- Art. 104 do CDC

### Dicas de prova
- Diferenças nos sujeitos e pedidos entre ação coletiva e individual
- Direito do indivíduo de renunciar à jurisdição coletiva
- Conceito de coisa julgada e litispendência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.498 (2)", "page_number": 498, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 95 do CDC", "Art. 104 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T13:42:13.556167+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=498", "doc_key": "aa6065eda7f90639119057c3638aa226"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '700b54fe9838aa3f8b8baf0d85b4371f96feececd826e94f7f01060c60cd4c6a'),
  ('cpiuris2025::1d135e2d08ef14006fd8de668962cab3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo Coletivo', '## Processo Coletivo

O processo coletivo é um campo fértil para a participação da sociedade, com audiências públicas, amicus curiae e divulgação ampla. A Fazenda Pública deve adiantar honorários periciais em certas hipóteses.

### Conceitos
- **Audiência pública**: Reunião de pessoas interessadas para discutir um assunto
- **Amicus curiae**: Parte que ajuda o juiz em uma causa sem ser parte
- **Contraditório**: Procedimento que visa garantir a justiça e a igualdade de todas as partes
- **Tutela provisória**: Medida temporária para proteger um direito ou evitar uma lesão
- **Fazenda Pública**: Entidade que representa o Estado em uma causa

### Referências legais
- Art. 2º, parágrafo único, da Lei n.º 7.347/1985
- Art. 18 da Lei n.º 7.347/1985
- Art. 91, CPC
- Art. 4º da Lei n.º 7.347/1985
- Art. 305 e seguintes do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das audiências públicas no processo coletivo.
- Conheça as regras sobre a admissão de amicus curiae e divulgação ampla.
- Destaque a necessidade da tutela provisória em ações coletivas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.499 (1)", "page_number": 499, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º, parágrafo único, da Lei n.º 7.347/1985", "Art. 18 da Lei n.º 7.347/1985", "Art. 91, CPC", "Art. 4º da Lei n.º 7.347/1985", "Art. 305 e seguintes do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T13:43:27.705686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=499", "doc_key": "1d135e2d08ef14006fd8de668962cab3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '108244e1ad318c9498ece897996fda09d2c7324b06a4b5876d80f5815b7aa95f'),
  ('cpiuris2025::0f66b7f81cb08bd2cd7a18bbed911427', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória em Ações Coletivas e Individual', '## Tutela Provisória em Ações Coletivas e Individual

A concessão de tutela provisória não está impedida pela negação da tutela provisória na ação coletiva, podendo ser concedida em ação individual.

### Conceitos
- **Tutela Provisória**: Medida cautelar adotada antes do julgamento da ação principal.
- **Ações Coletivas**: Processos que envolvem vários réus ou demandantes.
- **Contraditório**: Direito do réu de ser ouvido em juízo.
- **Amicus Curiae**: Advogado nomeado pelo juiz para assistir na ação.
- **Divulgação e Publicidade**: Obrigação de divulgar e publicar as ações judiciais.

### Referências legais
- Art. 273 do Código de Processo Civil
- Súmula 619 do FPPC

### Jurisprudência
- REsp 1.884.062/SP
- Tema repetitivo: Tutela Provisória em Ações Coletivas

### Dicas de prova
- Distinção entre a concessão de tutela provisória na ação coletiva e individual.
- Importância da divulgação e publicidade das ações judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.499 (2)", "page_number": 499, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "Súmula 619 do FPPC"], "jurisprudence": ["REsp 1.884.062/SP", "Tema repetitivo: Tutela Provisória em Ações Coletivas"], "confidence": 0.8, "extracted_at": "2026-05-28T13:44:30.559838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=499", "doc_key": "0f66b7f81cb08bd2cd7a18bbed911427"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'facb630bc258a834fdf638be24e28c7b3021da0339cba4af3453b19ba8535ae7'),
  ('cpiuris2025::e3ae234f99fe36109c2696a304871a61', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recorribilidade das interlocutórias em ações coletivas', '## Recorribilidade das interlocutórias em ações coletivas

A regras de recorribilidade das interlocutórias em ações coletivas, especialmente aquelas proferidas em ações populares e civis públicas.

### Conceitos
- **Recurribilidade**: O direito de recorrer uma decisão interlocutória
- **Ação Popular**: Ação coletiva que visa proteger um interesse ou direito comum
- **Código de Processo Civil**: Lei que regula o processo civil no Brasil
- **Cosa Julgada**: Conceito jurídico que se refere à imutabilidade da decisão proferida em uma ação
- **Eventum Probatio**: A probabilidade de serem verdadeiras as provas apresentadas na ação
- **Eventum Litis**: O resultado da ação, ou seja, o que é decidido pela justiça
- **Código de Defesa do Consumidor**: Lei que regula os direitos do consumidor no Brasil

### Referências legais
- Art. 19, § 1º da Lei n.º 4.717/1965
- Art. 1.015, XIII, CPC
- Art. 103, § 3º, CDC
- Lei 8.429/1992
- Lei 14.230/2021

### Jurisprudência
- RE 123456
- Tema repetitivo do STJ sobre a regras de recorribilidade das interlocutórias em ações coletivas

### Dicas de prova
- Entenda a diferença entre o eventum probatio e o eventum litis
- Conheça as regras de recorribilidade das interlocutórias em ações coletivas
- Aprenda a aplicar a coisa julgada secundum eventum litis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.500 (1)", "page_number": 500, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 19, § 1º da Lei n.º 4.717/1965", "Art. 1.015, XIII, CPC", "Art. 103, § 3º, CDC", "Lei 8.429/1992", "Lei 14.230/2021"], "jurisprudence": ["RE 123456", "Tema repetitivo do STJ sobre a regras de recorribilidade das interlocutórias em ações coletivas"], "confidence": 0.8, "extracted_at": "2026-05-28T13:46:06.744802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=500", "doc_key": "e3ae234f99fe36109c2696a304871a61"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c7c8ead095a55f2d7a820180a459e3edd004924c0a9fece9f61e7ca52deb0579'),
  ('cpiuris2025::0d7a721e88d2dce8ef858b18a4f8f5a9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão da ação individual em relação à ação coletiva', '## Suspensão da ação individual em relação à ação coletiva

O autor de ação individual deve requerer suspensão da ação para aproveitar a sentença da ação coletiva, sob pena de não poder dela se utilizar.

### Conceitos
- **coisa julgada**: Conceito jurídico que se refere à decisão final do juiz em uma ação
- **direitos e interesses em discussão**: Elementos que são objeto de disputa na ação
- **ação individual**: Ação proposta por um indivíduo
- **ação coletiva**: Ação proposta por uma coligação de pessoas
- **suspensão da ação**: Mudança no curso da ação para evitar que ela seja julgada antes do seu termo

### Referências legais
- Art. 104, CDC

### Jurisprudência
- REsp 1.733.540/DF
- AgInt no REsp 1.733.540/DF
- REsp 1.828.295/MG
- REsp 1.768.359/MG
- REsp 1.925.492/RJ

### Dicas de prova
- Pergunte se a suspensão da ação individual é obrigatória ou facultativa.
- Entenda o conceito de coisa julgada e como ela se aplica às ações de consumo.
- Identifique os direitos e interesses em discussão nas ações de consumo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.500 (2)", "page_number": 500, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 104, CDC"], "jurisprudence": ["REsp 1.733.540/DF", "AgInt no REsp 1.733.540/DF", "REsp 1.828.295/MG", "REsp 1.768.359/MG", "REsp 1.925.492/RJ"], "confidence": 0.8, "extracted_at": "2026-05-28T13:47:12.681850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=500", "doc_key": "0d7a721e88d2dce8ef858b18a4f8f5a9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7f9ce724874ad54136c829e0fc0144c78c9381e91f39bd83984ef19c669783e2'),
  ('cpiuris2025::ff80d2939d64de232184aacd7570a9d4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cosa Julgada em Processos Coletivos e Individuais', '## Cosa Julgada em Processos Coletivos e Individuais

A coisa julgada em processos coletivos é ultra partes, limitada ao grupo, categoria ou classe, salvo se a improcedência decorrer de insuficiência de prova. Já na hipótese de interesse individual homogêneo, a coisa julgada é erga omnes, somente no caso de procedência do pedido.

### Conceitos
- **Ultra partes**: Limitação da coisa julgada ao grupo, categoria ou classe
- **Erga omnes**: Benefício da sentença para todas as vítimas em caso de procedência do pedido
- **Legitimidade extraordinária**: Amplia capacidade para defender os interesses de toda a categoria

### Referências legais
- Art. 103, III, Código de Defesa do Consumidor (CDC)

### Jurisprudência
- STJ. 4ª Turma. REsp 1.762.278-MG
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre ultra partes e erga omnes
- Conheça a legitimidade extraordinária das entidades sindicais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.501 (1)", "page_number": 501, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 103, III, Código de Defesa do Consumidor (CDC)"], "jurisprudence": ["STJ. 4ª Turma. REsp 1.762.278-MG", "RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T13:48:12.965155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=501", "doc_key": "ff80d2939d64de232184aacd7570a9d4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fe57e382e3f54a3035604990c54a405f2170f2a1d0aeb978037c86ddcfa62683'),
  ('cpiuris2025::b36e0392f1b3fd392efce6bf76b31251', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos da Sentença Coletiva em Ações Coletivas', '## Efeitos da Sentença Coletiva em Ações Coletivas

A apresentação de listagem dos substituídos no momento do ajuizamento da ação coletiva não implica restrição dos efeitos da coisa julgada. A sentença coletiva tem efeito erga omnes, exceto quando o direito tutelado alcança apenas um subgrupo da categoria.

### Conceitos
- **Coisa Julgada**: Conceito jurídico que se refere à decisão final de uma ação judicial
- **Efeitos Erga Omnes**: Efeito que se estende a todos os interessados, independentemente da presença ou ausência de parte adversária
- **Ações Coletivas**: Procedimentos jurídicos que visam proteger direitos coletivos de uma categoria de pessoas
- **Sentença Coletiva**: Decisão final em ação coletiva que tem efeito erga omnes

### Referências legais
- Art. 76, parágrafo único, do Código Civil

### Jurisprudência
- REsp 2.030.944-RJ
- STJ. 1ª Turma. REsp 2.030.944-RJ

### Dicas de prova
- Entenda a diferença entre coisa julgada e efeitos erga omnes
- Conheça as limitações da sentença coletiva em relação à categoria profissional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.501 (2)", "page_number": 501, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 76, parágrafo único, do Código Civil"], "jurisprudence": ["REsp 2.030.944-RJ", "STJ. 1ª Turma. REsp 2.030.944-RJ"], "confidence": 0.8, "extracted_at": "2026-05-28T13:49:03.844419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=501", "doc_key": "b36e0392f1b3fd392efce6bf76b31251"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '39fbb600bdd0105cfed561c3b2087d60cc81bfda7c16998e7fad6492e7d15314'),
  ('cpiuris2025::7fea71c56fc17f0073901f0c07d9fd37', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo Coletivo', '## Processo Coletivo

Regras e diretrizes para processos coletivos, incluindo a eficácia subjetiva da coisa julgada e a liquidação de sentenças coletivas.

### Conceitos
- **Causa Julgada**: Conceito jurídico que se refere à decisão final do juiz em um processo
- **Liquidação**: Procedimento pelo qual o valor de uma condenação é quantificado
- **Eficácia Subjetiva**: Conceito jurídico que se refere à capacidade de um título processual de produzir efeitos em relação ao devido sujeito
- **Beneficiário Substituído Processualmente**: Pessoa que substitui o beneficiário original no processo coletivo
- **Custo Judicial**: Valor pago ao juiz ou ao tribunal por causa de uma ação judicial

### Referências legais
- Art. 97, caput, CDC
- STJ. 1ª Seção. REsp 1.966.058-AL
- STF. Plenário. RE 612043/PR

### Jurisprudência
- RE 612043/PR
- STJ. Corte Especial. EREsp 1.367.220-PR
- STJ. 2ª Turma. AgInt no AREsp 2.399.352-MA

### Dicas de prova
- Entenda a eficácia subjetiva da coisa julgada em processos coletivos
- Conheça as regras de liquidação de sentenças coletivas
- Aprenda a distinguir entre beneficiário substituído processualmente e o beneficiário original', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.502 (1)", "page_number": 502, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 97, caput, CDC", "STJ. 1ª Seção. REsp 1.966.058-AL", "STF. Plenário. RE 612043/PR"], "jurisprudence": ["RE 612043/PR", "STJ. Corte Especial. EREsp 1.367.220-PR", "STJ. 2ª Turma. AgInt no AREsp 2.399.352-MA"], "confidence": 0.8, "extracted_at": "2026-05-28T13:50:11.789699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=502", "doc_key": "7fea71c56fc17f0073901f0c07d9fd37"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a8c60ea193b9ca08ca53ae803dfd8313ed74ff180e6442cdf4b7fa4aef0796a8'),
  ('cpiuris2025::3e1e947d9996ef0883475e922088facb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação e Execução', '## Liquidação e Execução

Regra sobre liquidação e execução em casos de ausência de interesse público ou social, com isenções legais.

### Conceitos
- **Art. 18 da Lei n.º 7.347/1985**: Lei que regula a liquidação e execução em casos de ausência de interesse público ou social.
- **Art. 87 do CDC**: Código de Defesa do Consumidor, que regula as relações entre consumidores e fornecedores.
- **Liquidação promovida por associação**: Procedimento em que uma associação representa os titulares do direito material.
- **Execução coletiva**: Procedimento em que o Ministério Público tem legitimação ativa para promover a execução.
- **Execução residual**: Procedimento em que o Ministério Público não tem legitimação ativa para promover a execução.

### Referências legais
- Art. 18 da Lei n.º 7.347/1985
- Art. 87 do CDC
- Art. 100, parágrafo único, CDC
- Art. 2º, III, do Decreto n.º 1.306/1994

### Jurisprudência
- REsp 1.798.280/SP
- REsp 1.637.366/SP
- REsp 1.955.899/PR

### Dicas de prova
- Entenda a diferença entre liquidação e execução em casos de ausência de interesse público ou social.
- Conheça as isenções legais previstas na Lei n.º 7.347/1985.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.502 (2)", "page_number": 502, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 18 da Lei n.º 7.347/1985", "Art. 87 do CDC", "Art. 100, parágrafo único, CDC", "Art. 2º, III, do Decreto n.º 1.306/1994"], "jurisprudence": ["REsp 1.798.280/SP", "REsp 1.637.366/SP", "REsp 1.955.899/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T13:51:26.400462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=502", "doc_key": "3e1e947d9996ef0883475e922088facb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e0e03727c4a987581c1e99f8b0d831cbac28695022efe1ae084450f1f6321b62'),
  ('cpiuris2025::3006aa4e701ec8c09b4ba4f198f7951c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença Coletiva', '## Cumprimento de Sentença Coletiva

A execução da sentença coletiva deve ser promovida pela associação autora e, subsidiariamente, pelo Ministério Público ou outros legitimados. A liquidação e execução do título executivo judicial coletivo não são legítimas em foros aleatórios sem relação com as comarcas dos beneficiários.

### Conceitos
- **Legitimidade**: O direito de agir em um processo
- **Substituição Processual**: A substituição do autor ou da autora de uma ação por outra pessoa
- **Cumprimento de Sentença Coletiva**: O ato de cumprir a sentença proferida em uma ação coletiva
- **Título Executivo Judicial Coletivo**: Um título que se refere ao direito de receber um valor devido pela sentença coletiva
- **Foro Natural**: O foro onde o processo foi iniciado

### Referências legais
- Art. 15 da Lei n.º 7.347/1985

### Jurisprudência
- STJ. 1ª Seção. REsps 2.078.485-PE, 2.078.989-PE, 2.078.993-PE e 2.079.113-PE, Rel. Min. Herman Benjamin

### Dicas de prova
- Entenda a legitimidade para a liquidação e execução da sentença coletiva
- Conheça a substituição processual e sua importância
- Aprenda sobre o cumprimento de sentença coletiva e seus requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.503 (1)", "page_number": 503, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 15 da Lei n.º 7.347/1985"], "jurisprudence": ["STJ. 1ª Seção. REsps 2.078.485-PE, 2.078.989-PE, 2.078.993-PE e 2.079.113-PE, Rel. Min. Herman Benjamin"], "confidence": 0.8, "extracted_at": "2026-05-28T13:52:30.444453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=503", "doc_key": "3006aa4e701ec8c09b4ba4f198f7951c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd5f5228e458d0b5bd0945f59ea63ed7d2e058cdb7cda5f1991a42e766f110290'),
  ('cpiuris2025::740ea02d3637d72cf860ec8ebe5cdf2c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Indenização por Dano Moral e Material', '## Ação de Indenização por Dano Moral e Material

Revisão da jurisprudência sobre a ação de indenização por dano moral e material, destacando a aplicabilidade do artigo 23 da Lei nº 7.853/89.

### Conceitos
- **Ação de Indenização**: ação processual destinada a obter uma indenização por dano sofrido
- **Dano Moral e Material**: dano que afeta a pessoa física ou jurídica, resultando em prejuízo econômico ou emocional
- **Art. 23 da Lei nº 7.853/89**: artigo que estabelece as regras para a ação de indenização por dano moral e material

### Referências legais
- Art. 23 da Lei nº 7.853/89

### Jurisprudência
- REsp 1.801.518/RJ
- REsp 1.758.708/MS
- REsp 1.438.263/SP
- REsp 1.866.440/AL
- CC 199.938/SP

### Dicas de prova
- Distinção entre dano moral e material
- Aplicabilidade do artigo 23 da Lei nº 7.853/89', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.503 (2)", "page_number": 503, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 23 da Lei nº 7.853/89"], "jurisprudence": ["REsp 1.801.518/RJ", "REsp 1.758.708/MS", "REsp 1.438.263/SP", "REsp 1.866.440/AL", "CC 199.938/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T13:53:15.189386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=503", "doc_key": "740ea02d3637d72cf860ec8ebe5cdf2c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dacbce60ba771e88fdbb720f1c0e4cd52053529dc3d3098fe825ed083ef14d5c'),
  ('cpiuris2025::0e5e9a16a784d25067f950efdbc60b42', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Juizados Especiais', '## Juizados Especiais

Os Juizados Especiais são compostos por juízes togados ou por juízes togados e leigos, competentes para conciliação, julgamento e execução de causas cíveis de menor complexidade e de infrações de menor potencial ofensivo.

### Conceitos
- **Conciliação**: Procedimento que visa resolver o litígio por meio de negociação entre as partes.
- **Transação**: Acordo entre as partes para resolver o litígio, com ou sem a intervenção do juiz.
- **Rito sumaríssimo**: Procedimento que exclui todos os demais procedimentos especiais e é utilizado em casos de menor complexidade.

### Referências legais
- Art. 98, I, da Constituição Federal
- Lei nº 9.099/1995
- Lei nº 10.259/2001
- Lei nº 12.153/2009
- Art. 1.063 do Código de Processo Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre procedimento sumaríssimo e rito especial.
- Conhecimento dos critérios adotados nos Juizados Especiais, como a conciliação e a transação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.505", "page_number": 505, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 98, I, da Constituição Federal", "Lei nº 9.099/1995", "Lei nº 10.259/2001", "Lei nº 12.153/2009", "Art. 1.063 do Código de Processo Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T13:54:19.479331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=505", "doc_key": "0e5e9a16a784d25067f950efdbc60b42"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e423d615a88bd28d4664b68039ab501f853855d4b62fc4e7fa5600659e4e21b1'),
  ('cpiuris2025::e105fe68fa600c56b5f58d5d53321d07', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência nos Juizados Especiais', '## Competência nos Juizados Especiais

Discute-se a competência dos Juizados Especiais Estaduais e Federais, bem como as matérias que não podem ser abordadas nesses juízos.

### Conceitos
- **Competência nos Juizados Especiais**: A competência dos Juizados Especiais Estaduais e Federais é estabelecida pela lei.
- **Causas de menor complexidade**: As causas cujo conteúdo econômico não ultrapasse 40 (quarentA) salários mínimos
- **Valor limitado**: O valor limitado é o limite acima do qual as causas são consideradas de menor complexidade.
- **Matérias não abordáveis nos Juizados Especiais Federais**: As matérias que não podem ser abordadas nos Juizados Especiais Federais incluem, por exemplo, as causas entre Estado estrangeiro ou organismo internacional e Município ou pessoa domiciliada ou residente no País.

### Referências legais
- Art. 3º da Lei n. 9.099/1995
- Art. 275, inciso II do CPC/1973
- Art. 1.063 do CPC/2016
- Art. 3º da Lei n. 10.259/2001

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a competência dos Juizados Especiais Estaduais e Federais.
- Conheça as matérias que não podem ser abordadas nos Juizados Especiais Federais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.506 (1)", "page_number": 506, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 3º da Lei n. 9.099/1995", "Art. 275, inciso II do CPC/1973", "Art. 1.063 do CPC/2016", "Art. 3º da Lei n. 10.259/2001"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T13:57:30.077305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=506", "doc_key": "e105fe68fa600c56b5f58d5d53321d07"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b322b008b4a8baa238b75763ff51c23eb9c21de98fdd306992c8f0cd315c665d'),
  ('cpiuris2025::3c529a94073098b843e12a02b2cc98b4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais Cíveis', '## Competência dos Juizados Especiais Cíveis

Resumo objetivo: Discute a competência dos juizados especiais cíveis em determinadas causas, especialmente aquelas previstas no art. 275, inciso II, da Lei nº 5.869/73.

### Conceitos
- **Competência**: A capacidade do juiz de processar e julgar uma causa
- **Juizados Especiais Cíveis**: Instituição jurídica que processa e julga causas específicas, previstas em lei
- **Lei nº 9.099/95**: Lei que instituiu os juizados especiais cíveis
- **Lei nº 5.869/73**: Lei que prevê a competência dos juizados especiais cíveis em determinadas causas

### Referências legais
- Art. 1.063
- Art. 275, inciso II da Lei nº 5.869/73

### Dicas de prova
- Entenda a competência dos juizados especiais cíveis e como ela se aplica às causas previstas na Lei nº 5.869/73.
- Reconheça a importância da Lei nº 9.099/95 no instituição dos juizados especiais cíveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.506 (2)", "page_number": 506, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.063", "Art. 275, inciso II da Lei nº 5.869/73"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T13:58:15.823275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=506", "doc_key": "3c529a94073098b843e12a02b2cc98b4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '143bc1ef4fcf7944ed0947422109222d0dd9e0bd8851ebc1b198c5b759aadf66'),
  ('cpiuris2025::d25cf13555a95bc1ec4b8c3de00be824', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais da Fazenda Pública', '## Competência dos Juizados Especiais da Fazenda Pública

Os Juizados Especiais da Fazenda Pública têm competência absoluta para julgar demandas com valor não superior a R$ 60.000,00, excetuados casos específicos como impugnação de pena de demissão ou sanções disciplinares.

### Conceitos
- **Competência Absoluta**: A competência dos Juizados Especiais da Fazenda Pública é absoluta, não dependendo de valor ou complexidade do processo.
- **Exceções à Competência**: Existem exceções à competência dos Juizados Especiais da Fazenda Pública, como impugnação de pena de demissão ou sanções disciplinares.

### Referências legais
- Art. 103 do Código de Processo Civil
- Lei n. 9.099/1995, art. 3º, § 3º

### Jurisprudência
- AgInt nos EDcl no AREsp 2.201.340/RS
- Súmula 773 do STJ

### Dicas de prova
- Entenda a competência absoluta dos Juizados Especiais da Fazenda Pública e as exceções à sua competência.
- Aprenda a interpretação teleológico-sistemática do § 3º do art. 3º da Lei n. 9.099/1995.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.507 (1)", "page_number": 507, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 103 do Código de Processo Civil", "Lei n. 9.099/1995, art. 3º, § 3º"], "jurisprudence": ["AgInt nos EDcl no AREsp 2.201.340/RS", "Súmula 773 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T13:59:22.727072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=507", "doc_key": "d25cf13555a95bc1ec4b8c3de00be824"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '31b8510a57267f7131f519cb8a0859f508166b421e911685ed8da24d41a8b926'),
  ('cpiuris2025::0551aad7823c6e78fee30a7a66deccbf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência entre juizados especiais e juízos cíveis', '## Competência entre juizados especiais e juízos cíveis

A competência é absoluta para o especial fazendário, de acordo com a Lei n. 10.259/2001 e a Lei n. 12.153/2009. O STJ estabeleceu a súmula 428, que determina a competência do Tribunal Regional Federal em conflitos entre Juizado Especial Federal e Juízo federal da mesma seção judiciária.

### Conceitos
- **Competência absoluta**: A competência é absoluta para o especial fazendário, de acordo com a Lei n. 10.259/2001 e a Lei n. 12.153/2009.
- **Súmula 428 do STJ**: Determina a competência do Tribunal Regional Federal em conflitos entre Juizado Especial Federal e Juízo federal da mesma seção judiciária.
- **Competência estadual**: A competência é atribuída ao Tribunal de Justiça quando se trata de conflito envolvendo o Juízo da Justiça Comum e o Juizado Especial Estadual.
- **Juizado Especial Federal**: Um juizado especial federal é um órgão judiciário que processa e julga ações relacionadas à administração pública federal.

### Referências legais
- Art. 3º, § 3º, da Lei n. 10.259/2001
- Art. 2º, § 4º, da Lei n. 12.153/2009

### Jurisprudência
- Súmula 428 do STJ

### Dicas de prova
- Pergunte sobre a competência absoluta para o especial fazendário.
- Entenda a súmula 428 do STJ e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.507 (2)", "page_number": 507, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 3º, § 3º, da Lei n. 10.259/2001", "Art. 2º, § 4º, da Lei n. 12.153/2009"], "jurisprudence": ["Súmula 428 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T14:00:19.656182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=507", "doc_key": "0551aad7823c6e78fee30a7a66deccbf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd161f9983b6b296977649721f4c81a58013e17894355182163cb20a072b06849'),
  ('cpiuris2025::d38199d388deb1fcefb89cae7aae5a29', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade Ativa nos Juizados Especiais Estaduais', '## Legitimidade Ativa nos Juizados Especiais Estaduais

As pessoas físicas capazes, microempresas e OSCIPs podem propor ações nos Juizados Especiais Estaduais. Além disso, é permitido litisconsórcio, mas as empresas individualmente não podem demandar se fazem parte de um grupo econômico com receita bruta superior ao limite para Empresa de Pequeno Porte.

### Conceitos
- **Legitimidade Ativa**: O direito de uma pessoa ou entidade realizar uma ação judicial
- **Juizados Especiais Estaduais**: Um tipo de juizado que processa causas com valor até 20 salários mínimos
- **Microempresas**: Empresas com receita bruta anual inferior a R$ 1,2 milhão
- **OSCIPs**: Organizações Civis de Interesse Público

### Referências legais
- Art. 104 do Código de Processo Civil
- Enunciado n. 172 do FONAJE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a legitimidade ativa nos Juizados Especiais Estaduais e como as microempresas e OSCIPs podem propor ações.
- Entenda a diferença entre legitimidade ativa e passiva e como elas se aplicam aos diferentes tipos de juizados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.508", "page_number": 508, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 104 do Código de Processo Civil", "Enunciado n. 172 do FONAJE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T14:01:11.356059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=508", "doc_key": "d38199d388deb1fcefb89cae7aae5a29"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0fd4778614397d8682145aabd1750c6f992e31edd971d9ddf9e0e5c1d3a484dc'),
  ('cpiuris2025::5525ca3aaa759bd1bcf7d4fe6c5486b7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitidade Passiva nos Juizados Especiais Federais e da Fazenda Pública', '## Legitidade Passiva nos Juizados Especiais Federais e da Fazenda Pública

Os legitimados passivos que podem ser demandados nos juizados especiais federais incluem a União, autarquias e fundações públicas e empresas públicas federais. Já nos juizados especiais da fazenda pública, os estados, DF e municípios, autarquias e fundações públicas estaduais, distritais ou municipais podem figurar no polo passivo.

### Conceitos
- **Legitidade Passiva**: O direito de uma parte ser demandada em um processo
- **Juizados Especiais Federais**: Um tipo de juizado especial que processa casos federais
- **Fazenda Pública**: A entidade pública responsável por realizar atividades públicas
- **Polo Passivo**: O lado da ação que apresenta o direito ou a pretensão do réu
- **Legitimidade Passiva**: O direito de uma parte ser demandada em um processo

### Referências legais
- Art. 109, § 2º, do CPC

### Dicas de prova
- Entenda a noção de legitimidade passiva e como ela se aplica aos juizados especiais federais e da fazenda pública.
- Conheça as diferenças entre os dois tipos de juizados especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.509", "page_number": 509, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109, § 2º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:03:08.685959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=509", "doc_key": "5525ca3aaa759bd1bcf7d4fe6c5486b7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0da3794f3ab03b3bcb48114c4a13583ace09eee369c6bd801f21cf4ff99133dd'),
  ('cpiuris2025::b320ae5a12bd9b28af76ef3bba84a6d6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Requisitos e Procedimento das Tutelas de Urgência nos Juizados Especiais Federais e da Fazenda Pública', '## Requisitos e Procedimento das Tutelas de Urgência nos Juizados Especiais Federais e da Fazenda Pública

As tutelas de urgência podem ser concedidas nos Juizados Especiais Federais e da Fazenda Pública, mas não no Juizado Especial Estadual. A impugnação pode ser feita por meio de recursos ou mandado de segurança.

### Conceitos
- **Tutela de Urgência**: Medida provisória que visa proteger direito ou interesse legítimo
- **Juizados Especiais Federais**: Instância especial do Poder Judiciário federal
- **Citação**: Procedimento pelo qual a parte é notificada de um processo
- **Audiência de Conciliação**: Ato processual em que as partes tentam chegar a um consenso

### Referências legais
- Art. 20 do Código de Processo Civil
- Lei n. 10.259/2001
- Lei n. 12.153/2009
- Lei n. 9.099/1995
- Lei n. 13.994/2020

### Jurisprudência
- Súmula 482 do STF
- Tema repetitivo: Tutela de Urgência nos Juizados Especiais Federais

### Dicas de prova
- Distinção entre a tutela de urgência e a antecipação da tutela provisória
- Requisitos para a citação em juizado especial
- Objetivo da audiência de conciliação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.510 (1)", "page_number": 510, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 20 do Código de Processo Civil", "Lei n. 10.259/2001", "Lei n. 12.153/2009", "Lei n. 9.099/1995", "Lei n. 13.994/2020"], "jurisprudence": ["Súmula 482 do STF", "Tema repetitivo: Tutela de Urgência nos Juizados Especiais Federais"], "confidence": 0.8, "extracted_at": "2026-05-28T14:04:13.960712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=510", "doc_key": "b320ae5a12bd9b28af76ef3bba84a6d6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8816dca845db1002d518223ec07a31dd958e2504d523ecf087edbad137e2c7c6'),
  ('cpiuris2025::a688dc28b9ea19a97a3464c18d044b49', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tentativa de Conciliação e Processo', '## Tentativa de Conciliação e Processo

Regras para tentativa de conciliação em processo, incluindo redução a escrito e extinção do processo.

### Conceitos
- **Tentativa de Conciliação**: Procedimento utilizado para resolver o litígio fora da tribunal.
- **Audiência de Conciliação**: Ato em que as partes se reúnem com o juiz para tentar chegar a um acordo.
- **Mandado de Citação**: Instrumento processual que notifica o réu da existência do processo e do prazo para comparecimento.
- **Extinção do Processo**: Fim do processo devido à ausência ou recusa de uma das partes.
- **Audiência de Instrução e Julgamento**: Ato em que o juiz analisa as provas apresentadas pelas partes e proferencia sentença.

### Referências legais
- Art. 22, § 2º, Lei n. 9.099/1995
- Art. 23, Lei n. 9.099/1995

### Dicas de prova
- Diferenciar entre tentativa de conciliação e audiência de instrução e julgamento.
- Entender a importância do mandado de citação na tentativa de conciliação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.510 (2)", "page_number": 510, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 22, § 2º, Lei n. 9.099/1995", "Art. 23, Lei n. 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:05:04.022569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=510", "doc_key": "a688dc28b9ea19a97a3464c18d044b49"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ce41cfb07ef402fcd7602f58e8e6a3a56843f435d727a75c64bca602a002ab40'),
  ('cpiuris2025::1eb0ce4be0fc1a38dc737ade80a9359d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Instrução e Julgamento nos Juizados Especiais', '## Audiência de Instrução e Julgamento nos Juizados Especiais

Resumo do texto sobre audiência de instrução e julgamento nos Juizados Especiais, incluindo a apresentação da resposta do réu, produção de prova, sentença e extinção do feito.

### Conceitos
- **Audiência de Instrução e Julgamento**: Ato em que as partes apresentam suas provas e o juiz ouvinte as instrui antes de proferir a sentença.
- **Resposta do Réu**: Apresentação da resposta do réu no início da audiência de instrução e julgamento, que pode ser oral ou escrita.
- **Prova**: Produção de evidências para convencer o juiz sobre a veracidade dos fatos.
- **Sentença**: Decisão final do juiz que encerra o processo.
- **Extinção do Feito**: Fim do processo devido a uma causa legítima, como a renúncia do autor ou a extinção da ação por tempo.

### Referências legais
- Art. 31 da Lei n. 9.099/1995

### Dicas de prova
- Pergunte sobre a apresentação da resposta do réu, produção de prova e sentença nos Juizados Especiais.
- Entenda a diferença entre audiência de instrução e julgamento e extinção do feito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.511", "page_number": 511, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 31 da Lei n. 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:06:25.990234+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=511", "doc_key": "1eb0ce4be0fc1a38dc737ade80a9359d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5082c77c0096b223b231bf5474db1eb86f2b5d0d5f808fdcbe4e76c8c9e812fc'),
  ('cpiuris2025::272624b5a25e80e977eb298fa6d70caa', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso em Juizados Especiais', '## Recurso em Juizados Especiais

Resumo do texto sobre o recurso em Juizados Especiais, incluindo embargos de declaração, recurso inominado e agravos.

### Conceitos
- **Embargos de declaração**: Mêdio de impugnação à decisão judicial, cabível por escrito ou oralmente no prazo de 5 dias
- **Recurso inominado**: Recurso que pode ser proposto perante o próprio órgão prolator da decisão, com efeito devolutivo
- **Agravo de instrumento**: Mêdio de impugnação à decisão judicial, cabível no prazo de 10 dias

### Referências legais
- Art. 1.026 do CPC
- Art. 5º da Lei n. 10.259/2001

### Jurisprudência
- Informativo n. 777, STJ

### Dicas de prova
- Distinção entre embargos de declaração e agravos de instrumento
- Regra específica para o recurso inominado em Juizados Especiais Federais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.512", "page_number": 512, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.026 do CPC", "Art. 5º da Lei n. 10.259/2001"], "jurisprudence": ["Informativo n. 777, STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T14:07:20.312827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=512", "doc_key": "272624b5a25e80e977eb298fa6d70caa"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0f122499fc48a7bf3f44c5b7f394641ade1b66e3bf150ca9e14008442a43b110'),
  ('cpiuris2025::7a826e8a91e37db85bd8a94f89627905', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso e Ações no Juizado Especial', '## Recurso e Ações no Juizado Especial

Discute-se os recursos cabíveis e ações permitidas perante o Juizado Especial, incluindo agravo de instrumento, agravo interno, recurso extraordinário, mandado de segurança, ação rescisória e reclamação.

### Conceitos
- **Agravo de Instrumento**: Recurso cabível em sede de Juizados Especiais da Fazenda Pública
- **Agravo Interno**: Recurso cabível na Turma Recursal quando o julgamento se der por meio de decisão monocrática
- **Recurso Extraordinário**: Recurso possível contra decisão da turma recursal, com base na Súmula 640 do STF
- **Mandado de Segurança**: Ação constitucional adotada perante turma recursal para impugnar decisão interlocutória
- **Ação Rescisória**: Vedação expressa ao seu manejo em qualquer processo que tramitar perante o Juizado Especial
- **Reclamação**: Ação cabível após o advento do CPC/2015, restrita à hipótese de decisão de Turma Recursal Estadual

### Referências legais
- Art. 3º e 4º da Lei 12.153/09
- Súmula 640 do STF
- Art. 59 da Lei n. 9.099/1995
- Resolução n. 12/2009 do STJ
- Resolução n. 03/2016 do STJ

### Jurisprudência
- RMS 48.413/MS
- Súmula 376 do STJ

### Dicas de prova
- Distinção entre recurso e ação autônoma
- Prerogativa do magistrado apresentar informações ao Tribunal
- Excepcionalidade da impetração de mandado de segurança nos Tribunais de Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.513", "page_number": 513, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 3º e 4º da Lei 12.153/09", "Súmula 640 do STF", "Art. 59 da Lei n. 9.099/1995", "Resolução n. 12/2009 do STJ", "Resolução n. 03/2016 do STJ"], "jurisprudence": ["RMS 48.413/MS", "Súmula 376 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T14:08:35.528075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=513", "doc_key": "7a826e8a91e37db85bd8a94f89627905"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9d77d8e36efd066c54fd2013d51541cf5195aded31f6492bbd84de83bf0c596c'),
  ('cpiuris2025::510171f5e0e821fdce71b3b9ce16a79f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Uniformização de Interpretação de Lei', '## Competência e Uniformização de Interpretação de Lei

Discute a competência para processar e julgar Reclamações destinadas a dirimir divergência entre acórdão prolatado por Turma Recursal Estadual e jurisprudência do STJ, bem como para garantir a observância de precedentes.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar uma causa
- **Uniformização de Interpretação de Lei**: O processo de sanar divergência entre turmas recursais distintas sobre a interpretação da lei federal

### Referências legais
- Art. 1º da Resolução n. 03/2016
- Art. 14, § 4º, da Lei n. 10.259/2001

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência para processar e julgar Reclamações destinadas a dirimir divergência entre acórdão prolatado por Turma Recursal Estadual e jurisprudência do STJ.
