  ('cpiuris2025::1998c924297574cba033a800fb794dd4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução por quantia certa no Juizado Especial estadual', '## Execução por quantia certa no Juizado Especial estadual

O procedimento para cumprir sentença em Juizado Especial envolve o art. 52 da Lei nº 9.099/1995, exigindo requerimento do interessado e cálculos simples realizados pelo servidor do cartório.

### Conceitos
- **Juizado Especial**: instituição processual específica
- **execução por quantia certa**: procedimento para cumprir sentença
- **art. 52 da Lei nº 9.099/1995**: disposição legal que regula o procedimento

### Referências legais
- Art. 52 da Lei nº 9.099/1995

### Dicas de prova
- Requerimento do interessado é imprescindível
- Cálculos simples realizados pelo servidor do cartório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.514 (2)", "page_number": 514, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 52 da Lei nº 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:10:05.650369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=514", "doc_key": "1998c924297574cba033a800fb794dd4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b02d0e815a87484ab1f6e9f3f09d56abff0871debf2e3f25573d964b4c711cad'),
  ('cpiuris2025::7a67a7ab98a1332fe18a9e72f6d77db6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução por Quantia Certa no Juizado Especial Federal e Fazendário', '## Execução por Quantia Certa no Juizado Especial Federal e Fazendário

Regras para a execução de quantias certas em juizados especiais federais, incluindo procedimentos para embargos, audiência de conciliação e liquidação.

### Conceitos
- **Embargos**: Solicitação feita pelo executado para impugnar a decisão do juiz
- **Impugnação**: Termo equivalente a embargos, utilizado no art. 52, IX, da Lei n. 9.099/1995
- **Audiência de conciliação**: Reunião entre o juiz e as partes para tentar resolver a disputa sem julgamento
- **Liquidação**: Ato pelo qual se determina o valor da dívida e é feita a penhora dos bens penhoráveis

### Referências legais
- Art. 52, IX, da Lei n. 9.099/1995
- Art. 53 da Lei n. 9.099/1995
- Art. 17 da Lei n. 10.259/2001
- Art. 13 da Lei n. 12.153/2009

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre embargos e impugnação
- Conheça o procedimento para audiência de conciliação
- Registre a importância da liquidação em execução por quantia certa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.515 (1)", "page_number": 515, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 52, IX, da Lei n. 9.099/1995", "Art. 53 da Lei n. 9.099/1995", "Art. 17 da Lei n. 10.259/2001", "Art. 13 da Lei n. 12.153/2009"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T14:11:04.391929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=515", "doc_key": "7a67a7ab98a1332fe18a9e72f6d77db6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0a3e393b2987e3214ed98da17979730e504d8a69921adfba33a54a5fffd39a81'),
  ('cpiuris2025::2b76738760db70320da42b3965ece087', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Juizados Especiais da Fazenda Pública', '## Juizados Especiais da Fazenda Pública

A questão discute a cabível reclamação ao Superior Tribunal de Justiça em casos de divergência entre decisões proferidas por Turmas Recursais sobre questões de direito processual e quando a decisão recorrida estiver em contrariedade com súmula do tribunal superior.

### Conceitos
- **Lei dos Juizados Especiais Cíveis**: Lei que regula os Juizados Especiais Cíveis
- **Reclamação ao Superior Tribunal de Justiça**: Ação para impugnar decisão do tribunal superior
- **Turmas Recursais**: Comissões que analisam recursos apresentados por partes interessadas

### Referências legais
- Art. 53 da Lei n. 9.099/1995

### Dicas de prova
- Entenda a cabível reclamação ao Superior Tribunal de Justiça em casos de divergência entre decisões proferidas por Turmas Recursais.
