  ('cpiuris2025::1d41105f3e4f1ab945c5166596c84005', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Juizados Especiais Cíveis', '## Juizados Especiais Cíveis

Regras e limitações para os Juizados Especiais Cíveis, incluindo competência, recursos, intervenção de terceiros e execução da sentença.

### Conceitos
- **Competência dos Juizados Especiais Cíveis**: A competência dos Juizados Especiais Cíveis é estabelecida pela Lei nº 10.259/2001
- **Recursos nos Juizados Especiais Cíveis**: Os recursos nos Juizados Especiais Cíveis são recebidos no efeito devolutivo e suspensivo como regra geral
- **Intervenção de Terceiros nos Juizados Especiais Cíveis**: Não se admite intervenção de terceiro, assistência ou litisconsórcio nos processos dos Juizados Especiais Cíveis
- **Execução da Sentença nos Juizados Especiais Cíveis**: A execução da sentença nos Juizados Especiais Cíveis é feita mediante intimação ao advogado público responsável pela representação jurídica do ente público
- **Prova Oral nos Juizados Especiais Cíveis**: A prova oral será produzida na audiência de instrução e julgamento, podendo o Juiz limitar ou excluir o que considerar excessivo, impertinente ou protelatório
- **Competência Materna nos Juizados Especiais Cíveis**: A competência materna nos Juizados Especiais Cíveis é estabelecida pela Lei nº 10.259/2001

### Referências legais
- Art. 109 da Lei nº 9.503/1997
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo dos Juizados Especiais Cíveis

### Dicas de prova
- Pergunta sobre competência dos Juizados Especiais Cíveis
- Pergunta sobre recursos nos Juizados Especiais Cíveis
- Pergunta sobre intervenção de terceiros nos Juizados Especiais Cíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.516 (1)", "page_number": 516, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da Lei nº 9.503/1997", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo dos Juizados Especiais Cíveis"], "confidence": 0.8, "extracted_at": "2026-05-28T14:13:10.506517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=516", "doc_key": "1d41105f3e4f1ab945c5166596c84005"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd0ec3ba7eaa60bdc8356a30df5d23d015d3b6c51f073bef10032f1591947910b'),
  ('cpiuris2025::203d97a59d3629be63a74fc49471b34f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução da Sentença', '## Execução da Sentença

Resumo sobre a execução da sentença em juizado especial federal, destacando as opções de procedimento.

### Conceitos
- **Juizado Especial Federal**: Instituição do juizado especial federal para processar causas específicas.
- **Competência**: A capacidade do tribunal de julgar uma causa.
- **Turma Recursal**: Unidade judiciária que processa e julga recursos.
- **Princípio da Reserva de Plenário**: Regra que determina a necessidade de voto de todos os membros do tribunal para que uma decisão seja proferida.

### Referências legais
- Art. 114, § 3º, da LDO
- Súmula 634/STJ
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo sobre competência e turma recursal ...

### Dicas de prova
