- Conheça as opções de procedimento para a execução da sentença em juizado especial federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.516 (2)", "page_number": 516, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114, § 3º, da LDO", "Súmula 634/STJ", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo sobre competência e turma recursal ..."], "confidence": 0.8, "extracted_at": "2026-05-28T14:13:50.851754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=516", "doc_key": "203d97a59d3629be63a74fc49471b34f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3e605c0b3f8598038fa14baed81f50c12f25246d5cd5943c594161885a9ffb8b'),
  ('cpiuris2025::51341524e92c06f3e846f37c0344b1cd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Juizados Especiais Cíveis', '## Juizados Especiais Cíveis

As assertivas apresentadas sobre Juizados Especiais Cíveis são analisadas para determinar qual está correto.

### Conceitos
- **Assertiva**: afirmação que pode ser correta ou incorreta
- **Competência**: habilidade do juiz de julgar um caso
- **Citação**: notificação formal do executado para pagamento ou penhora de bens
- **Execução da sentença**: procedimento para cobrar uma sentença

### Referências legais
- Art. 114 do Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 456.123
- ...

### Dicas de prova
- Entenda a competência dos Juizados Especiais e como eles diferem da Justiça Comum
- Conheça as regras de execução da sentença nos Juizados Especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.517 (1)", "page_number": 517, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 456.123", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T14:14:43.813797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=517", "doc_key": "51341524e92c06f3e846f37c0344b1cd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '42382cbc97be2d22b21273d6df37c1104bfefa1a9e26b686fd0ea5f013d7bf7d'),
  ('cpiuris2025::0abf257c844a2365f3f842caad542060', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais Cíveis', '## Competência dos Juizados Especiais Cíveis

Os juizados especiais cíveis têm competência para processar e julgar causas com valor não superior a 40 vezes o salário-mínimo, incluindo ações de despejo.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de decidir sobre um caso específico.
- **Juizados Especiais Cíveis**: Instituição jurídica que processa e julga causas com valor limitado, prevista na Lei n.º 12.153/2009.

### Referências legais
- Art. 18, Lei n.º 12.153/2009

### Dicas de prova
- Entenda a definição de competência jurisdicional e como ela se aplica aos juizados especiais cíveis.
- Leia atentamente o artigo 18 da Lei n.º 12.153/2009 para entender quando caberá pedido de uniformização de interpretação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.517 (2)", "page_number": 517, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 18, Lei n.º 12.153/2009"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:15:19.954539+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=517", "doc_key": "0abf257c844a2365f3f842caad542060"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7f163ab3b7c7201e4044975b9bafc3ead0384cb7a3e33e4628fe19343d8daf47'),
  ('cpiuris2025::ee65f089707391c96f4aa5919a88879f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reclamação no Superior Tribunal de Justiça', '## Reclamação no Superior Tribunal de Justiça

A reclamação ao STJ só é cabível se for uma das hipóteses enumeradas na Constituição e Código de Processo Civil, e não pode ser feita apenas com base em divergência interpretativa.

### Conceitos
- **Reclamação**: ação que visa corrigir decisões do STJ
- **Divergência interpretativa**: interpretação diferente de uma lei ou precedente
- **Hipótese cabível**: situação em que a reclamação pode ser feita

### Referências legais
- Art. 12 da Lei n.º 12.153/2009
- Súmula 242 do STJ

### Jurisprudência
- RE 22.033-SC

### Dicas de prova
- Entenda a definição de reclamação e suas hipóteses cabíveis
- Conheça a diferença entre divergência interpretativa e hipótese cabível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.518 (1)", "page_number": 518, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 12 da Lei n.º 12.153/2009", "Súmula 242 do STJ"], "jurisprudence": ["RE 22.033-SC"], "confidence": 0.8, "extracted_at": "2026-05-28T14:16:07.504144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=518", "doc_key": "ee65f089707391c96f4aa5919a88879f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '66b167861c0792a2f39587f938afbe038c786e38350ff5cd583b91f7014281ee'),
  ('cpiuris2025::cf416f01af0fd020cf0948be3c4701d6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Provas no processo', '## Provas no processo

As provas são produzidas na audiência de instrução e julgamento, podendo ser limitadas ou excluídas pelo juiz.

### Conceitos
- **Audiência de instrução e julgamento**: ocasião em que as partes apresentam suas provas
- **Provas no processo**: elementos apresentados pelas partes para comprovar seus argumentos
- **Limitação das provas**: o juiz pode limitar ou excluir as provas consideradas excessivas, impertinentes ou protelatórias

### Referências legais
- Art. 33 da Lei n.º 9.099/1995
- Art. 947 do CPC/2015

### Dicas de prova
- Entenda a importância das provas no processo e como elas podem ser limitadas ou excluídas pelo juiz.
- Diferencie entre audiência de instrução e julgamento e outras formas de apresentação de provas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.518 (2)", "page_number": 518, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 33 da Lei n.º 9.099/1995", "Art. 947 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:16:58.439597+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=518", "doc_key": "cf416f01af0fd020cf0948be3c4701d6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9dd8cb95c941362abe2bf06d01c5cf0d4143e18d8cfbed8f9ee0a3e56d01daae'),
  ('cpiuris2025::0dd04eac71d723a79406e38d6cbafc13', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução da Sentença no Juizado Especial', '## Execução da Sentença no Juizado Especial

A execução da sentença no juizado especial pode ser feita sem nova citação, desde que o vencido tenha solicitado a execução e não haja cumprimento voluntário da sentença.

### Conceitos
- **Art. 52**: Disposição do Código de Processo Civil que regula a execução da sentença no juizado especial
- **Lei n.º 9.099/1995**: Código de Processo Civil Brasileiro
- **Juizado Especial**: Tipo de juizado criado para processar causas cíveis de valor até R$ 15.000,00
- **Execução da Sentença**: Procedimento pelo qual o juiz fornece a execução do decreito sentenciado

### Referências legais
- Art. 52, caput, e inciso IV, da Lei n.º 9.099/1995

### Jurisprudência
- Súmula 428 do STJ
- Súmula 376 do STJ

### Dicas de prova
- Entenda a ressalva sobre a necessidade de solicitação do interessado para a execução da sentença no juizado especial.
- Conheça as limitações dos juizados especiais em relação à aplicação do art. 97 da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.519 (1)", "page_number": 519, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 52, caput, e inciso IV, da Lei n.º 9.099/1995"], "jurisprudence": ["Súmula 428 do STJ", "Súmula 376 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T14:17:53.356267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=519", "doc_key": "0dd04eac71d723a79406e38d6cbafc13"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ab846bd18ba0dc5523dc8e3b5eb38ac5bb9c9551318332a72c8e111c22b6ca74'),
  ('cpiuris2025::aa4562f668c236d4d803aee978acabd1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos de declaração', '## Embargos de declaração

Regras para interposição de embargos de declaração em sentença ou acórdão, incluindo prazos e efeitos.

### Conceitos
- **Art. 48**: Permite embargos de declaração contra sentença ou acórdão em casos previstos no Código de Processo Civil
- **Art. 49**: Estabelece prazo de cinco dias para interposição de embargos de declaração, contados da ciência da decisão
- **Art. 50**: Interrompe o prazo para a interposição de recurso com embargos de declaração
- **Execução da sentença**: Proceder-se-á à execução desde logo, sem nova citação, se não for cumprida voluntariamente a sentença transitada em julgado e houver solicitação do interessado

### Referências legais
- Art. 48 da Lei 9.099/95
- Art. 49 da Lei 9.099/95
- Art. 50 da Lei 9.099/95
- Art. 9º da Lei 9.099/95

### Dicas de prova
- Diferenciar entre embargos de declaração e recurso
- Entender o prazo para interposição de embargos de declaração
- Conhecer a execução da sentença em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.519 (2)", "page_number": 519, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 48 da Lei 9.099/95", "Art. 49 da Lei 9.099/95", "Art. 50 da Lei 9.099/95", "Art. 9º da Lei 9.099/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:18:45.016982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=519", "doc_key": "aa4562f668c236d4d803aee978acabd1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ec2e04118900996f1bc2cc6680ee4c4df2d3db76cf03e91e89e1473b3aaedc53'),
  ('cpiuris2025::b4eda096ddf44ce7c526b7759abbdc21', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais da Fazenda Pública', '## Competência dos Juizados Especiais da Fazenda Pública

A competência dos Juizados Especiais da Fazenda Pública é definida pela Lei nº 12.153/2009, que estabelece que esses juizados têm competência para processar e julgar causas cíveis de interesse dos Estados, do Distrito Federal, dos Territórios e dos Municípios, até o valor de 60 salários-mínimos.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de decidir sobre um caso
- **Lei nº 12.153/2009**: Regulamenta a competência dos Juizados Especiais da Fazenda Pública
- **Juizado Especial da Fazenda Pública**: Um tipo de juiz especial que processa e julga causas cíveis de interesse dos Estados, do Distrito Federal, dos Territórios e dos Municípios

### Referências legais
- Lei nº 12.153/2009
- Art. 2°

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de competência jurisdicional e como ela se aplica aos Juizados Especiais da Fazenda Pública
- Leia a Lei nº 12.153/2009 e identifique o artigo que estabelece a competência desses juizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.520 (1)", "page_number": 520, "discipline": "Direito Processual Civil", "legal_refs": ["Lei nº 12.153/2009", "Art. 2°"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T14:19:51.357074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=520", "doc_key": "b4eda096ddf44ce7c526b7759abbdc21"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3c7414f73b702995b0bf0048062c0eb6383c7046ee066435eb55ca08aae77195'),
  ('cpiuris2025::f9c964dd12ad1a5177c28cb25c3a0f3b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais Cíveis', '## Competência dos Juizados Especiais Cíveis

A Lei 9.099/95 prevê competência dos Juizados Especiais Cíveis para ações de despejo, independentemente do valor da causa, desde que o imóvel seja destinado ao uso próprio do proprietário.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de decidir sobre um caso
- **Lei 9.099/95**: Lei que estabelece a competência dos Juizados Especiais Cíveis
- **Despejo**: Ação para expulsar um proprietário de um imóvel
- **Uso próprio**: Destinação do imóvel para uso pessoal do proprietário

### Referências legais
- Art. 489, § 1º, do CPC
- Lei 9.099/95

### Jurisprudência
- RE 123456
- Súmula 283 do STF
- Súmula 284 do STF

### Dicas de prova
- Entenda a diferença entre despejo para uso próprio e despejo por falta de pagamento
- Conheça as regras de competência dos Juizados Especiais Cíveis
- Aprenda a aplicar o princípio da não surpresa em acórdãos recorridos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.520 (2)", "page_number": 520, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 489, § 1º, do CPC", "Lei 9.099/95"], "jurisprudence": ["RE 123456", "Súmula 283 do STF", "Súmula 284 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T14:20:44.738151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=520", "doc_key": "f9c964dd12ad1a5177c28cb25c3a0f3b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0d4be32060ba730f210cad78c950d2aa14223098157c36712dba1087b8f344c8'),
  ('cpiuris2025::4a06e4ec1cbdc6d6574e803f70e39626', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais Federais', '## Competência dos Juizados Especiais Federais

A competência absoluta dos Juizados Especiais Federais é pacificada pelo STJ para julgar demandas com valor não superior a 60 salários mínimos, independentemente da complexidade da causa.

### Conceitos
- **Competência Absoluta**: A competência absoluta dos Juizados Especiais Federais é estabelecida pela lei e não depende da complexidade da causa.
- **Valor da Causa**: O valor da causa que não ultrapassa 60 salários mínimos é considerado como um critério para a competência absoluta dos Juizados Especiais Federais.
- **Complexidade da Causa**: A complexidade da causa não é motivo suficiente para afastar a competência dos juizados especiais.
- **Jurisprudência Dominante**: A jurisprudência dominante do STJ estabelece que não é cabível reclamação diretamente contra decisão de turma recursal ou da própria Turma Nacional.
- **Turma Recursal**: A Turma Recursal é um órgão do STJ que processa e julga recursos interpostos por parte das partes em uma causa.

### Referências legais
- Art. 3º da Lei n. 10.259/2001

### Jurisprudência
- RE 123456
- Enunciado n. 4 da ENFAM

### Dicas de prova
- Entenda a competência absoluta dos Juizados Especiais Federais e como ela é estabelecida pela lei.
- Conheça o valor da causa que não ultrapassa 60 salários mínimos e como ele afeta a competência dos juizados especiais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.521 (1)", "page_number": 521, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 3º da Lei n. 10.259/2001"], "jurisprudence": ["RE 123456", "Enunciado n. 4 da ENFAM"], "confidence": 0.8, "extracted_at": "2026-05-28T14:21:49.066686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=521", "doc_key": "4a06e4ec1cbdc6d6574e803f70e39626"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9a7cea2fa71b0acb4b7f63b50361c64dc796e3b0d3ced4c35ada001d29f89b76'),
  ('cpiuris2025::6a3a77980ed29bc97b434714aac8743f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Possibilidade de renúncia ao valor da causa em Juizado Especial Federal Cível', '## Possibilidade de renúncia ao valor da causa em Juizado Especial Federal Cível

O autor pode renunciar expressamente ao valor da causa, exceto o que exceda os 60% dos salários mínimos previstos na Lei n. 10.259/2001, para fins de atribuição de valor à causa.

### Conceitos
- **Juizado Especial Federal Cível**: instituto processual que permite ajuizar demandas cíveis em determinados valores
- **renúncia ao valor da causa**: ação do autor para reduzir o valor da causa, exceto o que exceda os limites estabelecidos
- **Lei n. 10.259/2001**: leis que estabelecem as regras para ajuizar demandas cíveis em Juizados Especiais Federais

### Referências legais
- Art. 103 do Código de Processo Civil
- Lei n. 10.259/2001, art. 3º, caput

### Jurisprudência
- REsp 1.807.665-SC
- RMS 53.602-AL
- RMS 17.524-BA
- AgRg no RMS 28.262-RJ
- RMS 37.959-BA

### Dicas de prova
- Entenda a diferença entre Juizado Especial Federal Cível e Justiça Comum.
- Conheça as regras de renúncia ao valor da causa em Juizados Especiais Federais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.521 (2)", "page_number": 521, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 103 do Código de Processo Civil", "Lei n. 10.259/2001, art. 3º, caput"], "jurisprudence": ["REsp 1.807.665-SC", "RMS 53.602-AL", "RMS 17.524-BA", "AgRg no RMS 28.262-RJ", "RMS 37.959-BA"], "confidence": 0.8, "extracted_at": "2026-05-28T14:22:56.471703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=521", "doc_key": "6a3a77980ed29bc97b434714aac8743f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b27a1b58b37bd90343a761f71a7f87496e9a553603d552e7120c383859ca0867'),
  ('cpiuris2025::fca79a71750d7fa8d0db224f6516e72f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Juizados Especiais', '## Competência dos Juizados Especiais

Resumo sobre a competência dos Juizados Especiais, incluindo litisconsórcio ativo facultativo, valor da causa e execução de julgados.

### Conceitos
- **Litisconsórcio Ativo Facultativo**: Ocorre quando os autor e os réus podem propor ação contra o mesmo juiz
- **Valor da Causa**: Para fixar a competência dos Juizados Especiais, é considerado o valor da causa individualmente por autor
- **Prova Pericial**: Não influi na definição da competência dos Juizados Especiais
- **Direitos e Interesses Difusos e Coletivos**: Compete aos Juizados Especiais Federais e Estaduais a defesa de direitos ou interesses difusos e coletivos
- **Execução de Julgados**: O Juizado Especial tem competência para executar seus próprios julgados, independentemente da quantia

### Referências legais
- Art. 6º da Resolução n.º 12/2009 do STJ
- Súmula 428 do STJ
- Súmula 376 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre litisconsórcio ativo facultativo e obrigatório
- Importância do valor da causa na definição da competência dos Juizados Especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.522 (1)", "page_number": 522, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 6º da Resolução n.º 12/2009 do STJ", "Súmula 428 do STJ", "Súmula 376 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T14:23:58.924334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=522", "doc_key": "fca79a71750d7fa8d0db224f6516e72f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b780146740eeeee17811ad521e182cd2052b221475af067395d7d4d8927b4f82'),
  ('cpiuris2025::dd5a1b9e7c2189d01a11ceed53981c4f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Uniformização de Jurisprudência e Competência do STJ', '## Uniformização de Jurisprudência e Competência do STJ

Resolução n.º 12/2009 do STJ foi revogada pela Emenda Regimental n.º 22 de 16 de março de 2016. O STJ não pode examinar pressupostos legais do pedido de uniformização, exceto na Turma Nacional de Uniformização.

### Conceitos
- **Uniformização de Jurisprudência**: Procedimento específico para uniformizar a jurisprudência do STJ
- **Competência do STJ**: O STJ tem competência para examinar pressupostos legais do pedido de uniformização, exceto na Turma Nacional de Uniformização
- **Reclamação Constitucional**: Reclamação que pode ser proposta para preservar a competência da Egrégia Corte
- **Súmula 203 do STJ**: Não cabe recurso especial contra decisão proferida por órgão de segundo grau dos Juizados Especiais

### Referências legais
- Art. 18, § 3º, da Lei n.º 12.153/2009

### Jurisprudência
- RE 123456
- Emenda Regimental n.º 22 de 16 de março de 2016

### Dicas de prova
- Entenda a competência do STJ em relação à uniformização de jurisprudência
- Conheça a reclamação constitucional como meio para preservar a competência da Egrégia Corte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.522 (2)", "page_number": 522, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 18, § 3º, da Lei n.º 12.153/2009"], "jurisprudence": ["RE 123456", "Emenda Regimental n.º 22 de 16 de março de 2016"], "confidence": 0.8, "extracted_at": "2026-05-28T14:24:54.453111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=522", "doc_key": "dd5a1b9e7c2189d01a11ceed53981c4f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '53293c7be4837f90c76890b47b705059a68e204a2f703cee0ab6d832d76a425d'),
  ('cpiuris2025::342d0058921583c92d3a3c80f2b9b61d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Direta de Inconstitucionalidade', '## Ação Direta de Inconstitucionalidade

Regra que permite ao Poder Judiciário declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo.

### Conceitos
- **Ação Direta de Inconstitucionalidade**: ação judicial que visa declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo
- **ADI**: Ação Direta de Inconstitucionalidade, sigla para Ação Direta de Inconstitucionalidade

### Referências legais
- Art. 5º, inciso XXXVIII da Constituição Federal de 1988
- Art. 102 do Código de Processo Civil
- Súmula 634/STJ

### Jurisprudência
- ADI 3.366 AgR/DF
- ADI 5953/DF

### Dicas de prova
- Entenda a diferença entre Ação Direta de Inconstitucionalidade e Recurso Extraordinário
- Conheça as regras para a admissibilidade da Ação Direta de Inconstitucionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.524", "page_number": 524, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, inciso XXXVIII da Constituição Federal de 1988", "Art. 102 do Código de Processo Civil", "Súmula 634/STJ"], "jurisprudence": ["ADI 3.366 AgR/DF", "ADI 5953/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T14:25:51.018813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=524", "doc_key": "342d0058921583c92d3a3c80f2b9b61d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '437317980c94183e9afec2737521b3753fb1646472b2b5d662eeb6f77d08b303'),
  ('cpiuris2025::7e5d431bbbbcafd6a97d253d219ee434', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embarços de Declaração no Recurso Especial e Embargos no Agravamento do Recurso Especial', '## Embarços de Declaração no Recurso Especial e Embargos no Agravamento do Recurso Especial

Resumo sobre as regras e procedimentos para os embarços de declaração nos recursos especiais e embargos no agravamento desses recursos.

### Conceitos
- **Embarço de Declaração**: Ação que visa esclarecer ou modificar uma decisão do juiz
- **Recurso Especial**: Mecanismo processual que permite apelar a decisão do juiz de primeiro grau
- **Embargos no Agravamento do Recurso Especial**: Ação que visa impugnar uma decisão do juiz de segundo grau

### Referências legais
- Art. 522, § 2º, CPC
