  ('cpiuris2025::d7dcb2c3ce3eb116278ea67d9ddc64df', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Resoluções e Súmulas do STJ', '## Resoluções e Súmulas do STJ

Resumo de resoluções e súmulas emitidas pelo Superior Tribunal de Justiça (STJ) relacionadas a processos civis.

### Conceitos
- **Resolução**: Decisão do STJ que não é final ou executiva, mas sim uma orientação para os tribunais inferiores.
- **Súmula**: Princípio jurídico geral estabelecido pelo STJ que tem natureza de lei e é aplicada por todos os tribunais do país.

### Referências legais
- Art. 102 da Constituição Federal

### Jurisprudência
