  ('cpiuris2025::1c3fd18d8701421e9e73cdf754f27d8d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo em Recurso Especial e Ações Rescisórias', '## Agravo em Recurso Especial e Ações Rescisórias

