  ('cpiuris2025::c073c18ff0c2296edb7ae1edc43476ed', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Introdução ao Direito Processual Penal', '## Introdução ao Direito Processual Penal

Resumo objetivo: Introdução à disciplina, organização e abordagem do Direito Processual Penal.

### Conceitos
- **Processo penal**: Ações judiciais que envolvem crimes e seus procedimentos.
- **Direito processual penal**: Substantiva as regras e normas que regem o processo penal.
- **Organização do sistema processual penal**: A estrutura e a disposição das leis e regulamentos que compõem o Direito Processual Penal.
- **Abordagem do Direito Processual Penal**: O enfoque e abordagem da disciplina em relação ao processo penal.
- **Importância do Direito Processual Penal**: A importância da disciplina no contexto do sistema jurídico brasileiro.
- **Objetivos do Direito Processual Penal**: Os objetivos e finalidades da disciplina em questão.
- **Regras e normas processuais**: As regras e normas que regem o processo penal, como a competência, a ação, a defesa, etc.
- **Procedimentos penais**: Os procedimentos e etapas do processo penal.

### Referências legais
- Art. 1 da Lei nº 7.210/1984
- Súmula 242 STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Processual Penal

### Dicas de prova
- Entenda a definição de processo penal e seu relacionamento com o Direito Processual Penal.
- Conheça as regras básicas do sistema processual penal, como competência e ação.
- Identifique os procedimentos penais e suas etapas no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1 da Lei nº 7.210/1984", "Súmula 242 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Processual Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T14:31:56.900583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=2", "doc_key": "c073c18ff0c2296edb7ae1edc43476ed"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '87fed518e3bfa5c92e47aaa4dbc8c1ff17657ecf40b1ce3cbf2bf63ebc9e3157'),
  ('cpiuris2025::9605b39f234f39f83bd23fbdaeff9a06', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistemas processuais penais', '## Sistemas processuais penais

Descreve as diferentes formas de sistemas processuais penais, incluindo inquisitorial, acusatório e misto.

### Conceitos
- **Sistema Inquisitorial**: Caracteriza-se pela iniciativa do Estado em investigar e provar a infração
- **Sistema Acusatório**: Caracteriza-se pela iniciativa da vítima ou de terceiro não partidarizado em investigar e provar a infração
- **Sistema Misto**: Combina elementos do sistema inquisitorial e acusatório

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Entenda a diferença entre os sistemas processuais penais e como eles afetam o direito do acusado
- Conheça as características de cada sistema e como eles são aplicados na prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.3 (1)", "page_number": 3, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:32:36.258561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=3", "doc_key": "9605b39f234f39f83bd23fbdaeff9a06"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aec6d70740fd44e076a8e05516abe3cb9153d231119e889fac84bf6809f965ee'),
  ('cpiuris2025::5f5a75220f9528c4474e68c4725e6cb6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios Fundamentais do Direito Processual Penal', '## Princípios Fundamentais do Direito Processual Penal

Resumo de principais princípios fundamentais do direito processual penal, incluindo a oralidade, o livre convencimento motivado e a liberdade probatória.

### Conceitos
- **Oralidade**: Princípio que exige a manifestação oral das partes no processo
- **Livre Convencimento Motivado**: Princípio que exige que o juiz tome uma decisão fundamentada e motivada
- **Liberdade Probatória**: Princípio que permite ao juiz escolher os meios de prova a serem utilizados
- **Princípio do Favor Rei**: Princípio que proíbe o favor pessoal do juiz e exige imparcialidade
- **Fonte Material**: Fonte da lei processual penal, como a Constituição e as leis específicas
- **Fonte Formal**: Fonte do processo, como o regimento interno do juízo

### Referências legais
- Art. 5º, LIV, da CF/88; Art. 129, § 2º, do CPP/2015

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Entenda a importância dos princípios fundamentais do direito processual penal
- Conheça as diferentes fontes do direito processual penal e sua relevância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.3 (2)", "page_number": 3, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF/88; Art. 129, § 2º, do CPP/2015"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T14:33:39.318300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=3", "doc_key": "5f5a75220f9528c4474e68c4725e6cb6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7ce8a3204000d91db894ee933a9cbeffcd37bc1f2f9be2dd5babae703cfcb1d6'),
  ('cpiuris2025::f7aaa51664fcf163aea02fe7a850693b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Juíz das Garantias e Investigação Criminal', '## Juíz das Garantias e Investigação Criminal

Trecho aborda conceitos gerais, conceito específico de juíz das garantias e competência para julgá-los, além de natureza jurídica do inquérito policial, sua finalidade e valor probatório.

### Conceitos
- **Juíz das Garantias**: Ente judiciale responsável por processar e julgar as garantias da vítima em casos criminais
- **Inquérito Policial**: Investigação criminal realizada pelo polícia civil ou militar, com o objetivo de apurar fatos criminais
- **Competência**: Hábito jurídico que determina a competência para processar e julgar um caso

### Referências legais
- Art. 5º da Constituição Federal
- Código de Processo Penal

### Jurisprudência
- Súmula 282 do STF
- Tema repetitivo: Competência em casos criminais

### Dicas de prova
- Entenda a competência para julgá-los
- Conheça o conceito de inquérito policial e sua finalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.3 (3)", "page_number": 3, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º da Constituição Federal", "Código de Processo Penal"], "jurisprudence": ["Súmula 282 do STF", "Tema repetitivo: Competência em casos criminais"], "confidence": 0.8, "extracted_at": "2026-05-28T14:34:21.600586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=3", "doc_key": "f7aaa51664fcf163aea02fe7a850693b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '32fca301f4b423ba209d51a8e494cda40aaa6cde972b021d8dd835a634d25d48'),
  ('cpiuris2025::980a508673641279f0d3e63ba6fdc3a5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Características do Inquérito Policial', '## Características do Inquérito Policial

Descreve as diferentes formas de procedimento do inquérito policial, incluindo oficioso, discricionário, escrito e temporário.

### Conceitos
- **Procedimento Oficioso**: Realizado sem a necessidade de autorização ou intimação de qualquer das partes.
- **Procedimento Discricionário**: O juiz tem amplo poder discricionário para determinar o procedimento do inquérito policial.
- **Procedimento Escrito**: O inquérito policial é realizado por meio de documentos escritos, como denúncias e laudos.
- **Procedimento Temporário**: O inquérito policial é realizado em um período temporário, geralmente até que a infração seja comprovada ou não.
- **Procedimento Dispensável**: O inquérito policial pode ser dispensado se a infração for de baixo valor ou se houver outros meios de prova suficientes.
- **Procedimento Indisponível**: O inquérito policial não pode ser realizado em determinadas situações, como em caso de morte ou lesão grave.
- **Procedimento Sigiloso**: O inquérito policial é realizado com sigilo, geralmente para proteger a vítima ou o acusado.
- **Procedimento Oficial**: O inquérito policial é realizado de acordo com as regras e procedimentos estabelecidos pela lei.

### Referências legais
- Art. 5º da Lei nº 7.210/82

### Dicas de prova
- Entenda a diferença entre procedimento oficioso e discricionário.
- Conheça as formas de procedimento do inquérito policial e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:35:30.706878+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=4", "doc_key": "980a508673641279f0d3e63ba6fdc3a5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ba81a0841f37028ce06bfc8f823357c2467069fb558059e768f70f280c0bd86'),
  ('cpiuris2025::04a71dec824d14e441e6ef2c1fe1b646', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Diligenças investigatórias e procedimentos subsequentes ao inquérito policial', '## Diligenças investigatórias e procedimentos subsequentes ao inquérito policial

Discute-se as diligenças investigatórias, identificação criminal, indiciação, desindiciamento, arquivamento do inquérito policial e seus procedimentos.

### Conceitos
- **Diligença investigatória**: Ação processual que visa apurar a verdade dos fatos
- **Indiciação**: O ato de indicar um crime ao juiz competente
- **Desindiciamento**: O ato pelo qual o juiz decide não proceder com a indicação do crime
- **Arquivamento do inquérito policial**: O ato pelo qual o juiz decide encerrar o inquérito policial sem procedimento

### Referências legais
- Art. 5º, inciso IV da CF/88
- Súmula 282 do STF

### Jurisprudência
- RE 123456/RS
- Tema repetitivo: Diligença investigatória e procedimentos subsequentes ao inquérito policial

### Dicas de prova
- Entenda a diferença entre diligença investigatória e procedimento de arquivamento do inquérito policial
- Conheça as espécies de indiciação e desindiciamento
- Aprenda a importância da atribuição do sujeito passivo no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso IV da CF/88", "Súmula 282 do STF"], "jurisprudence": ["RE 123456/RS", "Tema repetitivo: Diligença investigatória e procedimentos subsequentes ao inquérito policial"], "confidence": 0.8, "extracted_at": "2026-05-28T14:36:28.360117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=4", "doc_key": "04a71dec824d14e441e6ef2c1fe1b646"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cc764b052e3820f3c2251ef6b8c6ed6196def04fd433a7661f352e3cc8ddcc12'),
  ('cpiuris2025::223e458f282a753b2c538c69e89a0ad2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Investigação Criminal e Outros Instrumentos Investigatórios', '## Investigação Criminal e Outros Instrumentos Investigatórios

Trecho aborda diferentes instrumentos investigatórios, como inquéritos parlamentares, civil, termo circunstanciado de ocorrência, entre outros, destacando suas características e procedimentos.

### Conceitos
- **Arquivamento**: Decisão do juiz que encerra o processo sem julgamento de mérito.
- **Desarquivamento**: Ato pelo qual o juiz revoga a decisão de arquivamento.
- **Inquérito civil**: Investigação realizada por um juiz ou magistrado para esclarecer fatos de um processo.
- **Termo circunstanciado de ocorrência**: Ata que contém a descrição dos fatos ocorridos durante a investigação do inquérito policial.
- **Investigação criminal pelo Ministério Público**: Ação realizada pelo MP para investigar e processar um crime.
- **Investigação criminal defensiva**: Atividade realizada pela defesa para esclarecer fatos do caso.
- **Acordo de não persecução penal**: Concordância entre as partes para não prosseguir com a ação penal.
- **Trancamento ou encerramento anômalo do inquérito policial**: Situação em que o inquérito policial é trancado ou encerrado de forma irregular.

### Referências legais
- Art. 14, § 3º, CP
- Súmula 437/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Investigação Criminal

### Dicas de prova
- Entenda a diferença entre arquivamento e desarquivamento.
- Conheça as características de um inquérito civil e como ele é diferente do inquérito policial.
- Identifique o termo circunstanciado de ocorrência e sua importância na investigação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, § 3º, CP", "Súmula 437/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Investigação Criminal"], "confidence": 0.8, "extracted_at": "2026-05-28T14:37:31.933226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=4", "doc_key": "223e458f282a753b2c538c69e89a0ad2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1a0f99a7f7a86626ff69796772c12d11516e7719a5e6c4951c0e47caea8467d2'),
  ('cpiuris2025::960020b080066032f22efa5e3beb94a6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Controle Externo da Atividade Policial', '## Controle Externo da Atividade Policial

Discute o controle externo da atividade policial, destacando a importância de sua regulamentação.

### Conceitos
- **Atividade Policial**: Ações e atividades realizadas por agentes policiais
- **Controle Externo**: Ome mecanismos que visam fiscalizar e regular a atividade policial

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Dicas de prova
- Entenda o conceito de controle externo e sua importância na regulamentação da atividade policial.
- Destaque a relevância das leis e normas que regem a atividade policial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.4 (4)", "page_number": 4, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:37:58.002692+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=4", "doc_key": "960020b080066032f22efa5e3beb94a6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ffee9fa6affd04838292f5322d1d35d7909531984aba071dd5fd95b9d558a552'),
  ('cpiuris2025::b1d2f4534827f74d80e7f4039a172f53', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições da ação penal', '## Condições da ação penal

Descreve as condições necessárias para a ação penal ser processada, incluindo condições genéricas e específicas.

### Conceitos
- **Ação penal**: Processo em que o Estado é o autor e o réu é o acusado
- **Condições da ação penal**: Requisitos necessários para a ação penal ser processada
- **Ne procedat iudex ex officio**: Princípio que determina que o juiz não deve agir como autor do processo
- **Ne bis in idem**: Princípio que proíbe a repetição de processos por mesmas infrações
- **Intranscendência**: Princípio que determina que as penalidades devem ser proporcionais às infrações
- **Oficialidade**: Princípio que determina a necessidade de um ato processual ser feito por meio de um documento oficial
- **Oficiosidade**: Princípio que determina que o juiz pode agir como autor do processo sem necessidade de uma ordem judicial

### Referências legais
- Art. 5º, inciso XXXIX da CF/88

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda as condições genéricas e específicas da ação penal
- Conheça os princípios que regem a ação penal
- Identifique o princípio de oficialidade em relação ao ato processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso XXXIX da CF/88"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T14:39:05.221206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=5", "doc_key": "b1d2f4534827f74d80e7f4039a172f53"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '172a8ae2a855446a941c08101d7b71a5b22e20da4a4db6c29b19e2897651059a'),
  ('cpiuris2025::cb09886435384e5e2fd94a673c695c43', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios da ação penal pública e privada', '## Princípios da ação penal pública e privada

Resumo dos principios da ação penal pública e privada, incluindo obrigatoriedade, indisponibilidade, divisibilidade, oportunidade, disponibilidade, indivisibilidade, representação, requisição do Ministro da Justiça e iniciativa privada.

### Conceitos
- **Obrigatoriedade**: Princípio que estabelece a obrigatoriedade da ação penal pública
- **Indisponibilidade**: Princípio que determina a indisponibilidade do direito de ação penal privada
- **Divisibilidade**: Princípio que permite a divisão da ação penal em partes menores
- **Oportunidade**: Princípio que estabelece a oportunidade para a ação penal privada
- **Disponibilidade**: Princípio que determina a disponibilidade do direito de ação penal privada
- **Indivisibilidade**: Princípio que impede a divisão da ação penal em partes menores
- **Representação**: Requisição necessária para a ação penal pública condicionada
- **Requisição do Ministro da Justiça**: Requisição necessária para a ação penal pública condicionada

### Referências legais
- Art. 5º, inciso III, da CF
- Súmula 293/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Ação Penal Pública e Privada

### Dicas de prova
- Entenda a diferença entre ação penal pública e privada
- Conheça os principais princípios da ação penal pública e privada
- Identifique as requisícios necessários para a ação penal pública condicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso III, da CF", "Súmula 293/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação Penal Pública e Privada"], "confidence": 0.8, "extracted_at": "2026-05-28T14:40:09.364269+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=5", "doc_key": "cb09886435384e5e2fd94a673c695c43"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '412e84aa0c0e47a426fa3e6d444b32176c403acaf11be81b12517e880809ba13'),
  ('cpiuris2025::f2713bb1a3fe737da451ccfa7a5a39e2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ações Penais Privadas Subsidiárias da Pública e Hipóteses de Extinção de Punibilidade', '## Ações Penais Privadas Subsidiárias da Pública e Hipóteses de Extinção de Punibilidade

Descreve as ações penais privadas subsidiárias da pública, suas hipóteses de extinção de punibilidade e outras ações penais.

### Conceitos
- **Ação Penal Privada Subsidiária da Pública**: ação penal que pode ser iniciada pelo autor contra o autor do delito
- **Decadência**: fim do prazo para a ação penal ser iniciada
- **Renúncia**: abandono da ação penal por um dos litigantes
- **Perdão**: concessão do perdão pelo autor ou pelo Estado
- **Perempção**: fim do prazo para a ação penal ser iniciada devido à inércia do autor
- **Ação Penal Popular**: ação penal que pode ser iniciada pelo Estado sem a necessidade de um denunciante
- **Ação Penal Adesiva**: ação penal que se adere à ação penal do outro
- **Ação de Prevenção Penal**: ação penal que visa prevenir o crime antes que ele seja cometido

### Referências legais
- Art. 14, § 1º, CP
- Súmula 342 STF

### Dicas de prova
- Entenda a diferença entre ação penal subsidiária e ação penal popular.
- Conheça as hipóteses de extinção de punibilidade e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, § 1º, CP", "Súmula 342 STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:41:17.376687+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=5", "doc_key": "f2713bb1a3fe737da451ccfa7a5a39e2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ccb759328d4186d7240f5a00b630d52a3002fb3e809c19536fb6aecf8ea2517b'),
  ('cpiuris2025::2c17f06316822f81d827af78bfc729bc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cumulação de imputação e outras questões relacionadas', '## Cumulação de imputação e outras questões relacionadas

Discute as regras para a cumulação de imputações, imputação alternativa, aditamento da denúncia e dispositivos legais relacionados ao capítulo.

### Conceitos
- **Cumulação de imputações**: Princípio que permite a combinação de várias imputações em um único processo.
- **Imputação alternativa**: Alegação de que o acusado é autor de outro crime, com o objetivo de reduzir a pena ou evitar a condenação por outro crime.
- **Aditamento da denúncia**: Mudança feita na denúncia apresentada pelo Ministério Público durante o processo.
- **Denúncia**: Ação processual que visa condenar o acusado por um crime.
- **Processo penal**: Procedimento jurídico que visa punir ou não punir o acusado por um crime.
- **Ministério Público**: Autoridade pública responsável pela procura e punição de crimes.
- **Pena**: Sancionamento aplicado ao acusado por um crime.
- **Condenação**: Decisão do juiz que convida o acusado a ser considerado culpado e punido por um crime.

### Referências legais
- Art. 14, § 3º, inciso IV do Código de Processo Penal
- Súmula 284 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456/SP
- ...

### Dicas de prova
- Entenda a diferença entre cumulação e imputação alternativa.
- Conheça as regras para o aditamento da denúncia.
- Aprenda a importância do Ministério Público no processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, § 3º, inciso IV do Código de Processo Penal", "Súmula 284 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T14:42:26.374405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=5", "doc_key": "2c17f06316822f81d827af78bfc729bc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5eacc964e627bce1766cc988b03b3dda8336145abff914334d2a4c32e849c556'),
  ('cpiuris2025::bb5e16e8d9c35313cb9abc35b76fa2c1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ação Civil Ex Delicto e Jurisdição', '## Ação Civil Ex Delicto e Jurisdição

Descreve as noções gerais da ação civil ex delicto, sistemas de relação entre ação penal e ação civil ex delicto, jurisdição e competência.

### Conceitos
- **Ação Civil Ex Delicto**: ação processual que busca indenizar o dano causado por um delito
- **Sistema da Confusão**: sistema de relação entre ação penal e ação civil ex delicto em que as duas ações são confundidas
- **Sistema da Solidariedade**: sistema de relação entre ação penal e ação civil ex delicto em que as duas ações são solidárias
- **Sistema da Livre Escolha**: sistema de relação entre ação penal e ação civil ex delicto em que o autor escolhe a ação mais adequada
- **Sistema da Independência**: sistema de relação entre ação penal e ação civil ex delicto em que as duas ações são independentes

### Referências legais
- Art. 69 a 91, CPP

### Dicas de prova
- Entenda os sistemas de relação entre ação penal e ação civil ex delicto
- Conheça as características da jurisdição e princípios gerais da jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 69 a 91, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:43:16.836388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=6", "doc_key": "bb5e16e8d9c35313cb9abc35b76fa2c1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '310e803fdc589db083938d5ea1743404efcb537d60c4310c6f81ba0fbf5df5b4'),
  ('cpiuris2025::351f83ad95751c0ba1c0c2a3ed0753af', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência de justiça', '## Competência de justiça

Descreve as espécies de competência e suas classificações.

### Conceitos
- **Competência de justiça**: Conhecimento da jurisdição sobre a qual incide o processo
- **Competência originária**: Competência que se deriva diretamente do texto da legislação
- **Justiça Militar**: Jurisdição militar que processa crimes cometidos por militares
- **Justiça Eleitoral**: Jurisdição responsável pela eleição de autoridades
- **Justiça do Trabalho**: Jurisdição responsável por processos trabalhistas
- **Justiça Federal**: Jurisdição federal que processa crimes federais

### Referências legais
- Art. 109 da Constituição
- Art. 93 do Código de Processo Penal

### Dicas de prova
- Entenda a distinção entre competência originária e competência de justiça.
- Conheça as diferentes espécies de competência e suas classificações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da Constituição", "Art. 93 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:43:58.047601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=6", "doc_key": "351f83ad95751c0ba1c0c2a3ed0753af"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '84e44a7fb4e21ebe5bbadb2426a8b83f27c9ab05eda92e4da912845734c06d7d'),
  ('cpiuris2025::e878c3c2c172a7c1d8d0a38ebe93c05f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Questões Incidentais no CPP', '## Questões Incidentais no CPP

Trecho sobre questões incidentais no contexto do Código de Processo Penal, abordando procedimentos e requisitos para diferentes tipos de incidentes.

### Conceitos
- **Incidente de Falsidade Documental**: Requerimento feito para verificar a autenticidade de documentos apresentados como prova
- **Insanidade Mental**: Requerimento feito para avaliar a capacidade mental do réu ou de uma das partes
- **Legitimados para o Requerimento**: Partes, advogados ou representantes legais que podem solicitar a instauração do incidente
- **Suspensão do Curso do Processo**: Mecanismo pelo qual o processo é temporariamente suspenso para permitir a realização de procedimentos especiais

### Referências legais
- Art. 145 do CPP
- Art. 148 do CPP
- Art. 149 do CPP
- Art. 154 do CPP

### Dicas de prova
- Entenda a distinção entre incidente de falsidade documental e insanidade mental
- Conheça os requisitos para a suspensão do curso do processo
- Avalie as legítimas para o requerimento de instauração do incidente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 145 do CPP", "Art. 148 do CPP", "Art. 149 do CPP", "Art. 154 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:44:57.673127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=6", "doc_key": "e878c3c2c172a7c1d8d0a38ebe93c05f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '56ca21e05892de5d46c66c510052a3761908f3e6432e749604084bc670fcbc08'),
  ('cpiuris2025::29c7787083e09511ca9efc488f3ebe4f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Informativos de Jurisprudência', '## Informativos de Jurisprudência

Relaciona os informativos de jurisprudência publicados pela Justiça Federal.

### Conceitos
- **Jurisprudência**: decisões e orientações emitidas por tribunais
- **Informativo**: publicação que relata decisões e orientações do tribunal

### Jurisprudência
- Informativos de Jurisprudência

