  ('cpiuris2025::3d2f0463b21ae7f981ff1b4600188953', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções e Conflito de Competência', '## Exceções e Conflito de Competência

Discute as exceções e o conflito de competência no processo penal, incluindo a suspeição e a incompatibilidade do juiz.

### Conceitos
- **Conceito de Exceção**: A exceção é uma medida processual que visa evitar a violação dos direitos do acusado ou da vítima.
- **Classificação das Exceções**: As exceções podem ser classificadas em razão de suas consequências, como a suspeição e a incompatibilidade do juiz.
- **Exceção de Suspeição**: A exceção de suspeição é reconhecida quando há motivo para acreditar que o juiz pode estar influenciado por interesses pessoais ou externos.
- **Reconhecimento da Exceção de Suspeição**: O juiz pode reconhecer a exceção de suspeição de ofício, após análise das provas apresentadas pela parte.
- **Exceção de Incompatibilidade do Juiz**: A exceção de incompatibilidade do juiz é reconhecida quando há motivo para acreditar que o juiz não pode julgar o caso devido à sua relação pessoal com uma das partes.
- **Oposição da Exceção**: A parte pode opor-se à exceção apresentada pela outra parte, argumentando que não há motivo para reconhecer a suspeição ou incompatibilidade do juiz.
- **Conflito de Competência**: O conflito de competência ocorre quando dois ou mais juízes têm competência para julgar o mesmo caso.
- **Reconhecimento do Conflito de Competência**: O juiz pode reconhecer o conflito de competência, após análise das provas apresentadas pela parte.

### Referências legais
- Art. 95 a 117, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o conceito de exceção e sua classificação.
- Análise das provas apresentadas pela parte para reconhecer a suspeição ou incompatibilidade do juiz.
- Conheça as regras para o reconhecimento do conflito de competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 95 a 117, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T14:46:35.267575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=7", "doc_key": "3d2f0463b21ae7f981ff1b4600188953"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e54f171d192b2b0ee068a07cb88cba28167fc9cbf7ee1552e9ed8102d23c7730'),
  ('cpiuris2025::89d5465c7a99945e8f2d452e90b81d9d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Exceções no Processo Penal', '## Exceções no Processo Penal

Trecho aborda as exceções processuais, incluindo ilegitimidade, litispendência e coisa julgada.

### Conceitos
- **Ilegitimidade**: O direito de uma parte ter legitimidade para propor ou defender um processo
- **Litispendência**: A situação em que dois ou mais processos se sobrepõem, com a mesma causa de pedir
- **Coisa julgada**: A decisão final e irrevogável do juiz em um processo

### Referências legais
- Art. 485, § 2º, CF; Art. 324, Código de Processo Penal; Súmula 287/STJ

### Jurisprudência
- RE 123456
- Súmula 287/STJ

### Dicas de prova
- Entenda a diferença entre legitimidade ad causam e ad processum
- Conheça os critérios para determinar a litispendência
- Aprenda sobre as limitações da coisa julgada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 485, § 2º, CF; Art. 324, Código de Processo Penal; Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Súmula 287/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T14:47:24.266541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=7", "doc_key": "89d5465c7a99945e8f2d452e90b81d9d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bbb2f8295922b8c167194c887dec14ae7b24f51c9b0c5188273996dc73c13fa7'),
  ('cpiuris2025::38fcbd8d3920bf4754c138eff089c221', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conflitos de Competência', '## Conflitos de Competência

Discute as regras para a identificação e resolução de conflitos entre os tribunais competentes em um mesmo processo penal.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar uma causa
- **Conflito de Competência**: Situção em que dois ou mais tribunais competem para julgar a mesma causa
- **Jurisdição**: Poder do Estado para tomar decisões sobre questões específicas

### Referências legais
- Art. 109 da Lei nº 9.039/96
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Súmula 287/STJ

### Dicas de prova
- Entenda a distinção entre competência e jurisdição
- Conheça as regras para identificar conflitos de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109 da Lei nº 9.039/96", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Súmula 287/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T14:48:00.991154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=7", "doc_key": "38fcbd8d3920bf4754c138eff089c221"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5633771cfb167984fb6c4c46ab70a7add8380374a130595f2d23d6512f5806a9'),
  ('cpiuris2025::8db24423cf4162f2deb0157de6f90ca9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas Assecuratórias', '## Medidas Assecuratórias

Discute as medidas assecuratórias, incluindo o sequestro, e suas destinações.

### Conceitos
- **Sequestro**: medida assecuratória que visa privar a pessoa de seus bens
- **Destinação dos bens apreendidos**: utilização pelo poder público ou confisco

### Referências legais
- Art. 125 do CPP

### Dicas de prova
- Entenda a diferença entre sequestro e confisco
- Conheça as destinações dos bens apreendidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 125 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:48:28.734994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=8", "doc_key": "8db24423cf4162f2deb0157de6f90ca9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c000fd1b3d94848fe2cf3645512d109403ba9b0302a3182fcf0ef8689d8d857b'),
  ('cpiuris2025::f6e648c8e02bf546a47be390e2c3bd7a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Hipoteca Legal e Arresto', '## Hipoteca Legal e Arresto

Discute-se a hipoteca legal, seus requisitos, legitimados e possibilidade de caução pelo réu, além do arresto prévio, subsidiário e suas disposições comuns.

### Conceitos
- **Hipoteca Legal**: Condição que vincula o bem ao processo penal
- **Arresto Previa**: Medida provisória para garantir a ordem pública e segurança
- **Legitimados em Hipoteca Legal**: Partes envolvidas no processo penal
- **Caução pelo Réu**: Oportunidade de o réu se libertar da hipoteca legal

### Referências legais
- Art. 311 do CP
- Súmula 345/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Hipoteca Legal e Arresto

### Dicas de prova
- Entenda a diferença entre hipoteca legal e arresto prévio
- Conheça os requisitos e legitimados para a hipoteca legal
- Avalie a possibilidade de caução pelo réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do CP", "Súmula 345/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Hipoteca Legal e Arresto"], "confidence": 0.8, "extracted_at": "2026-05-28T14:49:18.695428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=8", "doc_key": "f6e648c8e02bf546a47be390e2c3bd7a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b7697e753dc3edbe99084084e824a4f84bb676e48c7112aaf9b9c415458477f9'),
  ('cpiuris2025::2a01703fe3ebe442410e21c58c36e86f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade do Ministério Público e outras questões', '## Legitimidade do Ministério Público e outras questões

Trecho aborda legitimidade do Ministério Público, remessa de autos ao juízo cível, venda antecipada de bens sequestrados, informativas de jurisprudência e prova em espécie.

### Conceitos
- **Legitimidade do Ministério Público**: O Ministério Público tem legitimidade para processar e punir os crimes.
- **Remessa de autos ao juízo cível**: A remessa de autos ao juízo cível é um procedimento que permite a continuidade do processo em outro tribunal.
- **Venda antecipada de bens sequestrados**: A venda antecipada de bens sequestrados é uma medida que pode ser tomada pelo juiz para garantir a ordem pública e a segurança.
- **Informativas de jurisprudência**: As informativas de jurisprudência são notificações feitas ao Ministério Público sobre decisões do Supremo Tribunal Federal e do Superior Tribunal de Justiça.
- **Prova em espécie**: A prova em espécie é a apresentação de provas específicas para comprovar um fato ou circunstância.
- **Exame de corpo de delito**: O exame de corpo de delito é uma investigação física realizada no local do crime para coletar evidências.
- **Cadeia de custódia**: A cadeia de custódia é a sequência de locais onde o acusado foi detido desde o momento em que foi preso até o momento em que foi libertado ou julgado.
- **Perícias em geral**: As perícias em geral são testemunhos técnicos realizados por especialistas para comprovar um fato ou circunstância.

### Referências legais
- Art. 155 a 157, CPP

### Dicas de prova
- Perguntas sobre legitimidade do Ministério Público e remessa de autos ao juízo cível podem ser respondidas com base nos princípios aplicáveis.
- A venda antecipada de bens sequestrados é uma medida que pode ser tomada pelo juiz para garantir a ordem pública e a segurança.
- As informativas de jurisprudência são importantes para o Ministério Público entender as decisões do Supremo Tribunal Federal e do Superior Tribunal de Justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 155 a 157, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:50:38.095759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=8", "doc_key": "2a01703fe3ebe442410e21c58c36e86f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bf22fd8a20be88670c21de35c018b6eb02b1fdebcb08aa2ffddbf90dc09bc67a'),
  ('cpiuris2025::7340d93d47b03b0d3e0cdd446c2eb661', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Processo penal - Ementa', '## Processo penal - Ementa

Resumo objetivo: A ementa do processo penal apresentada no texto, referente a determinado artigo da Lei de Imprudência, é objeto de análise para compreender as implicações legais e procedimentais que ele traz.

### Conceitos
- **Imprudência**: Falta de cuidado ou atenção no processo
- **Lei de Imprudência**: Lei que disciplina a conduta do juiz e outros agentes processuais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- A análise da ementa é fundamental para entender as implicações legais do artigo
- É importante identificar a conduta do juiz e seus impactos no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.8 (4)", "page_number": 8, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:51:06.033982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=8", "doc_key": "7340d93d47b03b0d3e0cdd446c2eb661"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '19995dba5dc8276c1ba513fb40f968d9b42ebe36d53efdf2c8c8bc595995eafa'),
  ('cpiuris2025::b8cd4b3cc9669ec9faf4bd8cc53228e5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sujeitos processuais', '## Sujeitos processuais

Capítulo que aborda os sujeitos processuais, incluindo o juiz e as partes envolvidas no processo.

### Conceitos
- **Juiz Natural**: Princípio que determina a competência do juiz natural, ou seja, o juiz que tem conhecimento da matéria e da procedência do processo.
- **Sujeito Processual**: Pessoa física ou jurídica que é parte de um processo
- **Parte**: Pessoa física ou jurídica que tem interesse em um processo
- **Juiz**: Pessoa física que exerce a função judiciária e decide os processos

### Referências legais
- Art. 251 do CPP

### Dicas de prova
- Entenda o conceito de juiz natural e sua importância na competência do juiz.
- Identifique as partes envolvidas no processo e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 251 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:51:55.571187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=9", "doc_key": "b8cd4b3cc9669ec9faf4bd8cc53228e5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fe19edc2ebb7cd80b0fea2da17a7a22110c945ee6a58eebb9b5e2872f2ffbb75'),
  ('cpiuris2025::d6746c75cec0a7a146afafc6285f6d38', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prerrogativas e vedações dos magistrados', '## Prerrogativas e vedações dos magistrados

Descreve as prerrogativas e vedações dos magistrados no sistema processual penal, incluindo imparcialidade, impedimento e suspeição.

### Conceitos
- **Imparcialidade**: A obrigação de agir imparcialmente, sem favoritismo ou preconceito
- **Impedimento**: A situação em que um magistrado não pode julgar uma causa devido a uma razão externa
- **Suspeição**: A situação em que um magistrado pode ser influenciado por uma razão externa e, portanto, não pode julgar uma causa
- **Má-fé**: O estado de espírito caracterizado pela intenção de enganar ou prejudicar alguém

### Referências legais
- Art. 252 do CPP
- Art. 253 do CPP
- Art. 254 do CPP
- Art. 255 do CPP
- Art. 256 do CPP

### Dicas de prova
- Entenda a distinção entre impedimento e suspeição
- Conheça as causas de má-fé e incompatibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 252 do CPP", "Art. 253 do CPP", "Art. 254 do CPP", "Art. 255 do CPP", "Art. 256 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:52:42.962069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=9", "doc_key": "d6746c75cec0a7a146afafc6285f6d38"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '80be28961a8caa029efe80eaf8b3772ededfdc6902a912870b75e29844b814ad'),
  ('cpiuris2025::74daeaa7b9b5af9a5d1a9e3c674b0683', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Definição de Acusado e Peca Acusatória Sem Dados Qualificativos', '## Definição de Acusado e Peca Acusatória Sem Dados Qualificativos

Artigo 259 do CPP define o acusado como a pessoa que é processada pela Justiça. A peça acusatória sem dados qualificativos é apresentada pelo Ministério Público.

### Conceitos
- **Acusado**: Pessoa que é processada pela Justiça
- **Peca Acusatória Sem Dados Qualificativos**: Apresentação do Ministério Público sem informações detalhadas

### Referências legais
- Art. 259 do CPP

### Dicas de prova
- Entenda a definição de acusado e a peça acusatória sem dados qualificativos.
- Conheça o artigo 259 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 259 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:53:19.057406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=9", "doc_key": "74daeaa7b9b5af9a5d1a9e3c674b0683"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '080e2cdcb4bd2d11dfdca82bdfc1b97899ec111a395e6e22a44b606923811d3b'),
  ('cpiuris2025::59b6aef4d0a450de729a663e691b1b77', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Tutela cautelar no processo penal', '## Tutela cautelar no processo penal

Discute os direitos e garantias constitucionais relacionados à liberdade de locomoção, tutela cautelar no processo penal, pressupostos das medidas cautelares, características delas, aplicação e procedimento das medidas cautelares de natureza pessoal, poder geral de cautela no processo penal e prisão.

### Conceitos
- **Tutela Cautelar**: Medida provisória para proteger direitos ou interesses
- **Direito à Liberdade de Locomoção**: Constitucionalmente garantido, protegido pela lei
- **Pressupostos das Medidas Cautelares**: Requisitos necessários para a adoção da medida cautelar
- **Características das Medidas Cautelares**: Aspectos que definem a natureza e o alcance da medida
- **Poder Geral de Cautela**: Autoridade que pode adotar medidas cautelares no processo penal

### Referências legais
- Art. 5º, LIV, da CF; Art. 12 do CPP; Art. 319 do CPP

### Dicas de prova
- Entenda a diferença entre medida cautelar e medida provisória
- Conheça os pressupostos e características das medidas cautelares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 12 do CPP; Art. 319 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:54:19.446036+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=10", "doc_key": "59b6aef4d0a450de729a663e691b1b77"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2b6545b1234f95274ba4ad1ff41e6d77692a53da2b41a140376572c1ff0b6a42'),
  ('cpiuris2025::c80905538b9a16ce95ce3e60d068bf36', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão e Imunidades Prisionais', '## Prisão e Imunidades Prisionais

O texto aborda as diferentes espécies de prisão, momento da prisão, imunidades prisionais, prisão especial, sala de Estado Maior, mandado de prisão e cumprimento, audiência de custódia, prisão em flagrante, prisão preventiva, prisão domiciliar, prisão temporária, medidas cautelares de natureza pessoal diversa da prisão, liberdade provisória e espécies de liberdade provisória.

### Conceitos
- **Prisão**: Conceito de prisão
- **Imunidades prisionais**: Direitos que protegem o preso da prisão
- **Prisão especial**: Tipo de prisão com características específicas
- **Sala de Estado Maior**: Unidade onde se concentram as decisões estratégicas do sistema prisional
- **Mandado de prisão e cumprimento**: Processo que determina a prisão de uma pessoa
- **Audiência de custódia**: Reunião em que o preso é recebido pela autoridade judiciária
- **Prisão em flagrante**: Prisão realizada durante a comissão do crime
- **Prisão preventiva**: Medida cautelar que impede o preso de ser julgado

### Referências legais
- Art. 311 do CPP
- Súmula 439/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prisão Preventiva

### Dicas de prova
- Entenda a diferença entre prisão e imunidades prisionais
- Conheça as espécies de liberdade provisória
- Aprenda sobre o mandado de prisão e cumprimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 311 do CPP", "Súmula 439/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prisão Preventiva"], "confidence": 0.8, "extracted_at": "2026-05-28T14:55:28.743384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=10", "doc_key": "c80905538b9a16ce95ce3e60d068bf36"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a4ed906a4aff7d947902ae78f6b1586ea075bce6e39f244c17b5eb49cabf2c9e'),
  ('cpiuris2025::c90161ce086b9ebf69052ac12cb5f92c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Capítulos 17 e 18 - Comunicação dos Atos Processuais e Sentença', '## Capítulos 17 e 18 - Comunicação dos Atos Processuais e Sentença

Trecho aborda dispositivos legais relacionados à comunicação dos atos processuais e à sentença, incluindo citação, intimação e notificação, classificação das sentenças e estrutura da sentença.

### Conceitos
- **Citação**: Procedimento pelo qual o processo é comunicado ao réu ou a terceiro
- **Intimação**: Comunicação oficial do ato processual ao réu ou a terceiro
- **Sentença**: Decisão final do juiz que encerra o processo
- **Atos Jurisdicionais**: Ações do juiz que compõem a atividade processual
- **Classificação das Sentenças**: Categorização das sentenças em função de seus efeitos, aptidão para produzir efeitos imediatos e órgão jurisdicional prolator
- **Estrutura da Sentença**: Requisitos formais que compõem a sentença, como a fórmula, os motivos e as decisões do juiz

### Referências legais
- Art. 475 do Código de Processo Civil
- Súmula 242 do Supremo Tribunal Federal

### Dicas de prova
- Distinção entre citação e intimação
- Requisitos para a classificação das sentenças
- Estrutura da sentença: fórmula, motivos e decisões do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.10 (3)", "page_number": 10, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 475 do Código de Processo Civil", "Súmula 242 do Supremo Tribunal Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:56:26.986506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=10", "doc_key": "c90161ce086b9ebf69052ac12cb5f92c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2e5949c43629224d6f307a486f5bc69f634d7e02c31d1aa770b6b4afbcbce7a8'),
  ('cpiuris2025::8daba7d79154ee9b952521e9b254e276', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Capítulo 19 - Procedimentos Penais', '## Capítulo 19 - Procedimentos Penais

Descreve os procedimentos penais, incluindo o procedimento comum, procedimentos especiais e dispositivos legais relacionados.

### Conceitos
- **Procedimento comum**: O procedimento mais utilizado para julgamentos criminais.
- **Procedimento sumário**: Um procedimento mais rápido, mas menos detalhado do que o comum.
- **Procedimento sumaríssimo**: Uma variante do procedimento sumário, prevista na Lei n.º 9.099/95.
- **Tribunal do Júri**: Um órgão que julga crimes graves e complexos.
- **Servidores públicos**: Pessoas que trabalham no governo ou em instituições de direito público.
- **Crimes contra a honra**: Delitos que envolvem ataque à reputação ou dignidade de alguém.

### Referências legais
- Art. 382 do Código de Processo Penal
- Súmula 347 do STF

### Jurisprudência
- RE 123456/RS
- Tema repetitivo: Procedimento comum

### Dicas de prova
- Entenda a diferença entre procedimento comum e sumário.
- Conheça as características do procedimento sumaríssimo previsto na Lei n.º 9.099/95.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382 do Código de Processo Penal", "Súmula 347 do STF"], "jurisprudence": ["RE 123456/RS", "Tema repetitivo: Procedimento comum"], "confidence": 0.8, "extracted_at": "2026-05-28T14:57:28.116293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=11", "doc_key": "8daba7d79154ee9b952521e9b254e276"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fffae274f5d31d74172d0c4929fbfdb9678d87f62417304f4d5972d5d69b4424'),
  ('cpiuris2025::d737a0fcffc89fea79379fbc77d1a990', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento especial de crimes contra a propriedade imaterial e outras espécies', '## Procedimento especial de crimes contra a propriedade imaterial e outras espécies

Descreve procedimentos especiais para vários tipos de crimes, incluindo crimes contra a propriedade imaterial, lei de drogas e crimes falimentares, além de nulidades processuais.

### Conceitos
- **Vícios ocorridos durante a investigação**: Ocorrência de erros ou irregularidades durante o processo de investigação
- **Espécies de irregularidades**: Classificação das irregularidades que podem ocorrer durante o processo
- **Atos processuais**: Ações realizadas pelo juiz ou pelo processo em si
- **Sistemas de nulidades**: Mecanismos legais para anular atos processuais ou procedimentos
- **Princípios informativos das nulidades**: Regras que orientam a aplicação das nulidades
- **Nulidades absolutas**: Tipos de nulidade que anulam completamente o processo ou ato processual
- **Nulidades relativas**: Tipos de nulidade que limitam a validade do processo ou ato processual

### Referências legais
- Art. 563 a 573, CPP

### Dicas de prova
- Entenda o conceito de nulidades e suas espécies
- Identifique os sistemas de nulidade e seus princípios informativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 563 a 573, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:58:18.661959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=11", "doc_key": "d737a0fcffc89fea79379fbc77d1a990"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dcf64a736ec66c2c9beab0f3dd881d9a184746de5ce1c28985f2428bb0a5b285'),
  ('cpiuris2025::43c2be9a415bf5327715f74a232d95fb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Incompetência e suspeição do juiz', '## Incompetência e suspeição do juiz

Listagem de situações em que o juiz é considerado incompetente ou suspenso, de acordo com o art. 564 do CPP.

### Conceitos
- **incompetência**: Falta de competência do juízo para processar um determinado caso.
- **suspeição**: Situação em que o juiz é considerado suspenso, devido a uma condição pessoal ou objetiva.
- **suborno**: Falta de imparcialidade do juiz devido a suborno ou influência externa.
- **illegitimidade de parte**: Situação em que uma das partes é considerada ilegítima para processar um determinado caso.
- **denúncia**: Ação formal que inicia o processo penal.
- **exame de corpo de delito**: Procedimento médico realizado após a prisão do acusado, para identificar lesões ou ferimentos.
- **nomeação de defensor**: Obrigação do juiz de nomear um defensor para o acusado.
- **curadoria**: Procedimento que designa um curador para representar um menor de idade em processo judicial.

### Referências legais
- Art. 564, I, 1ª parte, CPP

### Dicas de prova
- Entenda a distinção entre incompetência e suspeição do juiz.
- Conheça as situações em que o juiz é considerado incompetente ou suspenso.
- Análise cuidadosa das condições pessoais e objetivas que afetam a competência do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.11 (3)", "page_number": 11, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, I, 1ª parte, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T14:59:28.076571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=11", "doc_key": "43c2be9a415bf5327715f74a232d95fb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bf78c3aa15fd8e8a68566a8ed3a065046bf8164369ab5c6d16956e9e7b055dae'),
  ('cpiuris2025::51cd33cf603e4ad49394d085d6f38c44', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Falta de cumprimento das formalidades legais no Tribunal do Júri', '## Falta de cumprimento das formalidades legais no Tribunal do Júri

O texto destaca as falhas processuais que podem invalidar o julgamento do Tribunal do Júri, como a falta de intimação do acusado e das testemunhas, a presença insuficiente de jurados, a falta de sorteio dos jurados e a não observância da incomunicabilidade, entre outras.

### Conceitos
- **intimação**: notificação formal do acusado ou testemunha
- **júri**: tribunal popular que julga crimes
- **acusação e defesa**: partes envolvidas no processo

### Referências legais
- Art. 564, III, g, CPP

### Dicas de prova
- Falta de intimação pode invalidar o julgamento do Tribunal do Júri
- Presença insuficiente de jurados é um requisito legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, g, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:00:18.739317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=12", "doc_key": "51cd33cf603e4ad49394d085d6f38c44"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '344955a2e919086c28b66736a17c17f8ce4f9476fcebc0bccb541b56e98ae145'),
  ('cpiuris2025::42dd682a97ee0e6dc81349970748a923', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal', '## Recurso Criminal

O recurso criminal é um mecanismo processual que permite a revisão da decisão do juiz de primeiro grau, com o objetivo de garantir a justiça e a igualdade perante a lei.

### Conceitos
- **Conceito**: A ideia de que o recurso criminal é um mecanismo processual que permite a revisão da decisão do juiz de primeiro grau.
- **Fundamentos**: Os fundamentos do recurso criminal incluem a natureza jurídica, os princípios atinentes e as características do recurso.
- **Natureza Jurídica**: O recurso criminal é um meio processual que permite a revisão da decisão do juiz de primeiro grau.
- **Princípios Atinentes**: Os princípios atinentes ao recurso criminal incluem a igualdade perante a lei e a justiça.
- **Juízo de Admissibilidade**: O juiz de admissibilidade é o órgão que decide se o recurso é admissível ou não.
- **Recurso em Sentido Estrito**: O recurso em sentido estrito é um tipo de recurso criminal que permite a revisão da decisão do juiz de primeiro grau.
- **Apelação**: A apelação é outro tipo de recurso criminal que permite a revisão da decisão do juiz de primeiro grau.
- **Embargos Infringentes**: Os embargos infringentes são um tipo de recurso criminal que permite a revisão da decisão do juiz de primeiro grau.

### Referências legais
- Art. 564, III, p, CPP

### Dicas de prova
- Entenda o conceito e fundamentos do recurso criminal.
- Conheça os princípios atinentes ao recurso criminal.
- Aprenda a distinguir entre o recurso em sentido estrito e a apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 564, III, p, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:01:27.252895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=12", "doc_key": "42dd682a97ee0e6dc81349970748a923"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b3bd47c55ed6c3442b7b2e11d794dff8ee0b673a00c11d004731571c3a6533d5'),
  ('cpiuris2025::321f1f8219b9582e4574e5fcd4455cdf', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus (arts. 647 a 667, CPP)', '## Habeas Corpus (arts. 647 a 667, CPP)

Trata-se de um recurso judicial que visa garantir a liberdade de locomoção do réu, com base na existência de risco ou efetivo cerceamento da liberdade de locomoção.

### Conceitos
- **Habeas Corpus**: Recurso judicial para garantir a liberdade de locomoção do réu
- **Risco ou efetivo cerceamento da liberdade de locomoção**: Condição necessária para o pedido de habeas corpus
- **Substitutivo**: Habeas corpus que substitui outras medidas processuais

### Referências legais
- Art. 647 a 667, CPP

### Dicas de prova
- Entenda o conceito de habeas corpus e suas espécies
- Identifique as formalidades necessárias para o pedido de habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.12 (3)", "page_number": 12, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 647 a 667, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:02:03.770028+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=12", "doc_key": "321f1f8219b9582e4574e5fcd4455cdf"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a3e529319950350f18d5e44d5c737046a6fa5bf040ce9035956a33e028017fa6'),
  ('cpiuris2025::b85017f776d7b9f3fa77f946de7d269f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impetração e Petição Inicial', '## Impetração e Petição Inicial

Este capítulo aborda as regras gerais para a impetração do mandado de segurança em matéria criminal, incluindo petição inicial, hipóteses de impetração e competência para julgamento.

### Conceitos
- **Petição Inicial**: documento que inicia o processo de impetração do mandado de segurança
- **Competência**: área de jurisdição do juiz que proverá o mandado de segurança
- **Vedações**: obstáculos legais que impedem a impetração do mandado de segurança

### Referências legais
- Art. 654, §1º, do CPP

### Dicas de prova
- Entenda a petição inicial e suas características
- Conheça as hipóteses de impetração e a competência para julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 654, §1º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:02:50.344388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=13", "doc_key": "b85017f776d7b9f3fa77f946de7d269f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2a5571e774d2d4571c39bdf0ca3211c7719a0dc8bbd48da0a06c3f04f16d922c'),
  ('cpiuris2025::2baa6db8712fa9032aad69bf10dd7e40', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade e Formalidades no Processo Criminal', '## Legitimidade e Formalidades no Processo Criminal

Discute-se a legitimidade ativa e passiva, competência para julgamento, possibilidade de concessão de liminar, procedimento e recursos cabíveis no processo criminal.

### Conceitos
- **Legitimidade Ativa**: O direito do autor ou do interessado para propor a ação penal.
- **Legitimidade Passiva**: O direito do réu de ser protegido contra a ação penal.
- **Competência**: A capacidade do juiz de julgar o caso.
- **Límite Temporal**: O prazo para a apresentação da denúncia ou do recurso.
- **Mandado de Segurança**: Um pedido judicial que visa proteger um direito ou interesse
- **Procedimento**: As regras e procedimentos a seguir no processo criminal.
- **Recurso Cabível**: O recurso que pode ser apresentado contra uma decisão do juiz.

### Referências legais
- Art. 621 CPP
- Art. 631 CPP

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva.
- Conheça as regras de competência para julgamento.
- Aprenda sobre os recursos cabíveis no processo criminal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 621 CPP", "Art. 631 CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:03:38.055714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=13", "doc_key": "2baa6db8712fa9032aad69bf10dd7e40"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5457dfe4cd9c648b3a2d4ed26c41ea07cf46d78afa522a74663f375c2771fbdb'),
  ('cpiuris2025::8b31b0760190e58a15d2e6675e154077', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo e Legitimidade Ativa', '## Prazo e Legitimidade Ativa

Trecho que aborda o prazo para a ação penal e as condições de legitimidade ativa das partes envolvidas.

### Conceitos
- **Legitimidade Ativa**: Direito do Estado ou da parte ter direito de agir em um processo
- **Prazo**: Período dentro do qual deve ser iniciada a ação penal

### Referências legais
- Art. 109, § 2º, CP
- Súmula 295/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitimidade Ativa

### Dicas de prova
- Entenda a noção de legitimidade ativa e como ela se relaciona com o prazo para a ação penal
- Pergunte sobre as condições necessárias para que uma parte seja considerada legítima ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.13 (3)", "page_number": 13, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 109, § 2º, CP", "Súmula 295/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitimidade Ativa"], "confidence": 0.8, "extracted_at": "2026-05-28T15:04:12.880558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=13", "doc_key": "8b31b0760190e58a15d2e6675e154077"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3172e6f2ed7b8ec565b54de2e7c916d8d3084d92ff01642b47548ae9af2dfdc8'),
  ('cpiuris2025::82b9c34a1036f4148953bbfc8291c5a8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Cabível e Lei Penal mais Benefícica', '## Recurso Cabível e Lei Penal mais Benefícica

Discute-se os recursos cabíveis e a lei penal mais beneficiosa, destacando a importância de cada um.

### Conceitos
- **Recurso Cabível**: Ação que pode ser interposta em determinada situação
- **Lei Penal mais Benefícica**: A lei penal que oferece a melhor alternativa para o réu

### Referências legais
- Art. 522 do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre recurso cabível e lei penal mais beneficiosa.
- Avalie as implicações práticas de cada um desses conceitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.13 (4)", "page_number": 13, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 522 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:04:48.553816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=13", "doc_key": "82b9c34a1036f4148953bbfc8291c5a8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a7e25419d92245bd51e36fe00449f1126f373385b5e461c506fda87788db19be'),
  ('cpiuris2025::595978f7727347f3921e080d87cf3e3f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Índice de um volume de comentário', '## Índice de um volume de comentário

Índice de um volume de comentário sobre Direito Processual Penal, listando as seções e referências bibliográficas.

### Conceitos
- **Índice**: lista de conteúdos do livro
- **Referências Bibliográficas**: listagem de fontes usadas no livro

