  ('cpiuris2025::23920204f4997bdafb3a981ee1ef709f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistemas Processuais Penais', '## Sistemas Processuais Penais

O direito de punir se transforma em direito de punir concreto quando alguém desrespeita a norma penal e pratica uma conduta delituosa. O Estado passa a ter uma pretensão concreta de punir o infrator, surgindo a pretensão punitiva, que é o poder-dever do Estado de exigir a submissão à sanção penal.

### Conceitos
- **Ius Puniendi**: direito de punir
- **Pretensão Punitiva**: poder-dever do Estado de exigir a submissão à sanção penal
- **Processo Penal**: instrumento do qual se vale o Estado para imposição de sanção penal ao possível autor do fato delituoso

### Referências legais
- Art. 5º, LIV da CF
- Súmula 279/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre ius puniendi e pretensão punitiva.
- Conheça os sistemas processuais penais: inquisitorial, acusatório e misto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 279/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T15:06:00.262655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=15", "doc_key": "23920204f4997bdafb3a981ee1ef709f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1fbcfad2d5b71b7ed64788cd4f1ef735c7db0d25e9019531a554aedda0b38043'),
  ('cpiuris2025::8a09d296400b20f3695fdeebb27e3d36', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condições para a realização do contraditório', '## Condições para a realização do contraditório

O juiz não pode ser comprometido e, em caso de ausência de defesa e acusação contraposta, não há princípio do contraditório. A concentração de poderes no juiz torna in concebível a ideia de contraditório.

### Conceitos
- **Imparcialidade**: A capacidade de o juiz tomar decisões justas e imparciais
- **Contraditório**: O direito do acusado e do réu de apresentar argumentos contrários à acusação

### Referências legais
- Art. 5º, LIV da CF
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre imparcialidade e contraditório
- Consequências de ausência de defesa e acusação contraposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T15:06:43.848865+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=15", "doc_key": "8a09d296400b20f3695fdeebb27e3d36"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c11ac5dfdacdf1e580bb92df86ef9d8edf46b8a965c37452cad89f784fa99785'),
  ('cpiuris2025::1241cc0f053ffab4f05f0af9f94baa07', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistemas processuais penais', '## Sistemas processuais penais

O sistema inquisitorial é caracterizado pela concentração de poderes no juiz inquisidor, que tem liberdade para determinar a colheita de provas. Já o sistema acusatório apresenta uma separação das funções de acusar, defender e julgar, com o princípio da presunção de inocência.

### Conceitos
- **Sistema inquisitorial**: Caracterizado pela concentração de poderes no juiz inquisidor
- **Sistema acusatório**: Caracterizado pela separação das funções de acusar, defender e julgar
- **Princípio da presunção de inocência**: O acusado permanece solto durante o processo
- **Iniciativa probatória**: Deve ser fornecida pelas partes, não pelo juiz

### Referências legais
- Art. 5º da Constituição Brasileira
- Código de Processo Penal

### Dicas de prova
- Distinguir entre o sistema inquisitorial e acusatório
- Entender a importância do princípio da presunção de inocência
- Conhecer as características do sistema acusatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º da Constituição Brasileira", "Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:07:37.700350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=16", "doc_key": "1241cc0f053ffab4f05f0af9f94baa07"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1f35d6e03af17e80fc3b541fdc99611b4bc3fe0e083127e4388491d716bdaa42'),
  ('cpiuris2025::5e35404f95686dace9db52e7a6a6259c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema Acusatório e Direitos do Acusado', '## Sistema Acusatório e Direitos do Acusado

O sistema acusatório é reconhecido pela Constituição de 1988, com direitos fundamentais para o acusado, como sujeito de direitos e igualdade de condições nas partes. O Ministério Público tem privativa da propositura da ação penal pública.

### Conceitos
- **Princípio da Busca da Verdade**: Substitui o princípio da verdade real, enfatizando a busca da verdade através do contraditório e ampla defesa.
- **Direitos Fundamentais do Acusado**: Incluem sujeito de direitos e igualdade de condições nas partes.
- **Sistema Acusatório**: Reconhecido pela Constituição de 1988, com características como a propositura da ação penal pública privativa do Ministério Público.
- **Ministério Público**: Tem funções institucionais, incluindo a promover a ação penal pública.

### Referências legais
- Art. 129, I da CF/88

### Dicas de prova
- Entenda o sistema acusatório e os direitos do acusado.
- Destaque a propositura da ação penal pública privativa do Ministério Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 129, I da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:08:23.865398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=16", "doc_key": "5e35404f95686dace9db52e7a6a6259c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '619876e8b35c6c794fbcc158ee81daeb97a40746885be4f4aa95fd806bd4dddd'),
  ('cpiuris2025::8fbc36a70e41b55247ff0e6abaa66a26', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema Acusatório vs Inquisitorial', '## Sistema Acusatório vs Inquisitorial

O sistema acusatório é caracterizado pela escolha do sistema pelo processo penal brasileiro, com a iniciativa do órgão de acusação e controle da legalidade da investigação criminal pelo juiz das garantias. O sistema inquisitorial, por outro lado, concentra as funções de acusar, defender e julgar em uma única pessoa, o juiz inquisidor.

### Conceitos
- **Sistema Acusatório**: Caracterizado pela escolha do sistema pelo processo penal brasileiro
- **Sistema Inquisitorial**: Concentra as funções de acusar, defender e julgar em uma única pessoa, o juiz inquisidor
- **Juiz das Garantias**: Responsável pelo controle da legalidade da investigação criminal e pela salvaguarda dos direitos individuais
- **Iniciativa Acusatória**: Recai sobre o órgão de acusação, com restrição à fase judicial
- **Princípio da Busca da Verdade**: O objetivo é encontrar a verdade, com observância do contraditório e da ampla defesa

### Referências legais
- Art. 3º-A do CPP
- Art. 8º, §1º da CADH

### Dicas de prova
- Entenda a diferença entre o sistema acusatório e inquisitorial
- Conheça a figura do juiz das garantias e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-A do CPP", "Art. 8º, §1º da CADH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:09:38.222570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=17", "doc_key": "8fbc36a70e41b55247ff0e6abaa66a26"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9ebdd4bc598d94ef0fef2f5b3afd0a9f70be8af6cdaed84dfbde64f688220d63'),
  ('cpiuris2025::951d8e7ea98b062b8610a4dcebc71335', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema Misto ou Francês', '## Sistema Misto ou Francês

O sistema misto francês é uma fusão dos modelos inquisitorial e acusatório, caracterizado por duas fases distintas: inquisitorial e acusatória.

### Conceitos
- **Sistema Misto**: Fusão dos modelos inquisitorial e acusatório
- **Inquisitorial**: Modelo que não envolve contraditório
- **Acusatório**: Modelo que envolve contraditório

### Referências legais
- Code d’Instruction Criminelle francês, de 1808

### Dicas de prova
