  ('cpiuris2025::b09d7b73c2d5fe405222c5e8f2e1af08', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema Processual Penal', '## Sistema Processual Penal

O sistema processual penal brasileiro é acusatório, com separação das funções de acusar, defender e julgar, garantindo o contraditório, a ampla defesa e a presunção de não culpabilidade.

### Conceitos
- **Sistema Acusatório**: Processo em que o órgão acusador apresenta a acusação, o réu se defende e o juiz julga.
- **Separação das Funções**: Divisão das funções de acusar, defender e julgar para garantir o contraditório, a ampla defesa e a presunção de não culpabilidade.
- **Investigação Prévia**: Procedimento realizado antes do início do processo para coletar provas.
- **Previsão Legal de Prisões Processuais**: Regras estabelecidas pela lei que determinam a duração da prisão do réu durante o processo.
- **Modelo Fascista Italiano**: Influência do sistema processual italiano fascista no Código de Processo Penal brasileiro.

### Referências legais
- Art. 5º, LXXII da CF/88
- Súmula 623/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a separação das funções de acusar, defender e julgar no sistema processual penal brasileiro.
- Conheça as garantias do réu durante o processo, como o contraditório e a ampla defesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXXII da CF/88", "Súmula 623/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T15:11:10.678588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=18", "doc_key": "b09d7b73c2d5fe405222c5e8f2e1af08"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3bcffae7bc8998e265ed97fb4cd9be045562362bc4ebf78657e19cf5ae75b934'),
  ('cpiuris2025::1b7e6964cfaed8d88e4a2dc2241b0d7c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema Acusatório', '## Sistema Acusatório

O texto discute a rejeição do pedido da Procuradoria-Geral da República (PGR) para arquivamento de inquérito e suspensão de atos relacionados à investigação de ofensas contra integrantes do STF.

### Conceitos
- **Sistema Acusatório**: sistema que atribui a responsabilidade ao autor dos fatos
- **Inquérito Policial**: investigação realizada por um delegado de polícia
- **Ministério Público**: órgão responsável pela fiscalização do cumprimento das leis
- **Procuradoria-Geral da República**: órgão que representa o Estado na defesa dos seus interesses
- **Delegado de Polícia**: autoridade responsável pela investigação de crimes

### Referências legais
- Art. 2º da Lei nº 7.210/82
- Súmula 657 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Instauração de inquérito policial

