  ('cpiuris2025::57f20c2c34c9463881ed72c7c6df3907', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistema processual penal e características do sistema acusatório', '## Sistema processual penal e características do sistema acusatório

O texto discute as características do sistema acusatório, destacando a gestão da prova nas mãos das partes, a clara distinção entre as atividades de acusar e julgar, a publicidade dos atos processuais e a igualdade de oportunidades às partes no processo.

### Conceitos
- **Sistema acusatório**: Caracteriza-se pela gestão da prova nas mãos das partes, com clara distinção entre as atividades de acusar e julgar.
- **Gestão da prova**: É feita pelas partes, com a responsabilidade de produzir provas relevantes e urgentes.
- **Publicidade dos atos processuais**: Os atos do processo são públicos, garantindo a transparência e a igualdade de oportunidades às partes.
- **Igualdade de oportunidades**: As partes têm igualdade de oportunidades para produzir provas e defender seus interesses.

### Referências legais
- Art. 5º, LIV, do Código de Processo Penal

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Entenda a distinção entre as atividades de acusar e julgar no sistema acusatório.
- Conheça os dispositivos do Código de Processo Penal que facultam ao juiz a produção antecipada de provas consideradas urgentes e relevantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.19", "page_number": 19, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, do Código de Processo Penal"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.9, "extracted_at": "2026-05-28T15:13:03.926535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=19", "doc_key": "57f20c2c34c9463881ed72c7c6df3907"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd2bb3351cbb1f3b657f1872c2c545654048678b2b8a152cda6120e856bf56742'),
  ('cpiuris2025::d9f6c62201bcf35e5db73acf90211ef2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Sistemas processuais penais', '## Sistemas processuais penais

