- **Sistema Acusatório**: Caracterizado pela separação das funções de acusador, defensor e julgador
- **Sistema Inquisitivo**: Caracterizado pela iniciativa probatória do juiz ou do Estado
- **Iniciativa Probatória**: A capacidade do juiz de iniciar a investigação sem a necessidade de uma solicitação das partes

