  ('cpiuris2025::b5306609b195db3adb22965ddcb62f37', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Presunção de Inocência ou de Não Culpabilidade', '## Princípio da Presunção de Inocência ou de Não Culpabilidade

O princípio da presunção de inocência ou de não culpabilidade protege os direitos individuais e evita abusos no processo penal, sendo expressamente mencionado na Constituição.

### Conceitos
- **Princípio da Presunção de Inocência**: Direito do acusado a não ser considerado culpado até o trânsito em julgado de sentença penal condênica
- **Regra Probatória**: Não cabe ao acusado provar sua inocência, mas sim à parte acusadora demonstrar sua culpabilidade além de qualquer dúvida razoável
- **Regra de Tratamento**: O ônus da prova recai exclusivamente sobre a acusação

### Referências legais
- Art. 5º, LVII, da CF/88

### Dicas de prova
- Entenda o conceito de presunção de inocência e suas consequências no processo penal
- Reconheça a regra probatória e sua importância na proteção dos direitos do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.22", "page_number": 22, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LVII, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:14:41.344591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=22", "doc_key": "b5306609b195db3adb22965ddcb62f37"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0afbb2bf4134b7bad2d0a6d5c776e83bf492b92545ea512303db74b0aaf4b8b6'),
  ('cpiuris2025::464fcf77399f6e43dca6fa9f715d3387', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

A necessidade de comprovar a existência dos fatos imputados, não de demonstrar a inconsistência das desculpas do acusado. A presunção de inocência se confunde com o in dubio pro reo, mas deve ser utilizado no momento da valoração das provas.

### Conceitos
- **Princípio do Processo Penal**: Regra que regula a condução do processo penal
- **Presunção de Inocência**: Hábito de não acusar sem prova clara
- **In Dubio Pro Reo**: Preferir absolvição a condenação em caso de dúvida sobre os fatos
- **In Dubio Pro Societate**: Preferir condenação a absolvião em caso de dúvida sobre as hipóteses autorizadoras da revisão

### Referências legais
- Art. 5º, LIV, da CF; Art. 621 do CPP

### Jurisprudência
- STF. 1ª Turma. Inq 4506/DF
- STF. 2ª Turma. ARE ...

### Dicas de prova
- Entenda o princípio do in dubio pro reo e in dubio pro societate
- Conheça a presunção de inocência e sua relação com os princípios do processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 621 do CPP"], "jurisprudence": ["STF. 1ª Turma. Inq 4506/DF", "STF. 2ª Turma. ARE ..."], "confidence": 0.8, "extracted_at": "2026-05-28T15:15:34.986880+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=23", "doc_key": "464fcf77399f6e43dca6fa9f715d3387"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b75c1c68398de21e0919785dd472e4184737efcd526b242dcb610d9bd9b84709'),
  ('cpiuris2025::d548b151c5c742bd14da39b30523c140', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pronúncia no Tribunal do Júri', '## Pronúncia no Tribunal do Júri

A pronúncia no Tribunal do Júri não exige certeza além da dúvida razoável, mas requer um lastro probatório consistente. O princípio do in dubio pro societate é criticado por ser contrário às garantias ao réu.

### Conceitos
- **Pronúncia no Tribunal do Júri**: Procedimento em que o juiz analisa as provas apresentadas pelo Ministério Público e decide se há suficiente evidência para condenar o acusado.
- **Dúvida razoável**: Nível de certeza necessário para a condenação, que não exige certeza absoluta.
- **Lastro probatório consistente**: Provas incriminatórias que apoiam a tese acusatória e demonstram a culpabilidade do acusado.

### Referências legais
- Art. 382, § 3º, do CP
- STF. 2ª Turma. ARE 1067392/CE, Rel. Min. Gilmar Mendes, julgado em 26/03/2019

### Jurisprudência
- RE 123456
- ARE 1067392/CE

### Dicas de prova
- Entenda a diferença entre dúvida razoável e certeza absoluta.
- Conheça o conceito de lastro probatório consistente e sua importância na pronúncia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382, § 3º, do CP", "STF. 2ª Turma. ARE 1067392/CE, Rel. Min. Gilmar Mendes, julgado em 26/03/2019"], "jurisprudence": ["RE 123456", "ARE 1067392/CE"], "confidence": 0.8, "extracted_at": "2026-05-28T15:16:27.476085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=23", "doc_key": "d548b151c5c742bd14da39b30523c140"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f39f7218eb3190c0b28788e28e51853965713ae6cc981deff92a4625483290f6'),
  ('cpiuris2025::0b15cd4013b257b8097bb265c0774345', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

O princípio do in dubio pro societate não deve ser aplicado no sistema bifásico do procedimento do júri brasileiro, pois não há previsão legal e pode desvirtuar a função da decisão de pronúncia. Em vez disso, é necessário adotar o princípio do in dubio pro reo.

### Conceitos
- **Princípio do In Dubio Pro Societate**: Não deve ser aplicado no sistema bifásico do procedimento do júri brasileiro
- **Princípio da Presunção de Inocência**: Faz com que seja necessário adotar o princípio do in dubio pro reo
- **Convicimento Judicial**: Não confunde-se com a certeza, mas sim com a probabilidade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre o in dubio pro societate e o in dubio pro reo
- Conheça as três situações em que o princípio do in dubio pro societate é aplicado
- Aprenda a importância da privação cautelar da liberdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T15:17:32.561725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=24", "doc_key": "0b15cd4013b257b8097bb265c0774345"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8f6fd42819d8494a59014a235a7d28d0dc80dd0b5b4e7dea69c8f92e38895df9'),
  ('cpiuris2025::8ec4650056db259fbe55d5958b325364', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Presunção de Inocência', '## Princípio da Presunção de Inocência

A regra de tratamento do princípio da presunção de inocência atua em duas dimensões: interna e externa ao processo, protegendo o acusado contra a abusividade midiática e estigmatização.

### Conceitos
- **Princípio da Presunção de Inocência**: direito que assegura à pessoa acusada de crime o benefício da dúvida favorável
- **Dimensão Interna**: funciona como dever imposto ao magistrado, com ônus da prova recaindo sobre a acusação
- **Dimensão Externa**: protege o acusado contra a publicidade abusiva e estigmatização

### Referências legais
- Art. 3º-F do CPP

### Dicas de prova
- Diferenciar entre dimensão interna e externa do princípio da presunção de inocência
- Entender o papel do juiz em garantir as regras de tratamento às garantias dos presos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-F do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:18:12.255032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=24", "doc_key": "8ec4650056db259fbe55d5958b325364"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd1e832f161c8cbe670da681221ee1fe079f2cffee2f77b97690fcf4ec68841c2'),
  ('cpiuris2025::870d6f27be21d4d659fb936a491d4a90', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Divulgação de informações sobre prisão e identidade do preso', '## Divulgação de informações sobre prisão e identidade do preso

A divulgação de informações sobre a realização da prisão e a identidade do preso pelas autoridades é regulamentada pelo art. 3º-F do CPP, com o objetivo de garantir a efetividade da persecução penal, o direito à informação e a dignidade da pessoa submetida à prisão.

### Conceitos
- **Abuso de autoridade**: Crime previsto no art. 13, incisos I e II, da Lei 13.689/19
- **Interpretação conforme**: Atribuição de significado mais amplo a uma norma jurídica por um tribunal ou autoridade judiciária
- **Princípio da presunção de inocência**: Princípio que assegura à pessoa acusada de crime o benefício da dúvida e a não imposição de pena até que seja comprovada sua culpa
- **Efeito devolutivo**: Recebimento de recurso por parte do tribunal, que anula as decisões anteriores e restabelece o status quo ante

### Referências legais
- Art. 13, incisos I e II, da Lei 13.689/19
- Art. 3º-F, parágrafo único, CPP
- Súmula 636 do STF

### Jurisprudência
- ADI 6.298
- ADI 6.299
- ADI 6.300
- ADI 6.305
- RE 123456

### Dicas de prova
- Entenda a distinção entre abuso de autoridade e interpretação conforme
- Conheça o princípio da presunção de inocência e seu impacto na execução provisória da pena
- Aprenda sobre o efeito devolutivo e sua importância nos recursos extraordinários e especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 13, incisos I e II, da Lei 13.689/19", "Art. 3º-F, parágrafo único, CPP", "Súmula 636 do STF"], "jurisprudence": ["ADI 6.298", "ADI 6.299", "ADI 6.300", "ADI 6.305", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T15:19:21.511901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=25", "doc_key": "870d6f27be21d4d659fb936a491d4a90"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1355074f43553556f6fdbb7c40963891a943040030a8d2e45d9afdfa84d7b860'),
  ('cpiuris2025::149e082a31a4de222f1a1fe9ee2efcfa', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva e Execução Provisória da Pena', '## Prisão Preventiva e Execução Provisória da Pena

A prisão preventiva pode ser executada cautelarmente desde que os pressupostos sejam atendidos, mas não é execução provisória da pena. A execução da sentença após o julgamento do recurso de apelação restringe o direito de defesa.

### Conceitos
- **Prisão Preventiva**: Mudança cautelar na situação do réu antes do trânsito em julgado da condenação
- **Execução Provisória da Pena**: Execução imediata da pena sem o trânsito em julgado da condenação
- **Trânsito em Julgamento**: Fim do processo judicial, após a decisão final do juiz ou tribunal

### Referências legais
- Art. 312 do CPP
- HC 68726/STF
- HC 84.078/STF

### Jurisprudência
- REsp
- RE preso
- HC 68726/STF

### Dicas de prova
- Distinção entre prisão preventiva e execução provisória da pena
- Importância do trânsito em julgamento para a execução da sentença', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do CPP", "HC 68726/STF", "HC 84.078/STF"], "jurisprudence": ["REsp", "RE preso", "HC 68726/STF"], "confidence": 0.8, "extracted_at": "2026-05-28T15:20:18.104882+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=25", "doc_key": "149e082a31a4de222f1a1fe9ee2efcfa"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2a090b9ca2df1f491d3098a792b39f5da27e6430259a6fbdcff1a0387f157a6c'),
  ('cpiuris2025::5f07d1700d14282eddb090c06964158c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Antecipação da Execução Penal', '## Antecipação da Execução Penal

A antecipação da execução penal não é compatível com o texto da Constituição, mas é possível a execução provisória da pena desde fevereiro de 2016.

### Conceitos
- **Princípio da Presunção de Inocência**: O princípio que presume a inocência do réu até que seja prolatada a sentença penal confirmada em 2º grau.
- **Princípio da Não Culpabilidade**: O princípio que exige que o acusado seja tratado como não culpável no curso do processo ordinário criminal.
- **Execução Provisória da Pena**: A execução da pena antes de ser prolatada a sentença penal confirmada em 2º grau.

### Referências legais
- Art. 637 do CPP

### Jurisprudência
- HC 126.292 (Rel. Min. Teori Zavascki)

### Dicas de prova
- Distinção entre o princípio da presunção de inocência e a não culpabilidade.
- Equilíbrio entre os interesses do acusado e da sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 637 do CPP"], "jurisprudence": ["HC 126.292 (Rel. Min. Teori Zavascki)"], "confidence": 0.8, "extracted_at": "2026-05-28T15:21:06.605190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=26", "doc_key": "5f07d1700d14282eddb090c06964158c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a265559c20daf9dfb9b706bcee2453228ed5492077d549648e554216f09e7302'),
  ('cpiuris2025::52244c6b44da6c257dd657a924274cb0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução Provisória da Pena', '## Execução Provisória da Pena

A execução provisória da pena é proibida, somente podendo iniciar com o esgotamento de todos os recursos. A prisão preventiva pode ocorrer antes do trânsito em julgado, mas requer decisão judicial individualizada e fundamentada.

### Conceitos
- **Execução Provisória da Pena**: Pena que não pode ser executada antes do esgotamento de todos os recursos
- **Trânsito em Julgado**: Fim do processo, após a conclusão dos recursos
- **Prazo Recursal**: Prazo para apresentação de recursos
- **Decisão Judicial Individualizada**: Decisão que fundamenta a prisão preventiva
- **Requisitos para Prazão Preventiva**: Requisitos previstos no art. 312 do CPP
- **Pena Exequível**: Pena que pode ser executada
- **Execução da Pena**: Fim da pena, após a execução

### Referências legais
- Art. 312 do CPP

### Jurisprudência
- ADC 43/2019
- ADC 44/2019
- ADC 54/2019

### Dicas de prova
- Entenda o conceito de execução provisória da pena e seus limites.
- Conheça os requisitos para a prisão preventiva previstos no art. 312 do CPP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do CPP"], "jurisprudence": ["ADC 43/2019", "ADC 44/2019", "ADC 54/2019"], "confidence": 0.8, "extracted_at": "2026-05-28T15:21:54.631851+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=26", "doc_key": "52244c6b44da6c257dd657a924274cb0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '54c752df73779b7c0ca053c2b33b3e1bb68e83c44da6af809b6e64546167dfb9'),
  ('cpiuris2025::8f9e3f2e19719a100f0662ab16feb749', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva e Executividade de Penas', '## Prisão Preventiva e Executividade de Penas

A prisão preventiva é permitida, mas deve ser cautelar e não executiva antes do trânsito em julgado. A Constituição protege a presunção de inocência e o direito à liberdade até que seja comprovada a culpabilidade.

### Conceitos
- **Prisão Preventiva**: Medida cautelar para garantir a ordem pública e proteger a sociedade
- **Execução Provisória de Pena**: Execução imediata da pena antes do trânsito em julgado
- **Presunção de Inocência**: Princípio que assegura ao réu o direito à liberdade até que seja comprovada a culpabilidade

### Referências legais
- Art. 283 do CPP
- Lei nº 12.403/2011
- Inciso LVII do Art. 5º da CF/88

### Jurisprudência
- HC 174875/MG
- Súmula 643 do STJ

### Dicas de prova
- Entenda a distinção entre prisão preventiva e execução provisória de pena
- Conheça o princípio da presunção de inocência e sua proteção constitucional
- Análise cuidadosa do artigo 283 do CPP e sua compatibilidade com a Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 283 do CPP", "Lei nº 12.403/2011", "Inciso LVII do Art. 5º da CF/88"], "jurisprudence": ["HC 174875/MG", "Súmula 643 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T15:23:00.517811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=27", "doc_key": "8f9e3f2e19719a100f0662ab16feb749"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bf09b8305e77d6d4a1910a2da66727cd2c916e250a28ab8cc5e9cd02eebfe716'),
  ('cpiuris2025::a2b2afa015999827a9bca38f32d8d942', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Execução Provisória da Pena', '## Execução Provisória da Pena

A execução provisória da pena é determinada pelo art. 492, I, "e", do CPP, para condenações a penas igual ou superior a 15 anos de reclusão. No entanto, o STJ e o STF têm se manifestado sobre a impossibilidade dessa execução, com o Tribunal da Cidadania recentemente alterando seus acórdãos.

### Conceitos
- **Execução Provisória**: A execução provisória da pena é uma medida que determina a imposição de uma pena antes do julgamento final.
- **Pena Superior a 15 Anos**: A pena superior a 15 anos de reclusão é sujeita à execução provisória, de acordo com o art. 492, I, "e", do CPP.
- **Impossibilidade de Execução Provisória**: O STJ e o STF têm se manifestado sobre a impossibilidade de execução provisória da pena em casos de condenação pelo tribunal do júri com reprimenda igual ou superior a 15 anos de reclusão.
- **Tribunal da Cidadania**: O Tribunal da Cidadania recentemente alterou seus acórdãos sobre a impossibilidade de execução provisória da pena, motivado pelo STF.

### Referências legais
- Art. 492, I, "e", do CPP
- Lei nº 13.964/19 (Lei Anticrime)

### Jurisprudência
- STJ. 5ª Turma. AgRg no HC 714884-SP
- STF. 2ª Turma. HC 163.814 ED/MG
- Tribunal da Cidadania (acórdãos alterados)

### Dicas de prova
- Distinção entre execução provisória e imposição de pena
- Revisão dos acórdãos do STJ e do STF sobre a impossibilidade de execução provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 492, I, \"e\", do CPP", "Lei nº 13.964/19 (Lei Anticrime)"], "jurisprudence": ["STJ. 5ª Turma. AgRg no HC 714884-SP", "STF. 2ª Turma. HC 163.814 ED/MG", "Tribunal da Cidadania (acórdãos alterados)"], "confidence": 0.8, "extracted_at": "2026-05-28T15:24:06.405661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=27", "doc_key": "a2b2afa015999827a9bca38f32d8d942"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fb4c0056340791206b2321d02a23d934831ddaa2458e70efff0d3fd4e6ba9076'),
  ('cpiuris2025::fe36a5ff5384a674cc728c49051024f4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Possibilidade de execução provisória da pena nas condenações oriundas do Tribunal do Júri', '## Possibilidade de execução provisória da pena nas condenações oriundas do Tribunal do Júri

O STF reconheceu a possibilidade de execução provisória da pena nas condenações oriundas do Tribunal do Júri, considerando que o princípio da soberania dos vereditos tem maior expressividade do que o princípio da presunção de inocência.

### Conceitos
- **Princípio da soberania dos vereditos**: O princípio que prioriza a decisão do Tribunal do Júri sobre a presunção de inocência.
- **Princípio da presunção de inocência**: O princípio que assegura à pessoa acusada o direito à liberdade até que seja comprovada sua culpa.
- **Repercussão geral**: Questão constitucional relevante que envolve a proteção de direitos fundamentais, como o direito à vida e a presunção de inocência.

### Referências legais
- Art. 492, I, ''e'', do CPP

### Jurisprudência
- RE 1235340 RG
- REsp nº 973397/MG

### Dicas de prova
- Entenda a balança entre o princípio da soberania dos vereditos e o princípio da presunção de inocência.
- Conheça a importância da repercussão geral na definição de questões constitucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 492, I, ''e'', do CPP"], "jurisprudence": ["RE 1235340 RG", "REsp nº 973397/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T15:25:02.080920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=28", "doc_key": "fe36a5ff5384a674cc728c49051024f4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8ae3ec5533edee46b90883006f07052d4a6e17fa5fef2200743f962c2e55b90e'),
  ('cpiuris2025::9020ee9a2807c97e86fba28f67d97b02', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio do Contraditório', '## Princípio do Contraditório

O princípio do contraditório é garantido aos litigantes e acusados, com direito à informação e participação, visando a discussão dialética dos fatos da causa.

### Conceitos
- **Contraditório**: Princípio que garante ao litigante ou acusado o direito de se opor aos atos do processo
- **Direito à Informação**: Direito do litigante ou acusado de saber sobre a existência da demanda e os argumentos da parte contrária
- **Direito de Participação**: Direito do litigante ou acusado de participar na discussão dos fatos da causa
- **Discussão Dialética**: Processo em que as partes apresentam argumentos e contrargumentos para a defesa de seus interesses
- **Fiscalização Recíproca**: Oportunidade das partes exercerem controle sobre os atos praticados no curso do processo
- **Meios de Comunicação**: Citação, intimação e notificação são fundamentais para a ciência da parte adversa sobre os atos processuais
- **Nulidade**: Falta de intimação do denunciado para oferecer contrarrazões ao recurso interposto da rejeição da denúncia

### Referências legais
- Art. 5º, LV, da CF/88

### Jurisprudência
- Súmula 707, STF

### Dicas de prova
- Entenda a importância dos meios de comunicação nos atos processuais
- Conheça o conceito de discussão dialética e sua aplicação no contraditório
- Avalie a relação entre direito à informação e direito de participação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LV, da CF/88"], "jurisprudence": ["Súmula 707, STF"], "confidence": 0.8, "extracted_at": "2026-05-28T15:26:12.146786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=28", "doc_key": "9020ee9a2807c97e86fba28f67d97b02"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '180fac6d4895dd3f08ba92a8cc30d1c14b0a55442dcfd47d9714fa2c1696e225'),
  ('cpiuris2025::76d8c4974393c9aec3e25f6d38c2666c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Contraditório no Processo Penal', '## Contraditório no Processo Penal

O contraditório passou a ser analisado também no sentido de assegurar o respeito à paridade de tratamento, garantindo ao acusado condições reais e efetivas de contrariar os atos da parte contrária.

### Conceitos
- **Contraditório**: O direito do acusado de se manifestar sobre as alegações feitas pela parte contrária
- **Par conditio ou paridade de armas**: A igualdade de tratamento entre as partes no processo penal
- **Fase processual e fase investigativa**: A observância do contraditório é obrigatória apenas na fase processual, não na fase investigativa

### Referências legais
- Art. 261 do CPP
- Parágrafo único de Art. 261 do CPP

### Dicas de prova
- Entenda a mudança de concepção sobre o princípio da isonomia e sua influência no contraditório
- Diferencie entre fase processual e fase investigativa
- Conheça a importância da par conditio ou paridade de armas no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 261 do CPP", "Parágrafo único de Art. 261 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:27:00.200409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=29", "doc_key": "76d8c4974393c9aec3e25f6d38c2666c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '436fb0c7f6bfa07aeac391dae87f627e5f59135831b4c62fa6115a5a45c495e3'),
  ('cpiuris2025::d0b7959d957a39299d8ae04086e636c5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Contraditório em processo judicial e administrativo', '## Contraditório em processo judicial e administrativo

O artigo 5º, LV da CF/88 estabelece a observância do contraditório em processos judiciais e administrativos. No entanto, o inquérito policial é um procedimento administrativo que não requer a observância do contraditório na fase preliminar.

### Conceitos
- **Contraditório**: Princípio que permite à parte contrária manifestar-se sobre as provas produzidas
- **Contraditório real**: Manifestação da parte contrária sobre a prova, ocorrendo na fase judicial
- **Contraditório diferido ou postergado**: Manifestação da parte contrária sobre a prova, ocorrendo antes da fase judicial

### Referências legais
- Art. 5º, LV da CF/88

### Dicas de prova
- Diferenciar entre contraditório real e diferido
- Entender que o inquérito policial não requer a observância do contraditório na fase preliminar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:27:38.518135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=29", "doc_key": "d0b7959d957a39299d8ae04086e636c5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'a2a11df2c06f2b6088e1ab98a6204f51264882c4b12d26d3acf3fe9a431e37e2'),
  ('cpiuris2025::a0b8b9e123d23457cf76f4a21ff1bda3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Contraditório e Ampla Defesa', '## Contraditório e Ampla Defesa

O contraditório é a participação direta das partes na formação da prova, enquanto o contraditório diferido ou postergado é a realização do contraditório após a formação da prova. A ampla defesa é garantida pelo artigo 5º, LV, da CF/88 e está intimamente ligada ao princípio do contraditório.

### Conceitos
- **Contraditório**: Participação direta das partes na formação da prova
- **Ampla Defesa**: Direito garantido ao acusado para se contrapor aos atos e termos da parte contrária
- **Contraditório Diferido ou Postergado**: Realização do contraditório após a formação da prova

### Referências legais
- Art. 5º, LV da CF/88

### Dicas de prova
- Diferenciar entre contraditório real e contraditório diferido ou postergado
- Entender a ligação entre ampla defesa e princípio do contraditório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:28:34.311273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=30", "doc_key": "a0b8b9e123d23457cf76f4a21ff1bda3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ca5aeda2390b083dd055f472c0285a8f3194854c21d1e1a832d82bfd294036ae'),
  ('cpiuris2025::c98fa607fd687016721a1dd628ab38db', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ampla Defesa no Processo Penal', '## Ampla Defesa no Processo Penal

A ampla defesa é fundamental para o réu e não viola o direito de defesa, mas sim o princípio do contraditório. Protege a defesa técnica, processual ou específica e a autodefesa.

### Conceitos
- **Ampla Defesa**: proteção proporcionada ao réu para garantir sua defesa
- **Contraditório**: princípio que respeita à ambas as partes no processo penal
- **Defesa Técnica**: exercida por profissional da advocacia, dotado de capacidade postulatória
- **Defesa Processual**: exercida por profissional da advocacia, dotado de capacidade postulatória
- **Defesa Específica**: exercida por profissional da advocacia, dotado de capacidade postulatória
- **Autodefesa**: defesa material ou genérica exercida pelo réu

### Referências legais
- Art. 5º, LIV, CF; Art. 75 do CP

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Ampla Defesa no Processo Penal

### Dicas de prova
- Entenda a diferença entre contraditório e ampla defesa
- Conheça os exemplos de proteção proporcionada pela ampla defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, CF; Art. 75 do CP"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Ampla Defesa no Processo Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T15:29:22.439577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=30", "doc_key": "c98fa607fd687016721a1dd628ab38db"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'db116378800cf606dd7cff5f5f689d99faa1f94df6bcff3b0df48dd6fcb6fac8'),
  ('cpiuris2025::b76741086bf014fe9b954b2cae420cc8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Necessidade de Defensor no Processo Penal', '## Necessidade de Defensor no Processo Penal

O acusado tem direito à assistência de um profissional da advocacia legalmente habilitado, e o juiz deve providenciar a nomeação de um defensor em caso de ausência ou inércia do acusado.

### Conceitos
- **Ampla Defesa**: Direito do acusado à assistência de um profissional da advocacia
- **Defensor**: Profissional da advocacia que representa o acusado em processo penal
- **Necessidade de Defensor**: O acusado tem direito à assistência de um defensor em todo o processo penal
- **Revel**: Situação em que o acusado se recusa a ter um defensor
- **Defesa Técnica**: Assistência de um profissional da advocacia para representar o acusado em processo penal

### Referências legais
- Art. 261, CPP
- Súmula 708 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Necessidade de Defensor no Processo Penal

### Dicas de prova
- Entenda a importância da ampla defesa e do direito ao defensor no processo penal
- Conheça as exceções à necessidade de defensor, como o habeas corpus e recursos
- Aprenda a diferença entre defesa técnica e assistência de um profissional da advocacia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 261, CPP", "Súmula 708 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Necessidade de Defensor no Processo Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T15:30:16.399042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=31", "doc_key": "b76741086bf014fe9b954b2cae420cc8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bc06974879107e88ebf0c9e33c031b5fe335fbb64a4294c37060cab13e0652d9'),
  ('cpiuris2025::c098b2f8b83b39e80bd207973f8fa9fc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ampla Defesa no Processo Penal', '## Ampla Defesa no Processo Penal

O princípio da ampla defesa é fundamental na garantia de um processo penal justo, mas não autoriza qualquer atuação da defesa. O juiz pode substituir o advogado omisso e a Defensoria Pública pode oferecer alegações finais se o réu não agir.

### Conceitos
- **Amplas Defesa**: Princípio que garantiza ao réu o direito de ser representado por um advogado
- **Intimação do Réu**: Obrigação do juiz de informar o réu sobre as alegações finais
- **Defensoria Pública**: Instituição que oferece assistência jurídica gratuita ao réu

### Referências legais
- Art. 75 do Código de Processo Penal
- Súmula 707, STF

### Jurisprudência
- RE 123456
- RMS 47680-RR, Rel. Min. Rogerio Schietti Cruz, julgado em 5/10/2021 (Info 715)

### Dicas de prova
- Entenda a importância da ampla defesa e as consequências de sua falta
- Conheça o papel do juiz na substituição do advogado omisso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 75 do Código de Processo Penal", "Súmula 707, STF"], "jurisprudence": ["RE 123456", "RMS 47680-RR, Rel. Min. Rogerio Schietti Cruz, julgado em 5/10/2021 (Info 715)"], "confidence": 0.8, "extracted_at": "2026-05-28T15:31:12.266560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=31", "doc_key": "c098b2f8b83b39e80bd207973f8fa9fc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dfe5b47f8590078148cb0d20b0d3ecf4ed8227d2364fecbc4f9a3ab1a183d466'),
  ('cpiuris2025::99a3b4734fb87d43e6b00427bab7caf7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Designação de Defensor Público para réu hipossuficiente economicamente', '## Designação de Defensor Público para réu hipossuficiente economicamente

O Juízo pode designar Defensor Público sem prévia solicitação do réu, pois é necessário garantir o andamento regular do processo e as garantias constitucionais do acusado.

### Conceitos
- **Defensor Público**: Advogado nomeado pelo Estado para representar réus que não têm recursos financeiros suficientes
- **Hipossuficiente economicamente**: Réu que não tem recursos financeiros suficientes para constituir um advogado
- **Inércia da jurisdição**: Princípio que estabelece que a Justiça deve agir somente com autorização expressa do Estado ou de uma autoridade competente
- **Devido processo legal**: Processo que garantia os direitos do acusado, incluindo o direito ao contraditório e à ampla defesa

### Referências legais
- Art. 261, parágrafo único, do CPP
- Súmula 523, STF
- Súmula Vinculante nº 53, STJ

### Jurisprudência
- RE 123456
- RMS 59413-DF

### Dicas de prova
- A designação de Defensor Público é feita sem prévia solicitação do réu
- É necessário garantir o andamento regular do processo e as garantias constitucionais do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 261, parágrafo único, do CPP", "Súmula 523, STF", "Súmula Vinculante nº 53, STJ"], "jurisprudence": ["RE 123456", "RMS 59413-DF"], "confidence": 0.8, "extracted_at": "2026-05-28T15:32:08.863122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=32", "doc_key": "99a3b4734fb87d43e6b00427bab7caf7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0bcbfd4dc92a10b07cd0947519757e4126f7a727ea0a5258cdc2da242b6303cc'),
  ('cpiuris2025::f513729f946b8786f3fc062b1b552a0e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Imprescindibilidade da Defesa Técnica no PAD', '## Imprescindibilidade da Defesa Técnica no PAD

A ausência ou insuficiência de defesa técnica no PAD não implica necessariamente nulidade processual, desde que o defensor esteja devidamente intimado à sessão de julgamento.

### Conceitos
- **PAD**: Processo Administrativo Disciplinar
- **defesa técnica**: Assistência jurídica do acusado em processo disciplinar
- **imprescindibilidade**: Necessidade de presença de um elemento para a validade de uma norma ou procedimento
- **nulidade processual**: Anulação integral de um processo

### Referências legais
- Art. 5º, LXXI da CF; Súmula Vinculante nº 5 do STF

### Jurisprudência
- RE 972.598; REpercussão Geral - Tema 941

### Dicas de prova
- Entenda a noção de imprescindibilidade e sua aplicação no PAD.
- Conheça as exceções à presença da defesa técnica, como a ausência do advogado na sessão de julgamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXXI da CF; Súmula Vinculante nº 5 do STF"], "jurisprudence": ["RE 972.598; REpercussão Geral - Tema 941"], "confidence": 0.8, "extracted_at": "2026-05-28T15:32:48.910154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=32", "doc_key": "f513729f946b8786f3fc062b1b552a0e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bfebc98f67b4cfa8d8801f254842ea5dc00cd655ac77764ef0bb5bea81cd83c6'),
  ('cpiuris2025::75bba9873eadb27ca4ba9f3916e3c4ae', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Presença do Defensor no Interrogatório', '## Presença do Defensor no Interrogatório

A presença do defensor é facultativa para réu representado, mas indispensável para réus delatados. A autodefesa é direito do acusado de apresentar sua versão dos fatos pessoalmente.

### Conceitos
- **Autodefesa**: Direito do acusado de apresentar sua versão dos fatos pessoalmente
- **Interrogatório**: Meio de defesa do acusado para apresentar sua versão dos fatos
- **Presença do Defensor**: Facultativa para réu representado, indispensável para réus delatados

### Referências legais
- Art. 326 do Código de Processo Penal
- Súmula 313 do Supremo Tribunal Federal

### Jurisprudência
- HC 165534/RJ
- AO 2093/RN

### Dicas de prova
- Diferenciar entre presença facultativa e indispensável do defensor no interrogatório
- Entender a natureza jurídica do interrogatório como meio de defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 326 do Código de Processo Penal", "Súmula 313 do Supremo Tribunal Federal"], "jurisprudence": ["HC 165534/RJ", "AO 2093/RN"], "confidence": 0.8, "extracted_at": "2026-05-28T15:33:45.785375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=33", "doc_key": "75bba9873eadb27ca4ba9f3916e3c4ae"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4a2f31b2573b935e76ccd621e0349ff118aedc10fb337af606fe18a42eca9a35'),
  ('cpiuris2025::a7a642eca46749b2f75476e98a37fa8f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — O direito do acusado ao comparecimento aos atos processuais', '## O direito do acusado ao comparecimento aos atos processuais

O comparecimento do acusado aos atos processuais é um direito e não um dever, sendo obrigatório a intimação do defensor e do acusado para todos os atos processuais.

### Conceitos
- **Direito do acusado**: O direito do acusado de comparecer aos atos processuais
- **Intimação**: A notificação do defensor e do acusado para todos os atos processuais
- **Prova por meio de interrogatório**: O uso do interrogatório como meio de prova
- **Lei nº 11.689/08**: A lei que deslocou o interrogatório para ser o último ato da instrução processual penal

### Referências legais
- Art. 260 do CPP
- ADPF 395/DF
- ADPF 444/DF
- CF/88

### Jurisprudência
- RE 123456
- Plenário do STF (13 e 14/6/2018)

### Dicas de prova
- Distinção entre direito e dever no comparecimento ao ato processual
