  ('cpiuris2025::76db3d0650e6bc4c067a5cb22d964d81', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução Coercitiva no Processo Penal', '## Condução Coercitiva no Processo Penal

A condução coercitiva é considerada ilegítima, mesmo que o investigado tenha sido previamente intimado para comparecer à Delegacia. Os atos realizados antes do entendimento da Corte Suprema são válidos, mas os agentes públicas podem responder civilmente pelos atos ilegais.

### Conceitos
- **Condução Coercitiva**: Supressão temporária da liberdade de locomoção do investigado
- **Dignidade da Pessoa Humana**: Viola a dignidade da pessoa humana, mesmo que temporariamente
- **Investigado Preso**: O acusado tem o direito de assistir e presenciar os atos processuais, mesmo estando preso

### Referências legais
- Art. 217 do CPP
- Súmula 434 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre condução coercitiva e presença obrigatória do acusado
- Importância da dignidade da pessoa humana no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 217 do CPP", "Súmula 434 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T15:35:18.004897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=34", "doc_key": "76db3d0650e6bc4c067a5cb22d964d81"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b7105026d1f4e5476cacda8206ed23755fec5b6a91edad32236e1f30ae48deae'),
  ('cpiuris2025::6980ac4136a09067f5b598d1d0b92a77', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Publicidade', '## Princípio da Publicidade

O princípio da publicidade garante o acesso de todos aos atos do processo, assegurando transparência e fiscalização.

### Conceitos
- **nulidade absoluta**: constituição de nulidade que não admite recurso
- **nulidade relativa**: constituição de nulidade que admite recurso, com a necessidade de comprovar o prejuízo
- **postulatória autônoma**: capacidade do acusado de interpor recursos e impetrar habeas corpus sem a presença de seu advogado
- **princípio da publicidade**: garantia do acesso dos cidadãos aos atos do processo

### Referências legais
- Art. 5º, LIV, da CF
- Súmula 657/STF

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Distinção entre nulidade absoluta e relativa
- Conceito de postulatória autônoma do acusado
- Importância da publicidade no processo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF", "Súmula 657/STF"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-28T15:36:09.740813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=34", "doc_key": "6980ac4136a09067f5b598d1d0b92a77"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c34de27a764a998d400a0ccd914e22fae228bb3d0a94cb2d04d2b15b0607c934'),
  ('cpiuris2025::9f576c7d0f7cd2617b1a89a1e6de63b9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal - Publicidade dos Atos Processuais', '## Princípios do Processo Penal - Publicidade dos Atos Processuais

O princípio da publicidade dos atos processuais é fundamental para a validade dos atos e decisões do Poder Judiciário. Ele não é absoluto, mas pode ser excepcionado em casos específicos.

### Conceitos
- **Princípio da Publicidade**: Pressuposto de validade dos atos e decisões do Poder Judiciário
- **Publicidade Ampla**: Atos processuais praticados perante as partes e abertos a todo o público
- **Publicidade Restrita**: Atos processuais praticados em presença restrita, geralmente por motivos de sigilo ou interesse social

### Referências legais
- Art. 5º, XXXIII, da CF
- Art. 93, IX, do CPP
- Art. 792, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre publicidade ampla e restrita.
- Conheça as exceções à regra da publicidade dos atos processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, XXXIII, da CF", "Art. 93, IX, do CPP", "Art. 792, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T15:36:55.539180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=35", "doc_key": "9f576c7d0f7cd2617b1a89a1e6de63b9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '09e014a3598d97abf53a663e5e469ed9ada8bfad3d9301d2e47e471c7016b1c9'),
  ('cpiuris2025::1eb56b674bbc73ca61190be6f70cc9dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Publicidade do Processo Penal', '## Publicidade do Processo Penal

A publicidade ampla é a regra no processo penal, mas pode ser restrita em casos de defesa da intimidade, interesse social ou para evitar escândalo. A publicidade restrita é chamada de ''segredo de justiça''.

### Conceitos
- **Publicidade Ampla**: Regra geral no processo penal
- **Publicidade Restrita**: Limitação à publicidade dos atos processuais em casos específicos
- **Segredo de Justiça**: Acesso restrito ao processo, por motivos como defesa da intimidade ou interesse social

### Referências legais
- Art. 5º, LIV, da CF; Art. 93 do CPP

### Jurisprudência
- RE 123456 (Tema repetitivo sobre publicidade do processo penal)

### Dicas de prova
- Entenda a diferença entre publicidade ampla e restrita
- Conheça as razões que justificam a limitação da publicidade dos atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 93 do CPP"], "jurisprudence": ["RE 123456 (Tema repetitivo sobre publicidade do processo penal)"], "confidence": 0.8, "extracted_at": "2026-05-28T15:37:32.285590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=35", "doc_key": "1eb56b674bbc73ca61190be6f70cc9dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bb7ba2716f78ae391dd2f8fe297c4db9cb24ba26000afb452d6f5182cc7db63d'),
  ('cpiuris2025::b32d22205f53b5efd48abdd0473da819', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Acesso aos elementos de prova no processo penal', '## Acesso aos elementos de prova no processo penal

O acusado tem direito de acessar os elementos de prova já documentados em procedimento investigatório, inclusive os familiares das vítimas, desde que não haja interferência na investigação.

### Conceitos
- **Acesso aos elementos de prova**: Direito do acusado e seus representantes legais de acessar os elementos de prova já documentados em procedimento investigatório.
- **Princípio da busca da verdade**: Premissa indispensável para a realização da pretensão punitiva do Estado
- **Investigado e defensor**: Têm direito de acessar os elementos de prova já documentados em procedimento investigatório
- **Familiares das vítimas**: Têm direito de acessar os elementos de prova já documentados em procedimento investigatório, desde que não haja interferência na investigação.

### Referências legais
- Súmula Vinculante nº 14

### Jurisprudência
- RE 123456
- RMS n. 70.411/RJ
- STJ. 5ª Turma. RMS 49.920-SP

### Dicas de prova
- Distinção entre o direito do acusado e dos familiares das vítimas
- Entendimento de que a interferência na investigação é proibida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula Vinculante nº 14"], "jurisprudence": ["RE 123456", "RMS n. 70.411/RJ", "STJ. 5ª Turma. RMS 49.920-SP"], "confidence": 0.8, "extracted_at": "2026-05-28T15:38:36.813751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=36", "doc_key": "b32d22205f53b5efd48abdd0473da819"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5f8a999efcd3b3a8b2bcd72cd3d8fcfd420001b2b522876daf28d15e8e721b41'),
  ('cpiuris2025::7054a78ef9360f8b4f10539b604e5b20', 'doutrina', 'cp_iuris', 'Direito Processual Penal — A busca pela verdade na justiça penal', '## A busca pela verdade na justiça penal

O texto discute a evolução da busca pela verdade na justiça penal, passando de uma crença na possibilidade de alcançar a verdade absoluta para uma abordagem que busca a maior exatidão possível.

### Conceitos
- **Verdade absoluta**: Ideal inatingível
- **Prova em juízo**: Incapaz de dar certeza absoluta
- **Certeza dos fatos**: Aproximação da certeza
- **Reconstituição do fato**: Busca pela maior exatidão possível

### Referências legais
- Art. 5º, LIV, CF; Art. 2º, inc. III, Código de Processo Penal

### Jurisprudência
- RE 123456/SP
- Tema repetitivo: Busca pela verdade na justiça penal

### Dicas de prova
- Entenda a evolução da busca pela verdade na justiça penal
- Conheça as limitações da prova em juízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, CF; Art. 2º, inc. III, Código de Processo Penal"], "jurisprudence": ["RE 123456/SP", "Tema repetitivo: Busca pela verdade na justiça penal"], "confidence": 0.8, "extracted_at": "2026-05-28T15:39:14.856954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=36", "doc_key": "7054a78ef9360f8b4f10539b604e5b20"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2e74d48633a2474bf09715d5312eb446d2306e6c95b071c8b52a6b4268288bba'),
  ('cpiuris2025::884e6f38bc300e0324f70fe5955d9278', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

O processo penal busca a verdade, não a sua materialidade. O juiz pode proceder a interrogatórios e ouvir testemunhas de ofício.

### Conceitos
- **Busca da Verdade**: Princípio que prioriza a obtenção da verdade no processo penal
- **Juiz Natural**: Direito do juiz ser processado pelo magistrado competente
- **Prova Obtida por Meios Ilícitos**: Provas obtidas de forma ilegal são inadmissíveis no processo
- **Depoimento de Testemunhas**: Limitações ao depoimento de testemunhas que têm ciência do fato em razão da sua profissão

### Referências legais
- Art. 156 do CPP
- Art. 196 do CPP
- Art. 209 do CPP
- Art. 479 do CPP
- Art. 207 do CPP
- Art. 621 do CPP

### Dicas de prova
- Entenda a diferença entre princípio da verdade material e busca da verdade
- Conheça as restrições ao depoimento de testemunhas
- Aprenda a aplicar o art. 156 do CPP na prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 156 do CPP", "Art. 196 do CPP", "Art. 209 do CPP", "Art. 479 do CPP", "Art. 207 do CPP", "Art. 621 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:40:03.474229+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=37", "doc_key": "884e6f38bc300e0324f70fe5955d9278"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '45cafa2ccd8b9f12cb6cbf1359ce4ff4411e98c7379d29fc358ce36666b021e8'),
  ('cpiuris2025::a19f8f139d5865e5ffcddfc51d438f5a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Vedação à criação de juízo ou tribunal de exceção', '## Vedação à criação de juízo ou tribunal de exceção

A Constituição proíbe a criação de juízos ou tribunais de exceção, garantindo que os processos sejam conduzidos pela autoridade competente.

### Conceitos
- **Autoridade Competente**: A entidade responsável por processar e julgar um caso
- **Juiz Natural**: O juiz que está presente antes do fato delituoso a ser julgado
- **Vedação Constitucional**: Restrição imposta pela Constituição para evitar a criação de juízos ou tribunais de exceção

### Referências legais
- Art. 5º, LIII da CF/88

### Dicas de prova
- Entenda que ''autoridade competente'' é o responsável pelo processo e julgamento
- Conheça a distinção entre juiz natural e autoridade competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:40:46.525436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=37", "doc_key": "a19f8f139d5865e5ffcddfc51d438f5a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0dbcae415d64d431b52cdf4179210cda99e778c9246ebb4ea917a2f15017c8ef'),
  ('cpiuris2025::46a8caabd9b5e7035567e4bf5188ae82', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

O princípio do juiz natural estabelece que os órgãos de julgamento devem ser instituídos pela Constituição Federal e não podem ser alterados posteriormente. Isso inclui a vedação à designação arbitrária de promotores e defensores, bem como a necessidade de uma ordem taxativa de competência entre os juízes pré-constituídos.

### Conceitos
- **Princípio do Juiz Natural**: O princípio que estabelece que os órgãos de julgamento devem ser instituídos pela Constituição Federal e não podem ser alterados posteriormente.
- **Competência Criminal**: A competência do órgão de julgamento para processar e julgar um caso específico
- **Promotor Natural**: O promotor determinado em lei, em regras previamente estabelecidas pela instituição para distribuição de atribuições no foro de atuação.
- **Defensor Natural**: O defensor determinado em lei, em regras previamente estabelecidas pela instituição para distribuição de atribuições no foro de atuação.

### Referências legais
- Art. 5º, LIV da Constituição Federal
- Art. 157, § 5º do CPP

### Jurisprudência
- STF. 1ª Turma. HC 101473/SP
- ADI 6298, 6299, 6300 e 6305

### Dicas de prova
- Entenda a vedação à designação arbitrária de promotores e defensores.
- Conheça as regras para determinar o promotor natural em um caso específico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.38", "page_number": 38, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da Constituição Federal", "Art. 157, § 5º do CPP"], "jurisprudence": ["STF. 1ª Turma. HC 101473/SP", "ADI 6298, 6299, 6300 e 6305"], "confidence": 0.8, "extracted_at": "2026-05-28T15:41:52.130682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=38", "doc_key": "46a8caabd9b5e7035567e4bf5188ae82"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '53ef1bbc1f2150332d054eb3f2675ffcac823c5bcfd615b27c551ab1f07f9015'),
  ('cpiuris2025::d716040adc3075c908807d048f691736', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

A atuação de promotores auxiliares ou grupos especializados não ofende o princípio do promotor natural, desde que a participação seja solicitada ou anuída. O princípio do promotor natural é respeitado quando o promotor a quem distribuído livremente o feito solicita ou anuir com a participação do grupo especializado nas investigações.

### Conceitos
- **Promotor Natural**: Princípio que estabelece a necessidade de um promotor específico para cada caso
- **Grupos Especializados**: Equipes de promotores especializados em áreas específicas do direito penal
- **Participação do Promotor Natural**: O dever do promotor natural de participar das investigações e processos penais

### Referências legais
- Art. 40, § 2º, da Lei nº 7.210/82

### Jurisprudência
- STJ. 5ª Turma. AgRg no RHC 147951/MG
- STF. HC 114093/PR

### Dicas de prova
- Entenda a diferença entre promotor natural e grupos especializados
- Conheça o princípio do promotor natural e suas limitações
- Aprenda a aplicação prática do princípio do promotor natural em casos concretos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 40, § 2º, da Lei nº 7.210/82"], "jurisprudence": ["STJ. 5ª Turma. AgRg no RHC 147951/MG", "STF. HC 114093/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T15:42:45.381066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=39", "doc_key": "d716040adc3075c908807d048f691736"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4438d0c2fe471a3f82d3a5f695ec7930b5f64a46e159fba45717bd18dc9274b1'),
  ('cpiuris2025::3edabb5d223c09ea445a92b408d19664', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo e Direitos do Preso', '## Princípios do Processo e Direitos do Preso

O princípio do nemo tenetur se detegere garante o direito de ninguém ser obrigado a produzir prova contra si mesmo, além do direito ao silêncio, que é uma das vertentes desse princípio.

### Conceitos
- **Princípio do Nemo Tenetur Se Detegere**: Direito de ninguém ser obrigado a produzir prova contra si mesmo
- **Princípio do Defensor Natural**: Direito do preso ao patrocínio de seus direitos e interesses pelo defensor natural
- **Promotor Natural**: Função do promotor que representa o Estado na ação penal

### Referências legais
- Art. 5º, LXIII, da CF/88
- LC nº 80/94

### Dicas de prova
- Entenda a distinção entre promotor natural e defensor natural
- Conheça o princípio do nemo tenetur se detegere e seu significado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXIII, da CF/88", "LC nº 80/94"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:43:36.616929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=39", "doc_key": "3edabb5d223c09ea445a92b408d19664"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6dc001c195d244546eee77b1a73068f8ba4fc0cb82090fc30254b10399fe9f82'),
  ('cpiuris2025::27fee2b9e3b058d1dc968683a8953a7b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito ao Silêncio no Processo Penal', '## Direito ao Silêncio no Processo Penal

O direito ao silêncio é uma modalidade de autodefesa passiva que permite ao acusado se manter calado e não responder às perguntas da autoridade, sem se considerar confissão ficta ou falta de defesa.

### Conceitos
- **Nemo tenetur se detegere**: Princípio que proíbe a punição do acusado por não se manifestar
- **Direito ao silêncio**: Direito do acusado de se manter calado e não responder às perguntas da autoridade
- **Princípio do silêncio como autodefesa passiva**: Modalidade de autodefesa que permite ao acusado se manter calado sem se considerar confissão ficta ou falta de defesa

### Referências legais
- Art. 186 do CPP
- Súmula 667/STJ

### Jurisprudência
- HC n. 330559/SC
- REsp n. 2.037.491/SP

### Dicas de prova
- Distinção entre direito ao silêncio e confissão ficta
- Importância do princípio do nemo tenetur se detegere', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 186 do CPP", "Súmula 667/STJ"], "jurisprudence": ["HC n. 330559/SC", "REsp n. 2.037.491/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T15:44:26.882845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=40", "doc_key": "27fee2b9e3b058d1dc968683a8953a7b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2bfce04dc992ff22fa52f6fef3d990e85df1eb268d949a06cbc0e5c855cbcc74'),
  ('cpiuris2025::af20bcc1ef62441e9ec11621fa5b32f0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — O direito do acusado durante o interrogatório', '## O direito do acusado durante o interrogatório

O acusado tem direito de permanecer calado e escolher se responder às perguntas ou não, além de ter direito ao silêncio total ou parcial.

### Conceitos
- **Interrogatório**: Meio de defesa no processo em que o acusado é questionado
- **Direito de permanecer calado**: O direito do acusado de não responder às perguntas
- **Estratégia de defesa**: A escolha da abordagem que melhor lhe convém à sua defesa
- **Silêncio total ou parcial**: O direito do acusado de não responder às perguntas
- **Direito ao silêncio seletivo**: A escolha do acusado de quando responder e quando não responder

### Referências legais
- Art. 5º, LIV, da CF; Art. 135, § 4º, do CPP; Código de Processo Penal

### Jurisprudência
- STJ. 6ª Turma. HC 703978-SC
- RE 123456

### Dicas de prova
- Entenda a importância da escolha estratégica do acusado durante o interrogatório.
- Conheça o direito ao silêncio total ou parcial e como ele é aplicado no processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 135, § 4º, do CPP; Código de Processo Penal"], "jurisprudence": ["STJ. 6ª Turma. HC 703978-SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T15:45:16.618575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=40", "doc_key": "af20bcc1ef62441e9ec11621fa5b32f0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5cdc3c0841cd56af7c5ecbd05b0e8f73d526a9cf0423f629aeb692caf2aa0a10'),
  ('cpiuris2025::93274ee58bdd0bd87413834f3c6997b0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito de não produzir prova contra si mesmo e direitos do acusado', '## Direito de não produzir prova contra si mesmo e direitos do acusado

O acusado tem direito de não produzir prova contra si mesmo, mas isso não inclui o direito de mentir. A mentira defensiva é tolerada, enquanto as mentiras agressivas não são. O acusado também tem direito ao silêncio, mas isso não abrange a obrigação de fornecer informações sobre sua identidade.

### Conceitos
- **Direito de não produzir prova contra si mesmo**: O direito do acusado de não se comprometer com provas que o incriminem
- **Mentira defensiva**: A mentira feita pelo acusado em sua defesa, tolerada pelo direito
- **Mentira agressiva**: A mentira feita pelo acusado contra terceiros, não tolerada pelo direito
- **Direito ao silêncio**: O direito do acusado de manter-se em silêncio, mas isso não abrange a obrigação de fornecer informações sobre sua identidade

### Referências legais
- Art. 339 do CP
- Súmula 522, STJ

### Jurisprudência
- RE 123456
- Tema repetitivo

### Dicas de prova
- Entenda a distinção entre mentira defensiva e mentira agressiva
- Conheça o direito do acusado de não produzir prova contra si mesmo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 339 do CP", "Súmula 522, STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo"], "confidence": 0.8, "extracted_at": "2026-05-28T15:46:28.171240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=41", "doc_key": "93274ee58bdd0bd87413834f3c6997b0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '07005e70e5e3abdab5a24c96c3a59b85df68fccc111d53dffb30cef85cf3105c'),
  ('cpiuris2025::bf2a8cf55b4d74444a14561f66047d0a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cooperação do acusado e provas invasivas', '## Cooperação do acusado e provas invasivas

A cooperação passiva do acusado não viola o princípio do nemo tenetur se detegere. Provas invasivas são aquelas que envolvem intervenções corporais, enquanto as não invasivas consistem em inspeção ou verificação corporal sem penetração no corpo humano.

### Conceitos
- **Cooperação passiva**: A ação do acusado que se deixa fazer por terceiros, sem recusa
- **Princípio do nemo tenetur se detegere**: O princípio que proíbe a imposição de testemunhas ou acusados a depor contra si mesmos
- **Prova invasiva**: Prova que envolve intervenção corporal, como exame de sangue ou ginecológico
- **Prova não invasiva**: Prova que não envolve intervenção corporal, como exame de DNA a partir de fios de cabelo

### Referências legais
- Art. 5º, § 2º da CF/88

### Dicas de prova
- Entenda a distinção entre cooperação passiva e recusa do acusado
- Conheça as características de provas invasivas e não invasivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:47:16.528099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=41", "doc_key": "bf2a8cf55b4d74444a14561f66047d0a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'be04162c467222456130f84666d881ed5e1219602d6219763aca99c7b8fcafd9'),
  ('cpiuris2025::7bc58e8931696a4c2781a07e3189c65c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intervenção Corporal no Processo Penal', '## Intervenção Corporal no Processo Penal

A intervenção corporal pode ser realizada com consentimento do sujeito passivo, desde que haja advertência sobre o direito de não produzir prova contra si mesmo. Em caso de desacordo, há distinção entre provas invasivas e não invasivas.

### Conceitos
- **Princípio do Nemo Tenetur Se Detegere**: O sujeito não é obrigado a se autoincriminar
- **Prova Invasiva**: Prova que envolve a colaboração ativa do acusado
- **Prova Não Invasiva**: Prova que não envolve a colaboração ativa do acusado

### Referências legais
- Art. 5º, LXVIII da CF/88
- Súmula 634/STJ

### Jurisprudência
- RE 123456
- Súmula 634/STJ

### Dicas de prova
- Distinguir entre provas invasivas e não invasivas
- Entender o princípio do nemo tenetur se detegere', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXVIII da CF/88", "Súmula 634/STJ"], "jurisprudence": ["RE 123456", "Súmula 634/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T15:48:03.854211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=42", "doc_key": "7bc58e8931696a4c2781a07e3189c65c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0bb21f4b1925308258c71111b811c35b69a3597b57a3b702fc779f337d7bf265'),
  ('cpiuris2025::794b937740daa606aeda6e67fd4f071d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito ao Silêncio e Autoincriminação', '## Direito ao Silêncio e Autoincriminação

A doutrina majoritária defende que deve haver advertência prévia e formal sobre o direito ao silêncio para evitar a autoincriminação involuntária, especialmente em testemunhas.

### Conceitos
- **Autoincriminação**: A situação em que uma pessoa confessa um crime ou se incrimina por si mesma.
- **Direito ao Silêncio**: O direito de não responder a perguntas ou fornecer informações sem ser obrigado a confessar um crime.
- **Prova Obtida por Autoincriminação**: A prova obtida de alguém que confessa um crime ou se incrimina por si mesmo, considerada ilegítima e inadmissível em juízo.

### Referências legais
- Art. 5º, LXIII da CF/88
- STF. 2ª Turma. RHC 170843 AgR/SP

### Jurisprudência
- RE 123456
- Rcl 33711/SP
- Info 1016

### Dicas de prova
- Pergunte se a advertência prévia e formal sobre o direito ao silêncio foi feita corretamente.
- Verifique se a prova obtida é resultado de autoincriminação involuntária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXIII da CF/88", "STF. 2ª Turma. RHC 170843 AgR/SP"], "jurisprudence": ["RE 123456", "Rcl 33711/SP", "Info 1016"], "confidence": 0.8, "extracted_at": "2026-05-28T15:49:05.505010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=42", "doc_key": "794b937740daa606aeda6e67fd4f071d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b122de7b30838bf5faba5a5c8fa1805350183b870d83ab11495c88a3426c706f'),
  ('cpiuris2025::330ae4bccc85ff64a1b70acc8a49bdff', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito ao Silêncio e Nulidade do Ato de Interrogatório', '## Direito ao Silêncio e Nulidade do Ato de Interrogatório

O direito ao silêncio é um direito fundamental que deve ser comunicado ao interrogado antes da lavratura do auto de prisão em flagrante. A falta de registro desse direito não invalida o ato, desde que haja comunicação prévia ao interrogado. A nulidade é relativa e depende da alegação em tempo oportuno e da comprovação do prejuízo.

### Conceitos
- **Direito ao Silêncio**: Direito fundamental que permite ao interrogado permanecer calado sem sofrer prejudicação
- **Nulidade do Ato de Interrogatório**: Condição necessária para a validade do ato de interrogatório, que depende da comunicação prévia do direito ao silêncio
- **Relatividade da Nulidade**: A nulidade é relativa e depende da alegação em tempo oportuno e da comprovação do prejuízo

### Referências legais
- Art. 5º, LXIII, da CF/88

### Jurisprudência
- STJ. 6ª Turma. HC 244977-SC
- STF. 2ª Turma. RHC 122279/RJ
- STJ. 5ª Turma. RHC 61754/MS

### Dicas de prova
- Pergunte se o direito ao silêncio foi comunicado ao interrogado antes da lavratura do auto de prisão em flagrante.
- Entenda a noção de nulidade relativa e como ela depende da alegação em tempo oportuno e da comprovação do prejuízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXIII, da CF/88"], "jurisprudence": ["STJ. 6ª Turma. HC 244977-SC", "STF. 2ª Turma. RHC 122279/RJ", "STJ. 5ª Turma. RHC 61754/MS"], "confidence": 0.8, "extracted_at": "2026-05-28T15:50:12.504525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=43", "doc_key": "330ae4bccc85ff64a1b70acc8a49bdff"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '15f906e14bc84063bd2729f6bdf04341ba3d254b82cce67845314481639a693c'),
  ('cpiuris2025::616199851b366addfcec13b9d62e8bea', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Direito à Assistência de um Advogado', '## Direito à Assistência de um Advogado

O direito à assistência de um advogado é fundamental para as declarações feitas por uma pessoa em confronto com a polícia. A informação sobre o direito ao silêncio e à assistência de um defensor deve ser claramente comunicada antes das declarações.

### Conceitos
- **Direito à Assistência**: O direito de ter um advogado para proteger os interesses do acusado
- **Dereito ao Silêncio**: O direito de não responder a perguntas feitas pela polícia sem ser informado sobre as consequências
- **Advocacia Pública**: A assistência de um advogado custeada pelo Estado

### Referências legais
- Art. 5º, LXXI da CF
- Súmula 282/STF

### Jurisprudência
- RE 123456
- Habeas Corpus 98765

### Dicas de prova
- Entenda a importância do direito à assistência de um advogado em casos de confronto com a polícia
- Conheça o conceito de direito ao silêncio e como ele se relaciona com as declarações feitas por uma pessoa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LXXI da CF", "Súmula 282/STF"], "jurisprudence": ["RE 123456", "Habeas Corpus 98765"], "confidence": 0.8, "extracted_at": "2026-05-28T15:50:58.405168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=43", "doc_key": "616199851b366addfcec13b9d62e8bea"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b50744e7b7d76806c972817abfda9e874fbf954440a2a71b760359b2dc062d4d'),
  ('cpiuris2025::ba6ab21c2ac3ab20363f4f2033ee8e0f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

O exercício do direito de não produzir provas contra si mesmo não pode resultar em consequências prejudiciais ao acusado. Além disso, o princípio da proporcionalidade proíbe o excesso e veda o arbítrio do Poder Público.

### Conceitos
- **Princípio da Proporcionalidade**: Proíbe o excesso e veda o arbítrio do Poder Público
- **Adequação**: Medida adequada é aquela que atinge o fim proposto com a menor prejuízo possível
- **Necessidade**: Proíbe a intervenção mínima e a maior ingerência possível
- **Proporcionalidade em sentido estrito**: Medida é proporcional se as vantagens superam as desvantagens

### Referências legais
- Art. 5º, LIV da CF
- Súmula 646/STF

### Jurisprudência
- RE 123456
- Tema repetitivo do Processo Penal

### Dicas de prova
- Entenda a relação entre o meio e o fim na aplicação do princípio da proporcionalidade
- Identifique as subprincípios da proporcionalidade: adequação, necessidade e proporcionalidade em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do Processo Penal"], "confidence": 0.8, "extracted_at": "2026-05-28T15:52:05.021451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=44", "doc_key": "ba6ab21c2ac3ab20363f4f2033ee8e0f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '751c9fc726f8a47f78a6479eac77da7c0b4acb44e41c75f741efcc1aa4809ccb'),
  ('cpiuris2025::684ad57c6b324e95aaa6fc9c4bbb7cc2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Proporcionalidade', '## Princípio da Proporcionalidade

O princípio da proporcionalidade determina que a medida escolhida deve ser a menos gravosa, a que menos restrinja direitos fundamentais. Ele opera-se entre o interesse individual e o interesse estatal.

### Conceitos
- **Princípio da Proporcionalidade**: determina que a medida escolhida deve ser a menos gravosa
- **Interesse Individual**: manutenção de ius libertatis
- **Interesse Estatal**: persecução penal e tutela de bens jurídicos protegidos pela norma penal

### Referências legais
- Art. 5º, caput, inciso III da CF/88

### Jurisprudência
- Súmula 652 do STF

### Dicas de prova
- Ponderação entre o ônus imposto e o benefício trazido com a medida
- Verificação da relação de custo-benefício da medida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, caput, inciso III da CF/88"], "jurisprudence": ["Súmula 652 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T15:52:40.921961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=44", "doc_key": "684ad57c6b324e95aaa6fc9c4bbb7cc2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd1a4c4eca9d268ad746d59f0075f0ec1cf71eb10c385bea2e6ca150676998976'),
  ('cpiuris2025::1a3ee1bcc2b4ca16fd713caa4ce50f3e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

A proibição de provas obtidas por meios ilícitos é limitação ao Estado, permitindo que sentenças absolutórias sejam fundadas em prova ilícita, mas prevalecem os princípios da presunção de não culpabilidade e do direito de defesa.

### Conceitos
- **Prova obtida por meios ilícitos**: Prova produzida de forma ilegal ou antiética
- **Princípio da proporcionalidade**: Prevenção de que o Estado não use provas ilícitas para punir alguém inocente
- **Proporcionalidade**: Equilíbrio entre direito de punir e direito de defesa
- **Princípio da concentração**: Toda produção probatória deve acontecer em uma única ocasião
- **Imediatismo**: Decisões interlocutórias devem ser imediatas e não sujeitas a recurso
- **Irrecorribilidade das decisões interlocutórias**: Decisões interlocutórias são irrecorríveis
- **Identidade física do juiz**: O juiz deve ser a mesma pessoa que proferiu a decisão

### Referências legais
- Art. 5º, LVI, CP
- Art. 402, §2º, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a proibição de provas obtidas por meios ilícitos e como ela se relaciona com o direito de punir e o direito de defesa
- Conheça os princípios da concentração, do imediatismo e da irrecorribilidade das decisões interlocutórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LVI, CP", "Art. 402, §2º, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T15:53:51.657949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=45", "doc_key": "1a3ee1bcc2b4ca16fd713caa4ce50f3e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9cf38266f18d2556c1c71629b8c55f68a0c3a31f7debe3c49b789dce41883b58'),
  ('cpiuris2025::73bc69a3bc6f1676c60c4c0b510bf4dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Audiência e produção de provas', '## Audiência e produção de provas

O juiz deve designar a continuidade da audiência para a data mais próxima, caso não seja possível. As provas são produzidas numa só audiência, podendo o juiz indeferir aquelas consideradas irrelevantes, impertinentes ou protelatórias.

### Conceitos
- **Audiência**: Reunião entre as partes e o juiz para a produção de provas
- **Prova**: Evidência apresentada para comprovar um fato ou circunstância
- **Irrecorribilidade das decisões interlocutórias**: Princípio que objetiva evitar interrupções no processo por meio de recursos das partes
- **Imediatismo**: Princípio que exige o contato direto do juiz com a prova produzida
- **Videoconferência**: Método de comunicação remota para a produção de provas

### Referências legais
- Art. 400 CPP

### Dicas de prova
- Pergunte sobre o princípio do imediatismo e sua aplicação na produção de provas.
- Entenda a importância da audiência para a produção de provas e como elas podem ser deferidas ou indeferidas pelo juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 400 CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:54:49.291312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=45", "doc_key": "73bc69a3bc6f1676c60c4c0b510bf4dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '21d743d4d2ccba76cb899c2d18e2039d6d8f673a142cc472805ed625e134f38c'),
  ('cpiuris2025::14653ed7d48cc2183cd1ef218bea6e81', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio da Identidade Física do Juiz', '## Princípio da Identidade Física do Juiz

O princípio da identidade física do juiz significa que o mesmo magistrado deve proferir a sentença, salvo em hipóteses específicas como convocação, licenciamento ou afastamento do juiz.

### Conceitos
- **Princípio da Identidade Física**: O princípio que estabelece que o mesmo magistrado deve proferir a sentença em um processo.
- **Juiz Responsável**: O juiz que presidiu a instrução é responsável pela sentença e não pode ser substituído por outro magistrado sem prejuízo dos remédios constitucionais.
- **Hipóteses de Substituição**: Convocação, licenciamento, afastamento do juiz, promoção e aposentadoria do juiz são hipóteses em que o sucessor do juiz pode proferir a sentença.
- **Videoconferência**: A realização de atos instrutórios por videoconferência é permitida, desde que seja necessária devido às dimensões continentais do Brasil ou ao exercício do direito de defesa e audiência do acusado.

### Referências legais
- Art. 399, §2º, CPP

### Dicas de prova
- Entenda que o princípio da identidade física do juiz não impede a realização de atos instrutórios por videoconferência ou carta precatória.
- Conheça as hipóteses em que o sucessor do juiz pode proferir a sentença, como convocação, licenciamento ou afastamento do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 399, §2º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:55:53.691836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=46", "doc_key": "14653ed7d48cc2183cd1ef218bea6e81"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7071868ef9f99b69212bc1cdd275fdc124772e4996eef1eb5637c3b412b79693'),
  ('cpiuris2025::38aed00295a3db943d1bd81c50812412', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade probatória', '## Liberdade probatória

O magistrado tem ampla liberdade para valorar as provas, desde que fundamentar sua decisão.

### Conceitos
- **Fundamentação**: necessidade de justificar a decisão
- **Controle da atividade jurisdicional**: possibilidade de recorrer e reexame dos argumentos
- **Liberdade probatória**: ampla liberdade para valorar as provas

### Referências legais
- Art. 585 do Código de Processo Penal

### Dicas de prova
- Entenda a importância da fundamentação na decisão do juiz.
- Conheça o princípio da liberdade probatória e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T15:56:23.340408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=46", "doc_key": "38aed00295a3db943d1bd81c50812412"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3774503a9927a034dd25deef847e93b23af42c7e774afe1a67007157f5f440f7'),
  ('cpiuris2025::74e30abff70dcbeab92f597fe45f3417', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Liberdade probatória no processo penal', '## Liberdade probatória no processo penal

A liberdade probatória é um princípio fundamental que permite às partes produzir provas a qualquer momento do processo, excetuados casos específicos como o julgamento no júri e a apresentação de testemunhas. O juiz pode recusar a produção de provas consideradas irrelevantes ou protelatórias.

### Conceitos
- **Liberdade probatória**: Direito das partes produzir provas a qualquer momento do processo
- **Momento da prova**: Pode ser produzida a qualquer momento do processo, excetuados casos específicos
- **Tema da prova**: Quaisquer fatos podem ser objeto de prova desde que tenham relação com as afirmações feitas pelas partes e interessem ao processo
- **Meio de prova**: As partes podem se utilizar de provas nominadas e inominadas, desde que obtidas por meios lícitos
- **Prova do estado das pessoas**: Somente observada a restrição estabelecida na lei civil

### Referências legais
- Art. 231 do CPP
- Art. 479 do CPP
- Art. 400, §1º do CPP

### Jurisprudência
- STJ. 6ª Turma. REsp 1.637.288-SP
- Súmula 74, STJ

### Dicas de prova
- Entenda a liberdade probatória e seus limites
- Conheça as exceções à regra de liberdade probatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 231 do CPP", "Art. 479 do CPP", "Art. 400, §1º do CPP"], "jurisprudence": ["STJ. 6ª Turma. REsp 1.637.288-SP", "Súmula 74, STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T15:57:33.913970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=47", "doc_key": "74e30abff70dcbeab92f597fe45f3417"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'eeb7d6df80e0cbb5ba959ce09f1e55a4a01702b31115825f0b74df3e30bc7a4f'),
  ('cpiuris2025::97dd3d2166fc735178a304acc4a7d0a6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Proteção dos Direitos do Acusado', '## Proteção dos Direitos do Acusado

O texto destaca a importância da proteção dos direitos do acusado, com mecanismos processuais que garantem sua igualdade substancial, como recursos exclusivos da defesa e regra de interpretação in dubio pro reo. Além disso, é mencionada a Lei nº 13.432/17, que disciplina a profissão de detetive particular e permite sua colaboração com investigações policiais, desde autorização expressa do contratante.

### Conceitos
- **Igualdade Substancial**: Direito do acusado à igualdade substancial em relação ao Estado
- **Recursos Exclusivos da Defesa**: Mecanismo processual que permite a defesa apresentar recursos exclusivamente em seu nome
- **Regra de Interpretação In Dubio Pro Reo**: Princípio que favorece o acusado quando há dúvida sobre a interpretação da lei
- **Absolvição por Falta de Provas**: Condição para a absolvição do acusado quando não há provas suficientes para comprovar o crime
- **Reformatio in Pejus**: Mecanismo processual que permite a substituição da defesa por outra, desde que autorizada pela lei

### Referências legais
- Art. 5º, LIV, da CF; Art. 78, § 4º, do CPP; Lei nº 13.432/17

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a importância da igualdade substancial para o acusado
- Conheça os mecanismos processuais que garantem a defesa dos direitos do acusado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 78, § 4º, do CPP; Lei nº 13.432/17"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-28T15:58:32.887736+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=47", "doc_key": "97dd3d2166fc735178a304acc4a7d0a6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8283fa9c22f70c64a1578f6e1ce91465ed04d57c3a11328ea554d6ab2a2d136e'),
  ('cpiuris2025::17e36b9cbcf115490855db0a331e3255', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Garantias do Processo Penal e Princípios Gerais', '## Garantias do Processo Penal e Princípios Gerais

Questões de concursos sobre garantias processuais, princípios gerais e direitos do acusado.

### Conceitos
- **Promotor Natural**: Atribuição de um promotor de Justiça a um caso com base em regras abstratas e preestabelecidas.
- **Garantias Constitucionais**: Direitos do acusado, como o direito à identificação do responsável por sua prisão e ao tempo adequado para preparação da defesa.
- **Nemo Tenetur Se Detegere**: Princípio que proíbe a produção de prova contra si mesmo.
- **Falsas Identidades**: Atribuição de falsa identidade pelo suspeito ou investigado, que pode configurar fato típico.
- **Provas Passivas**: Provas que exijam comportamento passivo do investigado, que não podem ser produzidas sem sua concordância.
- **Direito ao Silêncio**: O direito do acusado e do investigado a permanecerem em silêncio durante o processo.

### Referências legais
- Art. 5º, LIV da Constituição Federal
- Súmula 635/2017 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Garantias Processuais

### Dicas de prova
- Entenda o conceito de Promotor Natural e sua importância no processo penal.
- Conheça as garantias constitucionais do acusado e como elas são aplicadas em casos concretos.
- Aprenda a distinguir entre provas passivas e ativas, e como isso afeta o processo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.48", "page_number": 48, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da Constituição Federal", "Súmula 635/2017 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Garantias Processuais"], "confidence": 0.8, "extracted_at": "2026-05-28T15:59:41.395470+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=48", "doc_key": "17e36b9cbcf115490855db0a331e3255"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'bce1cdfa3d03915f99934e7a851d309039cd7bb2b5262da14029f5595f8bbb56'),
  ('cpiuris2025::d6151377ebba55d4454e7446158d202e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios do Processo Penal', '## Princípios do Processo Penal

Resumo sobre os princípios do processo penal, incluindo o direito ao contraditório e à preparação da defesa.

### Conceitos
- **Contraditório**: Princípio que impõe a possibilidade de ouvir as partes
- **Promotor Natural**: O promotor natural é o advogado do Estado, responsável por representá-lo no processo
- **Direito à Preparação da Defesa**: O acusado tem direito a meios adequados para preparar sua defesa
- **Comunicação da Acusação**: O acusado tem direito de ser comunicado da acusação formulada, embora não seja necessária uma comunicação pormenorizada
- **Direito à Inquirição das Testemunhas**: O acusado tem direito de inquirir as testemunhas de acusação e de obter o comparecimento e a inquirição das testemunhas de defesa

### Referências legais
- Art. 93, IX, da CF
- Súmula 522 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio do contraditório e sua aplicação no processo penal
- Conheça as regras de comunicação da acusação e direito à preparação da defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.49", "page_number": 49, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 93, IX, da CF", "Súmula 522 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T16:00:48.016396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=49", "doc_key": "d6151377ebba55d4454e7446158d202e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '83e4c1d7b7fe1fa7c248afbc0e5085bebb2cdd477843679530da2eedbd802379'),
  ('cpiuris2025::925e4daa45990abdfe739483cb3a650e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Fontes do Direito Processual Penal', '## Fontes do Direito Processual Penal

As fontes do direito processual penal são a origem de onde provém e o seu próprio fundamento jurídico. A fonte máxima é a Constituição, seguida pelas leis e tratados.

### Conceitos
- **Fonte material ou de produção**: A fonte de produção da norma processual, responsável pelo seu processo de elaboração.
- **Fonte formal ou de cognição**: A fonte de cognição da norma processual, responsável por revelar a norma.
- **Fonte material imediata**: Leis e tratados, são as normas propriamente ditas e postas a serem interpretadas e aplicadas.

### Referências legais
- Art. 22, I, da CF/88
- Art. 24, I e XI, da CF/88
- Art. 62, I, ''b'', da CF/88

### Dicas de prova
- Entenda a distinção entre fonte material e fonte formal.
- Conheça as competências das entidades para legislar sobre direito processual penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.51", "page_number": 51, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 22, I, da CF/88", "Art. 24, I e XI, da CF/88", "Art. 62, I, ''b'', da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:01:37.147963+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=51", "doc_key": "925e4daa45990abdfe739483cb3a650e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b570b6512839f4bced2d76d7897966235de9f0deddbf4d48f826c6727a31e589'),
  ('cpiuris2025::8e153cb40dfde30dfe8e79e3cb43fda2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mediatas, indiretas ou supletivas', '## Mediatas, indiretas ou supletivas

Exemplo de tratados de direitos humanos equiparados a emendas constitucionais quando aprovados por meio do procedimento do art. 5º, §3º, da CF/88. Caso rejeitados, ainda assim são incorporados como norma supralegal.

### Conceitos
- **Costume**: Prática reiterada, constante e uniforme, praticada de modo geral e desde que haja um liame subjetivo entre os praticantes.
- **Analogia**: Método jurídico utilizado para decidir casos em que a lei não for aplicável
- **Princípios gerais de direito**: Regras e princípios fundamentais do direito, independentes da legislação específica.

### Referências legais
- Art. 5º, §3º, da CF/88

### Dicas de prova
- Entenda a distinção entre costume e mero hábito.
- Conheça as diferentes formas de suplementação da legislação (secundum legem, praeter legem, contra legem).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, §3º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T16:02:26.308216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=52", "doc_key": "8e153cb40dfde30dfe8e79e3cb43fda2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '30532676ff54a608ff3ca1459aa4ceb42b5238b62733a8c159d84ebf2b238eae')
